-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('8e586fab-625c-52dd-aead-7baff63ae929'::uuid, 'd2f2e4dc-e816-5003-bc11-100d3fcee8fa'::uuid, 'Combien de pays le Danube traverse-t-il ou longe-t-il ?', 'mcq', '["Quatre","Sept","Dix","Quinze"]'::jsonb, 2, 'Dix pays et quatre capitales : Vienne, Bratislava, Budapest, Belgrade.', 1),
    ('9db06fa5-d5fa-5a58-be16-d84c5a377832'::uuid, 'd2f2e4dc-e816-5003-bc11-100d3fcee8fa'::uuid, 'Quel fleuve marque la frontière entre l’Allemagne et la Pologne ?', 'mcq', '["Le Rhin","L’Oder","L’Elbe","Le Main"]'::jsonb, 1, 'La ligne Oder-Neisse, frontière depuis 1945, reconnue définitivement en 1990.', 2),
    ('e098824b-0f2e-5b0f-9be9-68c220a906ae'::uuid, 'd2f2e4dc-e816-5003-bc11-100d3fcee8fa'::uuid, 'Que désigne la « Willkommenskultur » ?', 'mcq', '["Une fête de bienvenue scolaire","La culture de l’accueil des réfugiés en 2015","Une tradition de Noël","Un programme touristique"]'::jsonb, 1, 'Des milliers de bénévoles ont accueilli les réfugiés arrivés en 2015.', 3),
    ('7766ed76-4280-5834-9025-9e954780831e'::uuid, 'd2f2e4dc-e816-5003-bc11-100d3fcee8fa'::uuid, 'Où et quand serait née la Currywurst ?', 'mcq', '["À Munich en 1810","À Berlin en 1949","À Hambourg en 1900","À Vienne en 1955"]'::jsonb, 1, 'Selon la tradition, Herta Heuwer l’a créée à Berlin avec des produits des soldats alliés.', 4),
    ('e6488ad3-9207-5456-b8ed-4cb357a2f14d'::uuid, 'd2f2e4dc-e816-5003-bc11-100d3fcee8fa'::uuid, 'Qu’est-ce que la Fuggerei ?', 'mcq', '["Une banque en ligne","La plus ancienne cité sociale encore habitée","Un marché de Noël","Un château sur le Rhin"]'::jsonb, 1, 'Fondée en 1521 à Augsbourg par Jakob Fugger, elle loge des habitants pour un loyer symbolique.', 5),
    ('02f89761-8a46-50f0-a076-c47f70cf3d76'::uuid, 'd2f2e4dc-e816-5003-bc11-100d3fcee8fa'::uuid, 'Où siège la Banque centrale européenne ?', 'mcq', '["Berlin","Bruxelles","Francfort","Luxembourg"]'::jsonb, 2, 'La BCE (*EZB*) est installée à Francfort-sur-le-Main.', 6),
    ('a0fbc321-ee57-507c-a654-583627b4e0c8'::uuid, 'd2f2e4dc-e816-5003-bc11-100d3fcee8fa'::uuid, '« Nur Bares ist Wahres » exprime…', 'mcq', '["l’attachement à l’argent liquide","le rejet de l’argent","la passion du troc","la confiance dans les banques en ligne"]'::jsonb, 0, 'Mot à mot : seul le liquide est vrai.', 7),
    ('90a1d979-770b-5cf8-abe0-5af2f9e5ebf1'::uuid, 'd2f2e4dc-e816-5003-bc11-100d3fcee8fa'::uuid, 'Le Deutsche Mark a été introduit en…', 'mcq', '["1871","1948","1990","2002"]'::jsonb, 1, 'La réforme monétaire de 1948 lance le miracle économique ouest-allemand.', 8),
    ('09c844c8-c7e6-5109-a1f0-59f267b01bb0'::uuid, 'd2f2e4dc-e816-5003-bc11-100d3fcee8fa'::uuid, 'Que signifie « prägen » ?', 'mcq', '["Payer","Marquer, façonner","Prier","Traverser"]'::jsonb, 1, '*Die Migration hat die Stadt geprägt* : la migration a façonné la ville.', 9),
    ('553e80ec-82a4-5258-b8a4-98ea604f6125'::uuid, 'd2f2e4dc-e816-5003-bc11-100d3fcee8fa'::uuid, 'Le Rhin prend sa source dans les Alpes suisses.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il naît en Suisse et se jette dans la mer du Nord aux Pays-Bas.', 10),
    ('1a01472b-7c01-5eef-b2a7-732675455521'::uuid, 'd2f2e4dc-e816-5003-bc11-100d3fcee8fa'::uuid, 'Que signifie « die Aufnahme » dans le contexte des réfugiés ?', 'mcq', '["L’enregistrement vidéo","L’accueil","Le départ","Le refus"]'::jsonb, 1, '*Aufnahme* a plusieurs sens ; ici, c’est l’accueil.', 11),
    ('46c3ac94-d4e5-51d1-b5ea-90e95e8f8258'::uuid, 'd2f2e4dc-e816-5003-bc11-100d3fcee8fa'::uuid, 'Quel pont symbolise la coopération franco-allemande sur le Rhin ?', 'mcq', '["Le pont de l’Europe entre Strasbourg et Kehl","Le pont de Remagen","Le pont Charles","L’Oberbaumbrücke"]'::jsonb, 0, 'Il relie Strasbourg et Kehl, deux villes autrefois séparées par la frontière.', 12),
    ('a2723c52-3a4d-5ba4-8ba1-db01eec1a727'::uuid, '0d648556-0e3a-5893-bf9a-b6b4901a3040'::uuid, 'Quelle œuvre de Lessing est un texte fondateur de la tolérance ?', 'mcq', '["Faust","Nathan le Sage","Les Brigands","Le Tambour"]'::jsonb, 1, 'La parabole des trois anneaux y met les trois religions sur un pied d’égalité.', 1),
    ('b166612c-5ba7-5684-8184-cbe005435116'::uuid, '0d648556-0e3a-5893-bf9a-b6b4901a3040'::uuid, 'Dans la parabole des anneaux, comment prouver la valeur de sa religion ?', 'mcq', '["Par l’ancienneté","Par sa conduite","Par un miracle","Par un vote"]'::jsonb, 1, 'Aucun anneau ne se distingue : c’est la conduite de chacun qui compte.', 2),
    ('24a0ea05-a7a5-5e57-b51e-731698845f8e'::uuid, '0d648556-0e3a-5893-bf9a-b6b4901a3040'::uuid, 'Que dit l’article 3 de la Loi fondamentale depuis 1994 ?', 'mcq', '["Que le handicap ne doit désavantager personne","Que l’allemand est langue officielle","Que l’école est gratuite","Que le service militaire est obligatoire"]'::jsonb, 0, '« *Niemand darf wegen seiner Behinderung benachteiligt werden.* »', 3),
    ('fc1c7f2f-5b03-5401-98ae-3881982cce3e'::uuid, '0d648556-0e3a-5893-bf9a-b6b4901a3040'::uuid, 'Combien d’associations (Vereine) compte-t-on environ en Allemagne ?', 'mcq', '["6 000","60 000","plus de 600 000","6 millions"]'::jsonb, 2, 'Plus de 600 000 : le *Vereinswesen* est un pilier de la société.', 4),
    ('5ed42282-a545-5a6a-a002-c716283a6936'::uuid, '0d648556-0e3a-5893-bf9a-b6b4901a3040'::uuid, 'Que désigne l’« Inklusion » à l’école ?', 'mcq', '["Des écoles réservées aux élèves handicapés","La scolarisation des élèves handicapés dans les classes ordinaires","Un examen d’entrée","L’apprentissage d’une langue étrangère"]'::jsonb, 1, 'Elle découle de la convention de l’ONU ratifiée en 2009.', 5),
    ('8c29e360-f6ba-5e91-a892-45d03db718e3'::uuid, '0d648556-0e3a-5893-bf9a-b6b4901a3040'::uuid, 'En quelle année le mariage pour tous a-t-il été adopté en Allemagne ?', 'mcq', '["2001","2013","2017","2022"]'::jsonb, 2, 'La *Ehe für alle* est en vigueur depuis octobre 2017.', 6),
    ('d92b4f4a-3ea8-5ada-812a-76c6bd20da3c'::uuid, '0d648556-0e3a-5893-bf9a-b6b4901a3040'::uuid, 'Le paragraphe 175, qui punissait l’homosexualité, a été définitivement supprimé en 1994.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il existait depuis 1871 et avait été durci par les nazis.', 7),
    ('308e01b1-b1a0-562a-981a-a748e8c935cd'::uuid, '0d648556-0e3a-5893-bf9a-b6b4901a3040'::uuid, 'Qui fonde à Berlin en 1919 un institut pionnier de sexologie ?', 'mcq', '["Sigmund Freud","Magnus Hirschfeld","Albert Einstein","Robert Koch"]'::jsonb, 1, 'L’institut de Magnus Hirschfeld a été pillé par les nazis en 1933.', 8),
    ('5f5cf860-191b-5e55-b34a-a56566f23b7d'::uuid, '0d648556-0e3a-5893-bf9a-b6b4901a3040'::uuid, 'Que signifie « benachteiligen » ?', 'mcq', '["Avantager","Défavoriser","Partager","Juger"]'::jsonb, 1, '*der Nachteil* = l’inconvénient : *benachteiligen*, désavantager.', 9),
    ('7a880649-8b6b-55f5-b9fe-e5f876e1e6da'::uuid, '0d648556-0e3a-5893-bf9a-b6b4901a3040'::uuid, 'Comment dit-on « l’égalité des droits » ?', 'mcq', '["die Gleichberechtigung","die Gleichgültigkeit","die Rechtschreibung","die Gleichzeitigkeit"]'::jsonb, 0, '*gleich* (égal) + *Berechtigung* (droit). *Gleichgültigkeit* = indifférence.', 10),
    ('b8296024-e7e1-5490-a40e-84034d1b1e04'::uuid, '0d648556-0e3a-5893-bf9a-b6b4901a3040'::uuid, 'Pourquoi dit-on que le Verein est une école de démocratie ?', 'mcq', '["On y apprend le droit","On y élit, on y vote, on s’y engage","Il est géré par l’État","Il remplace l’école"]'::jsonb, 1, 'Assemblée, bureau élu, votes : le club fonctionne comme une petite démocratie.', 11),
    ('0b072e9e-e031-5980-a376-801c0e1988b1'::uuid, '0d648556-0e3a-5893-bf9a-b6b4901a3040'::uuid, 'Que désigne « das Zusammenleben » ?', 'mcq', '["La vie en couple uniquement","Le vivre-ensemble","La vie en ville","La vie après la mort"]'::jsonb, 1, '*zusammen* (ensemble) + *leben* (vivre).', 12),
    ('472d5008-3cb5-5271-a349-72af0c033887'::uuid, '7d5bf015-a8bc-599e-81c6-eb2ef5061a98'::uuid, 'Quel ministre nazi contrôlait la culture et la propagande ?', 'mcq', '["Heinrich Himmler","Joseph Goebbels","Hermann Göring","Albert Speer"]'::jsonb, 1, 'Goebbels crée dès 1933 la *Reichskulturkammer*.', 1),
    ('346cf9db-9c63-5588-a4a1-019748e149db'::uuid, '7d5bf015-a8bc-599e-81c6-eb2ef5061a98'::uuid, 'Que s’est-il passé le 10 mai 1933 ?', 'mcq', '["L’incendie du Reichstag","Des autodafés de livres","L’exposition Art dégénéré","La nuit de Cristal"]'::jsonb, 1, 'Des étudiants brûlent les livres d’auteurs jugés « non allemands ».', 2),
    ('d7f47444-7e95-55cc-b3a1-ccaef4f95709'::uuid, '7d5bf015-a8bc-599e-81c6-eb2ef5061a98'::uuid, 'Que voulait montrer l’exposition « Entartete Kunst » de 1937 ?', 'mcq', '["La grandeur de l’art moderne","Le ridicule supposé de l’art moderne","L’art des colonies","Les œuvres d’Hitler"]'::jsonb, 1, 'Les nazis y exposaient l’art moderne pour le dénigrer.', 3),
    ('8ba1f89d-cd90-5ef7-929b-9607f10b343e'::uuid, '7d5bf015-a8bc-599e-81c6-eb2ef5061a98'::uuid, 'Qui a réalisé le film « Le Triomphe de la volonté » ?', 'mcq', '["Fritz Lang","Leni Riefenstahl","Marlene Dietrich","Bertolt Brecht"]'::jsonb, 1, 'Film de propagande de 1935 sur le congrès du parti nazi à Nuremberg.', 4),
    ('15034ae9-da85-55bb-83d2-39d51c46f211'::uuid, '7d5bf015-a8bc-599e-81c6-eb2ef5061a98'::uuid, 'Qui a écrit « Là où l’on brûle des livres, on finit par brûler des hommes » ?', 'mcq', '["Goethe","Heinrich Heine","Brecht","Thomas Mann"]'::jsonb, 1, 'Heine l’écrit en 1821, plus d’un siècle avant les autodafés nazis.', 5),
    ('1349088c-27e0-5b6e-81be-48d5e284cb11'::uuid, '7d5bf015-a8bc-599e-81c6-eb2ef5061a98'::uuid, 'Comment Thomas Mann s’adressait-il aux Allemands depuis l’exil ?', 'mcq', '["Par des tracts","Par la radio de la BBC","Par des films","Par la télévision"]'::jsonb, 1, 'Ses discours « Deutsche Hörer! » étaient diffusés par la BBC.', 6),
    ('97bf6ab2-66a2-5e18-9278-d8d8ae81d7fb'::uuid, '7d5bf015-a8bc-599e-81c6-eb2ef5061a98'::uuid, 'Qu’était « Die Pfeffermühle » ?', 'mcq', '["Un journal nazi","Le cabaret antinazi d’Erika Mann","Un film de Riefenstahl","Une maison d’édition de RDA"]'::jsonb, 1, 'Ouvert à Munich en 1933, il a poursuivi en Suisse.', 7),
    ('b2cba937-8bd0-5bee-81b6-316ab891ce0c'::uuid, '7d5bf015-a8bc-599e-81c6-eb2ef5061a98'::uuid, 'Wolf Biermann a été déchu de sa nationalité est-allemande en…', 'mcq', '["1961","1968","1976","1989"]'::jsonb, 2, 'En 1976, pendant une tournée à l’Ouest ; de nombreux artistes ont protesté.', 8),
    ('f85fe96e-804c-5446-9ac8-7bce1f1925af'::uuid, '7d5bf015-a8bc-599e-81c6-eb2ef5061a98'::uuid, 'Que signifie « die Zensur » ?', 'mcq', '["La censure","Le recensement","Le centre","La sentence"]'::jsonb, 0, 'Un mot clé pour parler de l’art sous les dictatures.', 9),
    ('e1d6a6e8-672e-521b-bb06-e485d31b4100'::uuid, '7d5bf015-a8bc-599e-81c6-eb2ef5061a98'::uuid, 'Bertolt Brecht est resté en Allemagne pendant tout le IIIe Reich.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il s’exile dès 1933 : Danemark, puis Finlande et États-Unis.', 10),
    ('29d0977f-4972-507f-aba8-cc2141674cc0'::uuid, '7d5bf015-a8bc-599e-81c6-eb2ef5061a98'::uuid, 'Quels écrivains ouest-allemands d’après-guerre ont reçu le prix Nobel ?', 'mcq', '["Böll et Grass","Goethe et Schiller","Kafka et Rilke","Brecht et Mann"]'::jsonb, 0, 'Heinrich Böll en 1972, Günter Grass en 1999.', 11),
    ('7bda2119-476b-5e24-977b-abe9c9c01bf1'::uuid, '7d5bf015-a8bc-599e-81c6-eb2ef5061a98'::uuid, '« sich der Macht widersetzen » signifie…', 'mcq', '["prendre le pouvoir","s’opposer au pouvoir","servir le pouvoir","fuir le pouvoir"]'::jsonb, 1, '*sich widersetzen* + datif : résister, s’opposer.', 12),
    ('df5a7d28-1b9b-5f2e-952f-7b2215cad31d'::uuid, '8c0956f0-03ac-5c62-9e7a-8ab19b0b97ca'::uuid, 'Qui a mis au point l’imprimerie à caractères mobiles vers 1450 ?', 'mcq', '["Röntgen","Gutenberg","Benz","Koch"]'::jsonb, 1, 'Johannes Gutenberg, à Mayence.', 1),
    ('c54d1b0a-4efd-5997-9959-3e7deabb3114'::uuid, '8c0956f0-03ac-5c62-9e7a-8ab19b0b97ca'::uuid, 'Pour quelle découverte Röntgen a-t-il reçu le premier Nobel de physique ?', 'mcq', '["L’électricité","Les rayons X","La radioactivité","Le téléphone"]'::jsonb, 1, 'Découverts en 1895, les rayons X ont révolutionné la médecine.', 2),
    ('23c2c2e4-a11b-5140-af1a-2ff5120da7d5'::uuid, '8c0956f0-03ac-5c62-9e7a-8ab19b0b97ca'::uuid, 'Quel bacille Robert Koch a-t-il identifié en 1882 ?', 'mcq', '["Celui de la rage","Celui de la tuberculose","Celui de la peste","Celui du choléra seulement"]'::jsonb, 1, 'On parle encore du « bacille de Koch ».', 3),
    ('76240ffa-034b-54f2-b3b8-c9704e15df40'::uuid, '8c0956f0-03ac-5c62-9e7a-8ab19b0b97ca'::uuid, 'Quel rôle Lise Meitner a-t-elle joué ?', 'mcq', '["Elle a inventé l’automobile","Elle a expliqué la fission nucléaire","Elle a découvert l’insuline","Elle a fondé BioNTech"]'::jsonb, 1, 'Avec Otto Frisch, en 1939 ; le Nobel est allé à Otto Hahn seul.', 4),
    ('10f67835-2578-5bf0-bf37-247ef33e1f5f'::uuid, '8c0956f0-03ac-5c62-9e7a-8ab19b0b97ca'::uuid, 'Pourquoi Fritz Haber incarne-t-il le dilemme du savant ?', 'mcq', '["Il a refusé le Nobel","Ses travaux ont servi aux engrais et aux gaz de combat","Il a fui l’Allemagne","Il a inventé la bombe atomique"]'::jsonb, 1, 'L’ammoniac nourrit le monde ; mais Haber a aussi dirigé l’attaque au gaz d’Ypres en 1915.', 5),
    ('bdaf922c-ba9d-5f65-933d-76eebd433f1a'::uuid, '8c0956f0-03ac-5c62-9e7a-8ab19b0b97ca'::uuid, 'Qui a cofondé BioNTech et développé un vaccin à ARN messager ?', 'mcq', '["Lise Meitner","Özlem Türeci et Uğur Şahin","Robert Koch","Carl Benz"]'::jsonb, 1, 'Le couple de chercheurs de Mayence a mis au point le vaccin en 2020.', 6),
    ('b4c9c55d-674b-5761-9836-47d78c95110b'::uuid, '8c0956f0-03ac-5c62-9e7a-8ab19b0b97ca'::uuid, 'Carl Benz a déposé le brevet de l’automobile en 1886.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sa *Motorwagen* est considérée comme la première automobile.', 7),
    ('9afa564c-47cb-5552-9033-c169283ab8fa'::uuid, '8c0956f0-03ac-5c62-9e7a-8ab19b0b97ca'::uuid, 'Que désigne le « Dieselgate » de 2015 ?', 'mcq', '["Une grève des usines","Le trucage des émissions de moteurs diesel","La fin du moteur diesel","Une invention de Rudolf Diesel"]'::jsonb, 1, 'Volkswagen avait truqué les tests de pollution de ses moteurs.', 8),
    ('cd90cecb-5994-52a7-95bc-4d3fd6ff4da8'::uuid, '8c0956f0-03ac-5c62-9e7a-8ab19b0b97ca'::uuid, 'Que signifie « die Verantwortung » ?', 'mcq', '["La réponse","La responsabilité","La vérité","La recherche"]'::jsonb, 1, '*verantworten* = répondre de : un mot clé de l’axe.', 9),
    ('4003337d-c2da-5074-ae1e-fc306992b62f'::uuid, '8c0956f0-03ac-5c62-9e7a-8ab19b0b97ca'::uuid, 'Quelle est la différence entre « erfinden » et « entdecken » ?', 'mcq', '["Aucune","erfinden = inventer, entdecken = découvrir","erfinden = découvrir, entdecken = inventer","entdecken s’emploie seulement pour les pays"]'::jsonb, 1, 'On invente une machine ; on découvre ce qui existait déjà (un bacille, un continent).', 10),
    ('7a14be28-a3c9-57b7-85b4-2887376e593f'::uuid, '8c0956f0-03ac-5c62-9e7a-8ab19b0b97ca'::uuid, 'Quel élément chimique porte le nom de Lise Meitner ?', 'mcq', '["Le meitnerium","L’einsteinium","Le hahnium","Le germanium"]'::jsonb, 0, 'Un hommage tardif à une scientifique longtemps oubliée.', 11),
    ('11004a90-a86e-53e6-8379-be21a491310a'::uuid, '8c0956f0-03ac-5c62-9e7a-8ab19b0b97ca'::uuid, 'Que signifie « der Fortschritt » ?', 'mcq', '["Le recul","Le progrès","La marche","Le pas de côté"]'::jsonb, 1, '*fort* (en avant) + *Schritt* (le pas).', 12),
    ('e8855bb7-d3b2-5be2-973a-11ab1ec8f3ca'::uuid, '75f918fd-9e7a-523b-bfdc-a1a414f8c2fb'::uuid, 'Qui a peint « Le Voyageur contemplant une mer de nuages » ?', 'mcq', '["Albrecht Dürer","Caspar David Friedrich","Egon Schiele","Paul Klee"]'::jsonb, 1, 'Chef-d’œuvre du romantisme allemand, vers 1818.', 1),
    ('e13c4ed1-dd34-5e23-b9ab-dc5f9175fa9f'::uuid, '75f918fd-9e7a-523b-bfdc-a1a414f8c2fb'::uuid, 'Qu’était le Wandervogel ?', 'mcq', '["Un oiseau migrateur protégé","Un mouvement de jeunesse de randonnée","Un parti politique","Une réserve naturelle"]'::jsonb, 1, 'Fondé en 1901, il invitait les jeunes à fuir la ville pour la nature.', 2),
    ('41af5025-c9a4-56c1-9ddb-283001884cfc'::uuid, '75f918fd-9e7a-523b-bfdc-a1a414f8c2fb'::uuid, 'Que signifie le sigle FKK ?', 'mcq', '["La culture du corps libre (naturisme)","Un club de football","Une fédération de randonnée","La réforme des forêts"]'::jsonb, 0, '*Freikörperkultur* : un mouvement né vers 1900, populaire en RDA.', 3),
    ('c26b8e26-bbf2-5cbf-bb6d-e4a050e263d7'::uuid, '75f918fd-9e7a-523b-bfdc-a1a414f8c2fb'::uuid, 'D’où vient le nom « Schrebergarten » ?', 'mcq', '["D’un roi de Saxe","Du médecin Moritz Schreber","D’une ville de Bavière","D’un poète romantique"]'::jsonb, 1, 'Le premier jardin de ce type a été créé à Leipzig en 1864.', 4),
    ('b26966e8-c3aa-548f-bb3a-1ab6088986d2'::uuid, '75f918fd-9e7a-523b-bfdc-a1a414f8c2fb'::uuid, 'Qui a forgé le mot « Nachhaltigkeit » en 1713 ?', 'mcq', '["Goethe","Hans Carl von Carlowitz","Alexander von Humboldt","Caspar David Friedrich"]'::jsonb, 1, 'Un forestier saxon : ne pas couper plus de bois qu’il n’en repousse.', 5),
    ('596a2ad2-64f7-54e3-b2b8-663cb8225fa0'::uuid, '75f918fd-9e7a-523b-bfdc-a1a414f8c2fb'::uuid, 'Quel est le premier parc national allemand (1970) ?', 'mcq', '["La Forêt-Noire","La forêt bavaroise","La Suisse saxonne","Le Harz"]'::jsonb, 1, 'Le *Nationalpark Bayerischer Wald*.', 6),
    ('9dfdde08-565d-540f-8b26-deced0b1ba81'::uuid, '75f918fd-9e7a-523b-bfdc-a1a414f8c2fb'::uuid, 'En quelle année le parti des Verts (die Grünen) a-t-il été fondé ?', 'mcq', '["1968","1980","1990","2000"]'::jsonb, 1, 'Fondé en 1980, il entre au Bundestag en 1983.', 7),
    ('e8aea838-ce33-58cf-a5e3-9098d66d35eb'::uuid, '75f918fd-9e7a-523b-bfdc-a1a414f8c2fb'::uuid, 'Que désignait « das Waldsterben » dans les années 1980 ?', 'mcq', '["La déforestation en Amazonie","La mort des forêts due aux pluies acides","La coupe des sapins de Noël","Un roman romantique"]'::jsonb, 1, 'Cette peur a nourri le mouvement écologiste allemand.', 8),
    ('9418e998-ed9f-5943-a1ea-e5e6d12c7b2e'::uuid, '75f918fd-9e7a-523b-bfdc-a1a414f8c2fb'::uuid, 'Que signifie « nachhaltig » ?', 'mcq', '["Rapide","Durable","Naturel","Dangereux"]'::jsonb, 1, '*nachhaltig* = durable : *eine nachhaltige Entwicklung*.', 9),
    ('70b48439-6645-5634-8413-1ed1aea8bbdb'::uuid, '75f918fd-9e7a-523b-bfdc-a1a414f8c2fb'::uuid, 'Pour les romantiques, la forêt est surtout un lieu de production de bois.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est pour eux un lieu de sentiment, de mystère et d’identité.', 10),
    ('443772e6-13e2-5865-9d90-b0ae4890bf98'::uuid, '75f918fd-9e7a-523b-bfdc-a1a414f8c2fb'::uuid, 'Qu’est-ce qu’une « Datsche » ?', 'mcq', '["Une petite maison de campagne, très répandue en RDA","Un plat de viande","Un parc national","Une randonnée"]'::jsonb, 0, 'Le mot vient du russe *datcha*.', 11),
    ('9502ebd0-5e84-5bcd-bad2-4b0035a1d422'::uuid, '75f918fd-9e7a-523b-bfdc-a1a414f8c2fb'::uuid, 'Comment dit-on « la protection de l’environnement » ?', 'mcq', '["der Umweltschutz","die Umweltschuld","der Naturgarten","die Schutzumwelt"]'::jsonb, 0, '*die Umwelt* (l’environnement) + *der Schutz* (la protection).', 12),
    ('d2faf2cd-bdef-5392-bb34-9877bed4cee8'::uuid, 'c2ea9192-3bca-510e-bac0-3f911bd5bc3b'::uuid, 'Quelle colonie allemande correspond à l’actuelle Namibie ?', 'mcq', '["Deutsch-Ostafrika","Deutsch-Südwestafrika","Kamerun","Togo"]'::jsonb, 1, '*Deutsch-Südwestafrika*, lieu du massacre des Herero et des Nama.', 1),
    ('f05ce275-a482-5691-af9a-483b58ed8be7'::uuid, 'c2ea9192-3bca-510e-bac0-3f911bd5bc3b'::uuid, 'Que réclamait von Bülow en 1897 ?', 'mcq', '["La paix avec la France","Une place au soleil pour l’Allemagne","L’unité allemande","La fin des colonies"]'::jsonb, 1, '« *Ein Platz an der Sonne* » : la revendication d’un empire colonial.', 2),
    ('dfdcc93f-b835-5e9b-babd-840f9ab26c2d'::uuid, 'c2ea9192-3bca-510e-bac0-3f911bd5bc3b'::uuid, 'En quelle année l’Allemagne a-t-elle perdu toutes ses colonies ?', 'mcq', '["1871","1919","1945","1990"]'::jsonb, 1, 'Le traité de Versailles les lui retire.', 3),
    ('b58c6834-8a24-5f4a-992a-85647a2682d8'::uuid, 'c2ea9192-3bca-510e-bac0-3f911bd5bc3b'::uuid, 'En 2021, l’Allemagne a reconnu comme génocide…', 'mcq', '["le massacre des Herero et des Nama","la guerre de 1870","la partition de 1949","la conférence de Berlin"]'::jsonb, 0, 'Commis entre 1904 et 1908 en Namibie.', 4),
    ('4bc0f097-785e-58f0-b19d-e9ef3c3dfca7'::uuid, 'c2ea9192-3bca-510e-bac0-3f911bd5bc3b'::uuid, 'Quel est le rôle du Goethe-Institut ?', 'mcq', '["Former des diplomates","Faire connaître la langue et la culture allemandes","Gérer les musées","Organiser le bac"]'::jsonb, 1, 'Fondé en 1951, il compte plus de 150 instituts dans le monde.', 5),
    ('34e365d6-3df6-5620-a595-19c1a3f36b49'::uuid, 'c2ea9192-3bca-510e-bac0-3f911bd5bc3b'::uuid, 'Qu’est-ce que la Deutsche Welle ?', 'mcq', '["Une chaîne internationale de radio et de télévision","Une vague de migrations","Un parti politique","Une banque"]'::jsonb, 0, 'Elle diffuse en une trentaine de langues.', 6),
    ('a75fbeb2-93e4-5d57-8ef2-f056084a9bab'::uuid, 'c2ea9192-3bca-510e-bac0-3f911bd5bc3b'::uuid, 'Que désigne l’« Ostpolitik » de Willy Brandt ?', 'mcq', '["Une guerre à l’Est","La détente avec les pays de l’Est","La réunification","La colonisation de l’Est"]'::jsonb, 1, 'Brandt a reçu le prix Nobel de la paix en 1971 pour cette politique.', 7),
    ('7fdd38f9-7275-5e08-b376-d2408893a292'::uuid, 'c2ea9192-3bca-510e-bac0-3f911bd5bc3b'::uuid, 'Quel mot Olaf Scholz a-t-il employé en février 2022 ?', 'mcq', '["Wende","Zeitenwende","Wiedervereinigung","Wirtschaftswunder"]'::jsonb, 1, '« Changement d’époque » après l’invasion de l’Ukraine.', 8),
    ('ff329f3c-fe7d-5b79-ade4-6ba628891a53'::uuid, 'c2ea9192-3bca-510e-bac0-3f911bd5bc3b'::uuid, 'Germantown, fondée en 1683, se trouve…', 'mcq', '["en Namibie","en Pennsylvanie","au Brésil","en Australie"]'::jsonb, 1, 'Une des premières implantations allemandes en Amérique.', 9),
    ('a83c181e-8b75-5fc5-87ce-0235ba60701c'::uuid, 'c2ea9192-3bca-510e-bac0-3f911bd5bc3b'::uuid, 'Que signifie « die Außenpolitik » ?', 'mcq', '["La politique étrangère","La politique intérieure","La politique locale","L’opposition"]'::jsonb, 0, '*außen* = dehors ; *Innenpolitik* = politique intérieure.', 10),
    ('4e0f4a2e-297e-54d4-aff3-dbfc33cd665a'::uuid, 'c2ea9192-3bca-510e-bac0-3f911bd5bc3b'::uuid, 'La Bundeswehr intervient à l’étranger depuis sa création en 1955.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ses premières interventions armées à l’étranger datent des années 1990.', 11),
    ('9273e375-297b-5471-949e-5c6a566805ed'::uuid, 'c2ea9192-3bca-510e-bac0-3f911bd5bc3b'::uuid, 'Quelle préposition suit « der Einfluss » ?', 'mcq', '["auf","an","für","von"]'::jsonb, 0, '*Einfluss haben auf* + accusatif : avoir de l’influence sur.', 12),
    ('d2803193-68ac-597f-a26e-e23de330e319'::uuid, '0862746e-9ab3-5f5d-8642-2c746593dddf'::uuid, 'Comment dit-on « j’avais mangé » ?', 'mcq', '["ich habe gegessen","ich hatte gegessen","ich hätte gegessen","ich aß"]'::jsonb, 1, 'Prétérit de *haben* + participe : plus-que-parfait.', 1),
    ('b1aa3141-e2ad-5623-850d-e57c5f2f1aa8'::uuid, '0862746e-9ab3-5f5d-8642-2c746593dddf'::uuid, 'Comment dit-on « il était parti » ?', 'mcq', '["er hatte gegangen","er war gegangen","er ist gegangen","er wäre gegangen"]'::jsonb, 1, '*gehen* prend *sein* : *war gegangen*.', 2),
    ('9315d4fa-bc1c-5173-be13-dc3387c3e273'::uuid, '0862746e-9ab3-5f5d-8642-2c746593dddf'::uuid, '« Nachdem er gegessen ___, ging er schlafen. » Quel mot complète la phrase ?', 'mcq', '["hat","hatte","hätte","ist"]'::jsonb, 1, 'Principale au prétérit : la subordonnée en *nachdem* passe au plus-que-parfait.', 3),
    ('608eb05b-a220-5b0c-bb8b-25519f9d2be2'::uuid, '0862746e-9ab3-5f5d-8642-2c746593dddf'::uuid, 'Avec « nachdem » et une principale au présent, la subordonnée est au…', 'mcq', '["présent","parfait","plus-que-parfait","futur"]'::jsonb, 1, 'Le décalage : un cran plus loin dans le passé que la principale.', 4),
    ('55aa1f36-bede-5c40-b026-5b149429142a'::uuid, '0862746e-9ab3-5f5d-8642-2c746593dddf'::uuid, 'Après « bevor », faut-il décaler les temps ?', 'mcq', '["Oui, toujours","Non, même temps que la principale","Seulement au futur","Seulement à l’écrit"]'::jsonb, 1, '*Bevor ich ging, las ich noch* : même temps des deux côtés.', 5),
    ('c403f967-7b7e-56be-9570-b173133da78c'::uuid, '0862746e-9ab3-5f5d-8642-2c746593dddf'::uuid, 'Quel mot est un adverbe (et provoque l’inversion) ?', 'mcq', '["nachdem","nach","nachher","bevor"]'::jsonb, 2, '*Nachher gehen wir ins Kino* : adverbe en 1re position, verbe 2e.', 6),
    ('28b4c8c2-cab5-5b2f-b124-1ee1e6cf7b3a'::uuid, '0862746e-9ab3-5f5d-8642-2c746593dddf'::uuid, 'Comment traduire « avant de partir, je t’appelle » ?', 'mcq', '["Vor zu gehen, rufe ich dich an.","Bevor ich gehe, rufe ich dich an.","Bevor zu gehen, ich rufe dich an.","Vorher ich gehe, rufe ich dich an."]'::jsonb, 1, '« Avant de » se rend par *bevor* + verbe conjugué.', 7),
    ('20b4203e-b7f6-59d4-8481-8ba08658df4f'::uuid, '0862746e-9ab3-5f5d-8642-2c746593dddf'::uuid, '« Als ich ankam, war der Zug schon abgefahren » : quelle action a eu lieu en premier ?', 'mcq', '["L’arrivée","Le départ du train","Les deux en même temps","On ne peut pas le savoir"]'::jsonb, 1, 'Le plus-que-parfait *war abgefahren* marque l’antériorité.', 8),
    ('f942485e-8abe-5f57-b507-34d575e85a2f'::uuid, '0862746e-9ab3-5f5d-8642-2c746593dddf'::uuid, 'Avec « nachdem », on peut mettre le même temps dans les deux propositions.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*nachdem* impose toujours un décalage de temps.', 9),
    ('22b13450-6b0a-5a5b-8cc2-608d1149e6fb'::uuid, '0862746e-9ab3-5f5d-8642-2c746593dddf'::uuid, 'Quelle préposition exprime « après le repas » ?', 'mcq', '["nachdem dem Essen","nach dem Essen","nachher dem Essen","danach Essen"]'::jsonb, 1, '*nach* + datif : *nach dem Essen*.', 10),
    ('6f019499-9145-5d3f-8be9-655c3f44a80f'::uuid, '0862746e-9ab3-5f5d-8642-2c746593dddf'::uuid, 'Comment traduire « Après avoir visité le musée, nous sommes allés au café » ?', 'mcq', '["Nach besucht das Museum gingen wir ins Café.","Nachdem wir das Museum besucht hatten, gingen wir ins Café.","Nachdem wir das Museum besuchten, gingen wir ins Café.","Nachher wir das Museum besucht hatten, gingen wir ins Café."]'::jsonb, 1, 'Subordonnée au plus-que-parfait, principale au prétérit.', 11),
    ('bdc88966-e249-5152-89d5-8dad6413eea9'::uuid, '0862746e-9ab3-5f5d-8642-2c746593dddf'::uuid, 'Que signifie « vorher » ?', 'mcq', '["Après","Auparavant","Pendant","Ensuite"]'::jsonb, 1, '*vorher* = avant, auparavant ; *nachher* = après.', 12),
    ('a68a83b3-c224-53bc-9d7e-bb9415659ffe'::uuid, 'f657db59-f844-5dc1-a21d-a3b39c7c3d68'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Ich helfe meinen Bruder.","Ich helfe meinem Bruder.","Ich helfe mein Bruder.","Ich helfe meines Bruders."]'::jsonb, 1, '*helfen* régit le datif : *meinem Bruder*.', 1),
    ('261d15ce-3030-5fb0-ba3a-5497670f1af4'::uuid, 'f657db59-f844-5dc1-a21d-a3b39c7c3d68'::uuid, 'Comment dit-on « Le film me plaît » ?', 'mcq', '["Der Film gefällt mich.","Der Film gefällt mir.","Ich gefalle den Film.","Mir gefällt mich der Film."]'::jsonb, 1, '*gefallen* + datif : la personne à qui ça plaît est au datif.', 2),
    ('b428b3f7-39cd-50a5-b182-85abbc5358fd'::uuid, 'f657db59-f844-5dc1-a21d-a3b39c7c3d68'::uuid, 'Quel verbe se construit avec l’accusatif de la personne ?', 'mcq', '["danken","helfen","fragen","antworten"]'::jsonb, 2, '*Ich frage den Lehrer* : accusatif, alors que le français dit « demander à ».', 3),
    ('4b69f595-ab03-5a98-8bde-4bef344efa70'::uuid, 'f657db59-f844-5dc1-a21d-a3b39c7c3d68'::uuid, '« Ich danke ___ für die Einladung. » (vous, politesse) Quel mot complète la phrase ?', 'mcq', '["Sie","Ihnen","Ihr","Ihre"]'::jsonb, 1, '*danken* + datif : *Ihnen*.', 4),
    ('25ea19d6-d1a9-5c36-92f8-85118b836522'::uuid, 'f657db59-f844-5dc1-a21d-a3b39c7c3d68'::uuid, 'Comment dit-on « Il me demande de l’aide » ?', 'mcq', '["Er bittet mir um Hilfe.","Er bittet mich um Hilfe.","Er fragt mir Hilfe.","Er bittet mich für Hilfe."]'::jsonb, 1, '*jn um etwas bitten* : accusatif de la personne, *um* pour la chose.', 5),
    ('55637263-0cd8-5d8e-be09-4c2080ee50ff'::uuid, 'f657db59-f844-5dc1-a21d-a3b39c7c3d68'::uuid, 'Dans « Ich erkläre dem Schüler die Regel », quel est le cas de « dem Schüler » ?', 'mcq', '["Nominatif","Accusatif","Datif","Génitif"]'::jsonb, 2, 'La personne à qui l’on explique est au datif.', 6),
    ('6491fa6c-eb58-5720-9fe7-b711104d1309'::uuid, 'f657db59-f844-5dc1-a21d-a3b39c7c3d68'::uuid, '« Das Buch gehört ___ Schwester. » Quel mot complète la phrase ?', 'mcq', '["meine","meiner","meinen","meines"]'::jsonb, 1, '*gehören* + datif ; *Schwester* est féminin : *meiner*.', 7),
    ('315d4e02-3831-59cb-b1dc-8d0685b675bb'::uuid, 'f657db59-f844-5dc1-a21d-a3b39c7c3d68'::uuid, 'Comment dit-on « je me lave les mains » ?', 'mcq', '["Ich wasche mich die Hände.","Ich wasche mir die Hände.","Ich wasche meine Hände mich.","Ich wasche die Hände mir mich."]'::jsonb, 1, 'Le COD est *die Hände* : le réfléchi passe au datif, *mir*.', 8),
    ('804677fe-314e-56b1-b024-fa219a929478'::uuid, 'f657db59-f844-5dc1-a21d-a3b39c7c3d68'::uuid, '« glauben » se construit avec le datif quand on croit une personne.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ich glaube dir* : je te crois. Pour une chose : *Ich glaube das.*', 9),
    ('e2053910-8162-542f-9d6d-c81f7d7dff03'::uuid, 'f657db59-f844-5dc1-a21d-a3b39c7c3d68'::uuid, '« Er ist sich der Gefahr bewusst » : quel est le cas de « der Gefahr » ?', 'mcq', '["Datif","Génitif","Accusatif","Nominatif"]'::jsonb, 1, '*sich einer Sache bewusst sein* régit le génitif.', 10),
    ('9039c3ba-09eb-5ada-9573-149eded9384a'::uuid, 'f657db59-f844-5dc1-a21d-a3b39c7c3d68'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Ich rufe dir morgen an.","Ich rufe dich morgen an.","Ich rufe morgen an dich.","Ich anrufe dich morgen."]'::jsonb, 1, '*anrufen* + accusatif, et le préverbe *an* en fin de phrase.', 11),
    ('5c3dc030-7f5d-5cf9-b14a-cf78b817ec42'::uuid, 'f657db59-f844-5dc1-a21d-a3b39c7c3d68'::uuid, 'Que signifie « Er widerspricht seinem Vater » ?', 'mcq', '["Il obéit à son père","Il contredit son père","Il parle de son père","Il répond à son père"]'::jsonb, 1, '*widersprechen* + datif : contredire.', 12),
    ('79f6ee98-e728-53e0-853e-3bd241f647cb'::uuid, 'ae3cc94c-6018-557d-96be-e736ba1cd0c3'::uuid, 'Que signifie « umziehen » ?', 'mcq', '["Se déshabiller seulement","Déménager","Retourner","Tirer"]'::jsonb, 1, '*um-* marque le changement : changer de logement (aussi « se changer »).', 1),
    ('33ae08e2-1bae-54f7-b5c2-a183d6905db3'::uuid, 'ae3cc94c-6018-557d-96be-e736ba1cd0c3'::uuid, 'Que signifie « einwandern » ?', 'mcq', '["Émigrer","Immigrer","Randonner","Revenir"]'::jsonb, 1, '*ein-* = vers l’intérieur : entrer dans un pays pour y vivre.', 2),
    ('86816c3e-b680-526d-a5ce-fed6e84e4702'::uuid, 'ae3cc94c-6018-557d-96be-e736ba1cd0c3'::uuid, 'Quel préverbe exprime la destruction en morceaux ?', 'mcq', '["ent-","zer-","er-","be-"]'::jsonb, 1, '*zerstören*, *zerbrechen* : détruire, briser.', 3),
    ('cdfb58e0-8c0b-562c-8426-23377619b03c'::uuid, 'ae3cc94c-6018-557d-96be-e736ba1cd0c3'::uuid, '« erneuern » est formé sur…', 'mcq', '["le verbe nennen","l’adjectif neu","le nom Nerv","le verbe nehmen"]'::jsonb, 1, '*er-* + *neu* : rendre neuf, renouveler.', 4),
    ('4858ffdf-4f19-51c9-b7c2-9675c21b724d'::uuid, 'ae3cc94c-6018-557d-96be-e736ba1cd0c3'::uuid, 'Que signifie « sich verlaufen » ?', 'mcq', '["Se promener","Se perdre","Courir vite","Se sauver"]'::jsonb, 1, '*ver-* marque ici l’erreur : marcher dans la mauvaise direction.', 5),
    ('7cf3bac6-ef60-5c5a-829d-f50e092820c4'::uuid, 'ae3cc94c-6018-557d-96be-e736ba1cd0c3'::uuid, 'Quel est le participe II de « verändern » ?', 'mcq', '["geverändert","verändert","vergeändert","veränderte"]'::jsonb, 1, 'Préverbe inséparable : pas de *ge-*.', 6),
    ('512b9dab-e386-5a9d-946c-2cc4fab2c7e7'::uuid, 'ae3cc94c-6018-557d-96be-e736ba1cd0c3'::uuid, '« umdenken » signifie…', 'mcq', '["penser à quelqu’un","changer sa façon de penser","réfléchir longtemps","oublier"]'::jsonb, 1, '*um-* (changement) + *denken* (penser).', 7),
    ('3269b584-cef7-50d9-a46e-142ce9d4411f'::uuid, 'ae3cc94c-6018-557d-96be-e736ba1cd0c3'::uuid, '« be- » transforme souvent un verbe à préposition en verbe transitif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*auf eine Frage antworten* → *eine Frage beantworten*.', 8),
    ('c95b7b5b-f842-519d-9776-d11c8d2ad1dd'::uuid, 'ae3cc94c-6018-557d-96be-e736ba1cd0c3'::uuid, 'Que signifie « sich zurückhalten » ?', 'mcq', '["Se retenir","Revenir","Retenir quelqu’un","Se retourner"]'::jsonb, 0, '*zurück-* (en arrière) + *halten* (tenir) : se retenir, rester en retrait.', 9),
    ('aaf2c60e-2390-5050-bbcc-b2199b585576'::uuid, 'ae3cc94c-6018-557d-96be-e736ba1cd0c3'::uuid, 'Que signifie « entdecken » ?', 'mcq', '["Couvrir","Découvrir","Décorer","Détruire"]'::jsonb, 1, '*ent-* (retrait) + *decken* (couvrir) : ôter la couverture, découvrir.', 10),
    ('fc6f0b97-66b2-57b8-b9f1-9239d32098f4'::uuid, 'ae3cc94c-6018-557d-96be-e736ba1cd0c3'::uuid, 'Que signifie « missverstehen » ?', 'mcq', '["Comprendre parfaitement","Mal comprendre","Ne pas entendre","Expliquer"]'::jsonb, 1, '*miss-* = de travers.', 11),
    ('40fb7a99-0b28-56ed-a8be-30be6a9e05a3'::uuid, 'ae3cc94c-6018-557d-96be-e736ba1cd0c3'::uuid, 'Dans « Ich steige in Köln um », que fait le locuteur ?', 'mcq', '["Il descend définitivement","Il change de train","Il monte dans le train","Il rate son train"]'::jsonb, 1, '*umsteigen* : changer (de train, de bus).', 12),
    ('eddba7e4-39c3-5c2d-944b-36b1777f9114'::uuid, '3db4e2a4-f57f-5d41-a893-c4178e7b011c'::uuid, 'Comment traduire « en mangeant » ?', 'mcq', '["beim Essen","bei essen","während essen","mit Essen"]'::jsonb, 0, '*beim* + infinitif substantivé, avec majuscule.', 1),
    ('eb768769-0044-54b4-b70d-13c587b6bf44'::uuid, '3db4e2a4-f57f-5d41-a893-c4178e7b011c'::uuid, '« Während ich arbeite, ___ er. » Quelle forme complète la phrase ?', 'mcq', '["er schläft","schläft","schlafen","geschlafen"]'::jsonb, 1, 'La subordonnée en tête occupe la 1re place : le verbe de la principale suit immédiatement.', 2),
    ('5df96a3e-9147-5bfe-ac20-55a7eef52e79'::uuid, '3db4e2a4-f57f-5d41-a893-c4178e7b011c'::uuid, 'Après la préposition « während », quel cas emploie-t-on ?', 'mcq', '["Le datif","Le génitif","L’accusatif","Le nominatif"]'::jsonb, 1, '*während des Unterrichts* : génitif.', 3),
    ('ba3832f9-bb79-5c52-9afc-2d6410bb89ad'::uuid, '3db4e2a4-f57f-5d41-a893-c4178e7b011c'::uuid, 'Dans « Während Paul Sport liebt, liest seine Schwester lieber », « während » a un sens…', 'mcq', '["temporel","adversatif (tandis que)","causal","final"]'::jsonb, 1, 'Les deux actions s’opposent : tandis que.', 4),
    ('fbaaf2e0-fdab-5650-a6b1-1db217d31abf'::uuid, '3db4e2a4-f57f-5d41-a893-c4178e7b011c'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Gleichzeitig sie telefoniert.","Gleichzeitig telefoniert sie.","Gleichzeitig sie telefonieren.","Sie gleichzeitig telefoniert."]'::jsonb, 1, 'Adverbe en tête : inversion, verbe 2e.', 5),
    ('586bd239-081d-57cf-be5a-f3b44e7dac3f'::uuid, '3db4e2a4-f57f-5d41-a893-c4178e7b011c'::uuid, '« Als » s’emploie pour…', 'mcq', '["une action répétée","une action unique dans le passé","le futur","une condition"]'::jsonb, 1, '*Als ich klein war* : un moment unique du passé.', 6),
    ('22832b9c-cdf0-5a11-8da1-268b44cde501'::uuid, '3db4e2a4-f57f-5d41-a893-c4178e7b011c'::uuid, '« ___ ich ihn sehe, lacht er. » (chaque fois) Quel mot complète la phrase ?', 'mcq', '["Als","Wenn","Während","Beim"]'::jsonb, 1, 'Répétition : *(immer) wenn*.', 7),
    ('16dbd191-3680-5f23-b209-f72dca82415a'::uuid, '3db4e2a4-f57f-5d41-a893-c4178e7b011c'::uuid, 'Dans « beim Lesen », « Lesen » prend une majuscule parce que c’est un nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’infinitif substantivé est un nom neutre : majuscule.', 8),
    ('bb7b6197-99cb-5981-abb0-4d651326bbf9'::uuid, '3db4e2a4-f57f-5d41-a893-c4178e7b011c'::uuid, 'Que signifie « solange es regnet » ?', 'mcq', '["Depuis qu’il pleut","Tant qu’il pleut","Avant qu’il pleuve","Bien qu’il pleuve"]'::jsonb, 1, '*solange* = tant que.', 9),
    ('9bd94e9c-936d-5f4f-abab-a80b4e4aba7a'::uuid, '3db4e2a4-f57f-5d41-a893-c4178e7b011c'::uuid, 'Que signifie « währenddessen » ?', 'mcq', '["Pendant ce temps","Pourtant","Ensuite","Depuis"]'::jsonb, 0, 'Adverbe : *währenddessen* reprend la simultanéité.', 10),
    ('f54a59cf-84de-50fa-803a-a3ff4952ed64'::uuid, '3db4e2a4-f57f-5d41-a893-c4178e7b011c'::uuid, 'Comment dit-on « en conduisant » ?', 'mcq', '["beim Autofahren","bei Autofahren","während Autofahren","im Autofahrt"]'::jsonb, 0, '*beim* + infinitif substantivé : *beim Autofahren*.', 11),
    ('0bc97abd-0351-5ff5-bac9-3bbc45474fd4'::uuid, '3db4e2a4-f57f-5d41-a893-c4178e7b011c'::uuid, 'Quel mot est un adverbe synonyme de « gleichzeitig » ?', 'mcq', '["während","zugleich","solange","als"]'::jsonb, 1, '*zugleich* = en même temps ; les autres sont des subordonnants.', 12),
    ('34331cfe-44b2-5c69-a1e2-aff489687a2d'::uuid, '46d576ab-b237-5d4c-80a6-306182267c01'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Obwohl es regnet, wir gehen spazieren.","Obwohl es regnet, gehen wir spazieren.","Obwohl regnet es, gehen wir spazieren.","Obwohl es regnet, spazieren wir gehen."]'::jsonb, 1, 'Subordonnée en tête, puis verbe de la principale, puis sujet.', 1),
    ('4dbf8716-bff4-5e32-afde-e48a1d52f6e2'::uuid, '46d576ab-b237-5d4c-80a6-306182267c01'::uuid, 'Quelle est la nature de « trotzdem » ?', 'mcq', '["Subordonnant","Adverbe","Préposition","Coordonnant"]'::jsonb, 1, 'Adverbe : il occupe la 1re place et provoque l’inversion.', 2),
    ('1f55fafc-d875-5413-8244-a1719ac0021c'::uuid, '46d576ab-b237-5d4c-80a6-306182267c01'::uuid, 'Que signifie « trotz des Regens » ?', 'mcq', '["À cause de la pluie","Malgré la pluie","Pendant la pluie","Après la pluie"]'::jsonb, 1, '*trotz* + génitif : malgré.', 3),
    ('1224195f-3bb2-514b-a506-2a74f621ca53'::uuid, '46d576ab-b237-5d4c-80a6-306182267c01'::uuid, '« Das ist ___ teuer, aber praktisch. » Quel mot complète la phrase ?', 'mcq', '["zwar","trotzdem","obwohl","sondern"]'::jsonb, 0, '*zwar … aber* : certes… mais.', 4),
    ('d89e04e7-74e7-576e-934c-956921bf8f9d'::uuid, '46d576ab-b237-5d4c-80a6-306182267c01'::uuid, 'Que signifie « dagegen » dans « Bonn dagegen ist klein » ?', 'mcq', '["Contre cela","En revanche","De plus","Donc"]'::jsonb, 1, '*dagegen* marque l’opposition entre deux éléments.', 5),
    ('5bb9fb80-dca7-5437-b0f4-e74678f41dbf'::uuid, '46d576ab-b237-5d4c-80a6-306182267c01'::uuid, 'Que signifie l’abréviation « bzw. » ?', 'mcq', '["Par exemple","Beziehungsweise : ou plutôt, respectivement","C’est-à-dire","Et cetera"]'::jsonb, 1, '*beziehungsweise* précise ou distribue.', 6),
    ('b6c00879-a3c9-5419-8cda-440bed5e4963'::uuid, '46d576ab-b237-5d4c-80a6-306182267c01'::uuid, 'Que signifie « übrigens » ?', 'mcq', '["D’ailleurs, au fait","Ensuite","Pourtant","Finalement"]'::jsonb, 0, 'Il introduit une remarque en passant.', 7),
    ('c61a7b7d-aba5-58ca-9066-8cae54147194'::uuid, '46d576ab-b237-5d4c-80a6-306182267c01'::uuid, 'Après « außerdem » en tête de phrase, le sujet se place après le verbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Außerdem ist das teuer* : adverbe en 1re position, inversion.', 8),
    ('f9222717-9d23-5805-9594-eb4fa5264f85'::uuid, '46d576ab-b237-5d4c-80a6-306182267c01'::uuid, 'Comment dit-on « même si » ?', 'mcq', '["obwohl","auch wenn","wenn auch nicht","sogar"]'::jsonb, 1, '*auch wenn* : concession hypothétique.', 9),
    ('d64cd830-20d5-5533-9cef-786944fb8d82'::uuid, '46d576ab-b237-5d4c-80a6-306182267c01'::uuid, '« Das ist nicht teuer, ___ billig. » Quel mot complète la phrase ?', 'mcq', '["aber","sondern","dagegen","trotzdem"]'::jsonb, 1, 'Après une négation, « mais au contraire » se dit *sondern*.', 10),
    ('5cda4010-601c-5fbe-a437-c2a4edf91530'::uuid, '46d576ab-b237-5d4c-80a6-306182267c01'::uuid, 'Quelle expression sert à conclure ?', 'mcq', '["Einerseits","Zusammenfassend kann man sagen, dass…","Zum Beispiel","Außerdem"]'::jsonb, 1, 'Pour conclure : *zusammenfassend*, en résumé.', 11),
    ('bebd410c-bbd5-516a-9cbc-67328a7bd2ad'::uuid, '46d576ab-b237-5d4c-80a6-306182267c01'::uuid, 'Que signifie « d. h. » ?', 'mcq', '["das heißt : c’est-à-dire","der Hauptsatz","durchaus hier","dort hinten"]'::jsonb, 0, '*das heißt* introduit une reformulation.', 12),
    ('4aebda0b-50c9-5404-be1c-55b8921820fb'::uuid, '0b2bba3c-233f-5119-80b6-51ae8a0741b0'::uuid, 'Que signifie « Er muss krank sein » ?', 'mcq', '["Il est obligé d’être malade","Il est sûrement malade","Il n’est pas malade","Il veut être malade"]'::jsonb, 1, 'Emploi subjectif : le locuteur est presque certain.', 1),
    ('b7a0767a-03f8-531c-b18f-95a3078e3203'::uuid, '0b2bba3c-233f-5119-80b6-51ae8a0741b0'::uuid, 'Quel modal exprime une forte probabilité, un peu moins sûre que « muss » ?', 'mcq', '["darf","dürfte","soll","will"]'::jsonb, 1, '*Er dürfte zu Hause sein* : il est sans doute chez lui.', 2),
    ('8f9b5625-7531-5557-b7b4-752acc979e6c'::uuid, '0b2bba3c-233f-5119-80b6-51ae8a0741b0'::uuid, '« Das mag sein, aber… » sert à…', 'mcq', '["exprimer un goût","concéder avant de réfuter","donner un ordre","exprimer un souhait"]'::jsonb, 1, 'C’est possible, mais… : une formule de concession.', 3),
    ('f2e944e0-53a5-54b2-86fb-e467cf347657'::uuid, '0b2bba3c-233f-5119-80b6-51ae8a0741b0'::uuid, 'Comment dit-on « Il a dû être malade » (supposition) ?', 'mcq', '["Er musste krank sein.","Er muss krank gewesen sein.","Er hat krank sein müssen.","Er muss krank war."]'::jsonb, 1, 'Modal au présent + infinitif passé : *krank gewesen sein*.', 4),
    ('1dec1ccc-b0ac-527f-b109-8a3bd99c4406'::uuid, '0b2bba3c-233f-5119-80b6-51ae8a0741b0'::uuid, '« Das kann nicht sein! » signifie…', 'mcq', '["Ce n’est pas possible !","Il ne peut pas venir","Ça ne peut pas attendre","Ce n’est pas permis"]'::jsonb, 0, '*kann nicht* dans son emploi subjectif : impossible.', 5),
    ('d011b302-2ac3-5cbb-a675-fd3a6acb3699'::uuid, '0b2bba3c-233f-5119-80b6-51ae8a0741b0'::uuid, 'Que signifie « Er muss nicht kommen » ?', 'mcq', '["Il ne doit pas venir (interdit)","Il n’est pas obligé de venir","Il ne viendra pas","Il ne peut pas venir"]'::jsonb, 1, 'L’interdiction se dit *darf nicht*.', 6),
    ('b2d63acc-b4c0-58da-a16b-93f149d751bc'::uuid, '0b2bba3c-233f-5119-80b6-51ae8a0741b0'::uuid, '« Sie kann den Bus verpasst ___. » Quel mot complète la phrase ?', 'mcq', '["hat","haben","hatte","gehabt"]'::jsonb, 1, 'Infinitif passé : participe + *haben* à l’infinitif.', 7),
    ('f5afef37-c7e3-5874-855a-32557827e10b'::uuid, '0b2bba3c-233f-5119-80b6-51ae8a0741b0'::uuid, 'Quel adverbe équivaut à l’emploi subjectif de « muss » ?', 'mcq', '["vielleicht","kaum","bestimmt","nie"]'::jsonb, 2, '*bestimmt*, *sicher* : certainement.', 8),
    ('d24608d8-9fb8-5573-8287-6bae369f6960'::uuid, '0b2bba3c-233f-5119-80b6-51ae8a0741b0'::uuid, 'Dans « Er muss arbeiten », le modal a un emploi objectif (obligation).', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ici, c’est une obligation qui pèse sur le sujet.', 9),
    ('e76d7687-dbe3-5192-8406-bf86ae28fc5c'::uuid, '0b2bba3c-233f-5119-80b6-51ae8a0741b0'::uuid, '« Das könnte stimmen » exprime…', 'mcq', '["une certitude","une possibilité","une interdiction","un ordre"]'::jsonb, 1, '*könnte* : ça pourrait être vrai.', 10),
    ('ad126b01-7346-5291-850b-c0e3654dfc1f'::uuid, '0b2bba3c-233f-5119-80b6-51ae8a0741b0'::uuid, 'Que signifie « wahrscheinlich » ?', 'mcq', '["Vraiment","Probablement","Heureusement","Rarement"]'::jsonb, 1, '*wahrscheinlich* = probablement.', 11),
    ('8288366b-713f-5054-90f2-6a7f9909b7c0'::uuid, '0b2bba3c-233f-5119-80b6-51ae8a0741b0'::uuid, 'Comment dire « Ça a dû être difficile » ?', 'mcq', '["Das dürfte schwierig gewesen sein.","Das durfte schwierig sein.","Das hat schwierig sein dürfen.","Das dürfte schwierig war."]'::jsonb, 0, 'Modal subjectif + infinitif passé.', 12),
    ('8a3cf371-b342-52c4-9e36-bf2ef1aa09b6'::uuid, 'd4a8b1f2-b245-557c-81a6-230840765237'::uuid, 'Quelles sont les couleurs du drapeau allemand ?', 'mcq', '["Noir, rouge, or","Rouge, blanc, rouge","Noir, blanc, rouge","Bleu, blanc, rouge"]'::jsonb, 0, 'Le noir-rouge-or remonte à la révolution démocratique de 1848.', 1),
    ('2ddf228e-7729-52b6-96d7-486d87f3a9ba'::uuid, 'd4a8b1f2-b245-557c-81a6-230840765237'::uuid, 'L’hymne allemand actuel est…', 'mcq', '["la première strophe du Deutschlandlied","la troisième strophe du Deutschlandlied","l’Ode à la joie","un chant composé en 1990"]'::jsonb, 1, 'Seule la troisième strophe (« *Einigkeit und Recht und Freiheit* ») est chantée depuis la RFA.', 2),
    ('f3797a40-cc63-557a-a005-0c5de5ff240b'::uuid, 'd4a8b1f2-b245-557c-81a6-230840765237'::uuid, 'Pourquoi Dürer choque-t-il en 1500 avec son autoportrait ?', 'mcq', '["Il se peint nu","Il prend une pose réservée au Christ","Il se peint en roi","Il se peint en caricature"]'::jsonb, 1, 'De face, main sur la poitrine : l’artiste revendique la dignité de créateur.', 3),
    ('849e7e76-b8df-5759-a783-a91b53855cd0'::uuid, 'd4a8b1f2-b245-557c-81a6-230840765237'::uuid, 'Egon Schiele était un peintre…', 'mcq', '["suisse","autrichien","bavarois","prussien"]'::jsonb, 1, 'Figure de l’expressionnisme viennois, mort en 1918 à 28 ans.', 4),
    ('7606c2b6-5fd0-5292-b9bc-302d1002ce1f'::uuid, 'd4a8b1f2-b245-557c-81a6-230840765237'::uuid, 'Le Dirndl et la Lederhose sont des costumes traditionnels…', 'mcq', '["de la Frise","de Bavière et d’Autriche","de Berlin","de Saxe"]'::jsonb, 1, 'Ce sont les *Trachten* de l’espace alpin, portées notamment à l’Oktoberfest.', 5),
    ('3ec5441c-3225-59f4-aa7e-fd84232dee25'::uuid, 'd4a8b1f2-b245-557c-81a6-230840765237'::uuid, 'Que signifie « das Vorurteil » ?', 'mcq', '["Le préjugé","Le jugement","L’avant-propos","L’avantage"]'::jsonb, 0, '*vor* (avant) + *Urteil* (jugement) : un jugement porté avant de connaître.', 6),
    ('83d5a6cc-0209-5bd9-a6e4-12ef63c1771f'::uuid, 'd4a8b1f2-b245-557c-81a6-230840765237'::uuid, 'Après 1945, les Allemands ont longtemps affiché peu leurs symboles nationaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le patriotisme était suspect après le nazisme ; le drapeau est revenu en masse en 2006.', 7),
    ('a632b831-1b16-5a10-b764-5c01a750b471'::uuid, 'd4a8b1f2-b245-557c-81a6-230840765237'::uuid, 'Quel événement a vu le retour massif du drapeau dans les rues allemandes ?', 'mcq', '["La réunification de 1990","La Coupe du monde de football 2006","Les JO de 1972","L’euro en 2002"]'::jsonb, 1, 'Organisée en Allemagne, la Coupe du monde 2006 a lancé un « patriotisme de fête ».', 8),
    ('58c3c3a2-64d5-567c-a67c-9cf9ed068617'::uuid, 'd4a8b1f2-b245-557c-81a6-230840765237'::uuid, 'Dans « Herkunft », Saša Stanišić raconte…', 'mcq', '["la vie à la cour de Vienne","son enfance entre la Bosnie et l’Allemagne","la chute du Mur","un conte de Grimm"]'::jsonb, 1, 'Le livre, prix du livre allemand 2019, interroge l’appartenance à deux pays.', 9),
    ('c1a8a527-e4a6-5949-bb04-824977139c11'::uuid, 'd4a8b1f2-b245-557c-81a6-230840765237'::uuid, 'Comment dit-on « l’autoportrait » ?', 'mcq', '["das Selbstbild","das Selbstporträt","das Eigenbild","die Selbstdarstellung"]'::jsonb, 1, '*das Selbstbild* est l’image de soi, au sens psychologique.', 10),
    ('30ea2aea-f4e7-503e-976d-ea2abd109cfb'::uuid, 'd4a8b1f2-b245-557c-81a6-230840765237'::uuid, '« Ich fühle mich eher als Bayer » exprime…', 'mcq', '["une identité régionale","un rejet de l’Allemagne","une nationalité étrangère","un cliché sur les Bavarois"]'::jsonb, 0, 'Dans un pays fédéral, l’identité régionale compte souvent autant que la nationale.', 11),
    ('4cc6a638-512d-595f-b3d6-84c109c94d04'::uuid, 'd4a8b1f2-b245-557c-81a6-230840765237'::uuid, 'Combien de cantons compte la Suisse ?', 'mcq', '["16","9","26","12"]'::jsonb, 2, 'La Suisse compte 26 cantons ; l’Allemagne 16 Länder, l’Autriche 9.', 12),
    ('ea5d01fc-8bc5-5057-bf6d-26370536da64'::uuid, '5cd17676-1a52-5862-971b-df88c0bf1875'::uuid, 'Que signifie le slogan « Trau keinem über 30! » ?', 'mcq', '["Ne fais confiance à personne de plus de 30 ans","Il faut avoir 30 ans pour voter","Tout change après 30 ans","Trente ans de paix"]'::jsonb, 0, 'Slogan des étudiants de 1968, en rupture avec la génération de leurs parents.', 1),
    ('cd7bec95-1337-54c6-9cff-291661bb69d1'::uuid, '5cd17676-1a52-5862-971b-df88c0bf1875'::uuid, 'Quelle question les jeunes de 1968 posaient-ils avec insistance à leurs parents ?', 'mcq', '["Leur rôle sous le nazisme","Leur salaire","Leur religion","Leur vote en 1990"]'::jsonb, 0, 'Le silence sur le passé nazi était au cœur de la révolte.', 2),
    ('d7aa03f7-b86f-5b81-b4d4-1a71c6ebdf8d'::uuid, '5cd17676-1a52-5862-971b-df88c0bf1875'::uuid, 'Qui fut une figure du mouvement étudiant ouest-allemand ?', 'mcq', '["Willy Brandt","Rudi Dutschke","Helmut Kohl","Konrad Adenauer"]'::jsonb, 1, 'Rudi Dutschke en était le porte-parole le plus connu.', 3),
    ('8e0dca70-4e3b-5ced-a2cf-c5fe1f4f8550'::uuid, '5cd17676-1a52-5862-971b-df88c0bf1875'::uuid, 'Thomas Mann a reçu le prix Nobel de littérature en…', 'mcq', '["1901","1929","1946","1972"]'::jsonb, 1, 'Pour *Les Buddenbrook*, notamment ; ses enfants Klaus et Erika ont aussi écrit.', 4),
    ('f07935a2-78be-566d-9e6a-797f8c169973'::uuid, '5cd17676-1a52-5862-971b-df88c0bf1875'::uuid, 'Qu’est-ce qu’un « Mehrgenerationenhaus » ?', 'mcq', '["Une maison de retraite fermée","Un lieu ouvert où les générations se rencontrent","Une école maternelle","Un immeuble réservé aux étudiants"]'::jsonb, 1, '*mehr* (plusieurs) + *Generationen* + *Haus* : un lieu de rencontre entre générations.', 5),
    ('60a2bfe5-1531-51b3-ac25-e18ca34585db'::uuid, '5cd17676-1a52-5862-971b-df88c0bf1875'::uuid, 'Que désigne « der Generationenvertrag » ?', 'mcq', '["Un traité de paix","Le principe selon lequel les actifs paient les retraites des anciens","Un contrat de travail","Un héritage"]'::jsonb, 1, 'C’est la base du système de retraite par répartition.', 6),
    ('810b8508-21e6-546c-a10f-61e1b057e629'::uuid, '5cd17676-1a52-5862-971b-df88c0bf1875'::uuid, 'L’âge médian en Allemagne dépasse 45 ans.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’Allemagne est l’un des pays les plus âgés du monde.', 7),
    ('8713be89-316e-59bf-affc-17bbeb4c7e5c'::uuid, '5cd17676-1a52-5862-971b-df88c0bf1875'::uuid, 'Que signifie « die Enkel » ?', 'mcq', '["Les oncles","Les petits-enfants","Les ancêtres","Les cousins"]'::jsonb, 1, '*der Enkel / die Enkelin* : le petit-fils, la petite-fille.', 8),
    ('beffb44f-f961-5446-a66b-47daac63e658'::uuid, '5cd17676-1a52-5862-971b-df88c0bf1875'::uuid, 'Quelle famille de musiciens a compté plusieurs fils compositeurs ?', 'mcq', '["Mann","Bach","Grimm","Brecht"]'::jsonb, 1, 'Carl Philipp Emanuel et Johann Christian Bach sont célèbres à leur tour.', 9),
    ('4751d10b-9c47-593e-9ab2-d24dbab9034e'::uuid, '5cd17676-1a52-5862-971b-df88c0bf1875'::uuid, 'Comment dit-on « la colocation » ?', 'mcq', '["die Wohngemeinschaft","die Wohnung","die Gemeinde","das Wohnheim"]'::jsonb, 0, 'Abrégé en *WG* : une communauté de logement.', 10),
    ('2ea2ded2-9b23-5d93-809b-8138f0d0c9f0'::uuid, '5cd17676-1a52-5862-971b-df88c0bf1875'::uuid, '« Wohnen für Hilfe » désigne…', 'mcq', '["une aide au logement de l’État","un étudiant logé chez un senior contre de l’aide","une maison de retraite","un service de déménagement"]'::jsonb, 1, 'Un logement contre des services : une solidarité concrète entre générations.', 11),
    ('910ff77d-eaec-53b1-aaa2-4afcffcac90a'::uuid, '5cd17676-1a52-5862-971b-df88c0bf1875'::uuid, 'Que signifie « weitergeben » ?', 'mcq', '["Abandonner","Transmettre","Recevoir","Oublier"]'::jsonb, 1, '*weiter* (plus loin) + *geben* (donner) : faire passer à d’autres.', 12),
    ('29239108-52a9-538e-808b-8b26c9f895a1'::uuid, '0b3630d0-6b99-5140-a20b-93f3eb769724'::uuid, 'Que désigne « die Aufarbeitung der Vergangenheit » ?', 'mcq', '["La reconstruction des villes","Le travail de l’Allemagne pour assumer son passé","Un cours d’histoire","La réunification"]'::jsonb, 1, 'C’est l’effort collectif pour affronter les crimes du national-socialisme.', 1),
    ('1caf4b73-b916-5d41-a696-888295da4ff3'::uuid, '0b3630d0-6b99-5140-a20b-93f3eb769724'::uuid, 'Que sont les « Stolpersteine » ?', 'mcq', '["Des pavés portant le nom de victimes du nazisme","Des murs de Berlin","Des tombes de soldats","Des statues de rois"]'::jsonb, 0, 'Posés devant le dernier domicile choisi librement par la victime, ils rappellent un nom.', 2),
    ('3362a5c7-de2b-52ce-bbd5-5ff50088b83b'::uuid, '0b3630d0-6b99-5140-a20b-93f3eb769724'::uuid, 'Quel chancelier s’est agenouillé à Varsovie en 1970 ?', 'mcq', '["Konrad Adenauer","Helmut Schmidt","Willy Brandt","Helmut Kohl"]'::jsonb, 2, 'Ce geste de Willy Brandt est devenu un symbole de la reconnaissance des crimes allemands.', 3),
    ('b5e6c85d-9af8-5cca-9b4f-cb8e587c1efb'::uuid, '0b3630d0-6b99-5140-a20b-93f3eb769724'::uuid, 'Le mémorial aux Juifs assassinés d’Europe se trouve à…', 'mcq', '["Munich","Berlin","Nuremberg","Francfort"]'::jsonb, 1, 'Inauguré en 2005 près de la porte de Brandebourg.', 4),
    ('f7dd1721-440a-5fb8-b4d4-13233d79ff5f'::uuid, '0b3630d0-6b99-5140-a20b-93f3eb769724'::uuid, 'Que signifie « Ostalgie » ?', 'mcq', '["La nostalgie de certains aspects de la vie en RDA","La haine de l’Est","Un parti politique","Une tradition bavaroise"]'::jsonb, 0, '*Ost* + *Nostalgie* : le regret de certains aspects de la vie à l’Est.', 5),
    ('e3f8562f-8194-5754-858b-c66e07cf616f'::uuid, '0b3630d0-6b99-5140-a20b-93f3eb769724'::uuid, 'Regretter certains aspects de la vie en RDA signifie forcément regretter la dictature.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’Ostalgie vise souvent les objets et la vie quotidienne, pas la Stasi ni le régime.', 6),
    ('ea404851-6180-52e5-ac01-58e7c85a5db5'::uuid, '0b3630d0-6b99-5140-a20b-93f3eb769724'::uuid, 'Quel film de 2003 a évoqué l’Ostalgie avec humour ?', 'mcq', '["La Vie des autres","Good Bye, Lenin!","Cours, Lola, cours","Le Tambour"]'::jsonb, 1, 'Un fils recrée la RDA dans l’appartement de sa mère après la chute du Mur.', 7),
    ('b519e6e2-2d12-58ae-9152-356909de99e8'::uuid, '0b3630d0-6b99-5140-a20b-93f3eb769724'::uuid, 'Qu’est-ce que l’« Ampelmännchen » ?', 'mcq', '["Le bonhomme des feux piétons de l’Est","Un gâteau de Noël","Une marionnette de la télévision","Une mascotte de football"]'::jsonb, 0, 'Symbole sauvé après la réunification, il est devenu une marque populaire.', 8),
    ('0cc1a02b-9fd4-5a0d-8888-61c13d9183c0'::uuid, '0b3630d0-6b99-5140-a20b-93f3eb769724'::uuid, 'La mine Zollverein, classée à l’UNESCO, se trouve…', 'mcq', '["en Lusace","dans la Ruhr, à Essen","à Hambourg","en Bavière"]'::jsonb, 1, 'Ancienne mine de charbon devenue site culturel.', 9),
    ('a5f4d4d1-ac89-5b96-ba44-d395c715d584'::uuid, '0b3630d0-6b99-5140-a20b-93f3eb769724'::uuid, 'Que signifie « das Mahnmal » ?', 'mcq', '["Le repas du soir","Le mémorial qui avertit","La cathédrale","L’hôtel de ville"]'::jsonb, 1, '*mahnen* = avertir, exhorter : un monument qui met en garde.', 10),
    ('f8f063d6-930f-5c1e-856a-30efbfc79b46'::uuid, '0b3630d0-6b99-5140-a20b-93f3eb769724'::uuid, '« Ich erinnere mich ___ meine Kindheit. » Quel mot complète la phrase ?', 'mcq', '["auf","an","über","von"]'::jsonb, 1, '*sich erinnern an* + accusatif : se souvenir de.', 11),
    ('548d1e2e-fcba-5d13-bf54-78a07461d50e'::uuid, '0b3630d0-6b99-5140-a20b-93f3eb769724'::uuid, 'Que désigne l’« Abiball » ?', 'mcq', '["Le bal du bac","Un match de football","La fête du 3 octobre","Un bal de mariage"]'::jsonb, 0, 'Le bal qui fête l’*Abitur* ; en Autriche, on parle de *Maturaball*.', 12),
    ('f2741697-941e-53d9-8408-0dceafe142e6'::uuid, 'c7018d50-4dcb-503b-8678-0080997e30cf'::uuid, 'Que signifie « die Energiewende » ?', 'mcq', '["La crise de l’énergie","Le tournant énergétique","Le prix de l’énergie","Une centrale électrique"]'::jsonb, 1, '*die Wende* = le tournant : le passage aux renouvelables et la sortie du nucléaire.', 1),
    ('3e927774-f502-5f96-84fb-39a8db55a8d5'::uuid, 'c7018d50-4dcb-503b-8678-0080997e30cf'::uuid, 'Quel événement a poussé l’Allemagne à décider de sortir du nucléaire en 2011 ?', 'mcq', '["Tchernobyl","Fukushima","La chute du Mur","La crise financière"]'::jsonb, 1, 'La catastrophe de Fukushima a accéléré la décision du gouvernement Merkel.', 2),
    ('cedea2b3-51bb-54b0-af35-1b58594c1827'::uuid, 'c7018d50-4dcb-503b-8678-0080997e30cf'::uuid, 'En quelle année les derniers réacteurs allemands ont-ils été arrêtés ?', 'mcq', '["2011","2019","2023","2038"]'::jsonb, 2, 'Les trois derniers ont fermé en avril 2023.', 3),
    ('4fe72624-5fab-5071-841c-368eea4458de'::uuid, 'c7018d50-4dcb-503b-8678-0080997e30cf'::uuid, 'Que désigne « der Fachkräftemangel » ?', 'mcq', '["Le chômage des jeunes","La pénurie de main-d’œuvre qualifiée","Le manque d’écoles","La baisse des salaires"]'::jsonb, 1, '*die Fachkraft* = le travailleur qualifié ; *der Mangel* = le manque.', 4),
    ('58f1d7a7-27ed-5cb6-80d4-1baa80a7d043'::uuid, 'c7018d50-4dcb-503b-8678-0080997e30cf'::uuid, 'Par quelle phrase commence la Loi fondamentale allemande ?', 'mcq', '["Wir sind das Volk","Die Würde des Menschen ist unantastbar","Einigkeit und Recht und Freiheit","Alle Macht dem Volke"]'::jsonb, 1, 'L’article 1 place la dignité humaine au sommet.', 5),
    ('f4df2ea7-11dd-53cb-a932-a5051851d7d6'::uuid, 'c7018d50-4dcb-503b-8678-0080997e30cf'::uuid, 'Plus de la moitié de l’électricité allemande vient aujourd’hui des renouvelables.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Éolien, solaire et biomasse dépassent désormais la moitié de la production.', 6),
    ('1210a61d-fb0f-52c8-9eb0-6bd34978980f'::uuid, 'c7018d50-4dcb-503b-8678-0080997e30cf'::uuid, 'Que veut dire « wehrhafte Demokratie » ?', 'mcq', '["Une démocratie armée pour la guerre","Une démocratie capable de se défendre contre ses ennemis","Une démocratie directe","Une monarchie"]'::jsonb, 1, 'Leçon de Weimar : la démocratie se donne les moyens d’interdire ce qui veut la détruire.', 7),
    ('0f572025-dcdb-58db-adec-1ebe1c090587'::uuid, 'c7018d50-4dcb-503b-8678-0080997e30cf'::uuid, 'Comment dit-on « la centrale nucléaire » ?', 'mcq', '["das Kernkraftwerk","das Kraftwerkkern","die Atomstadt","das Windrad"]'::jsonb, 0, 'Abrégé *AKW* (*Atomkraftwerk*) dans la langue courante.', 8),
    ('3e6dcf47-7894-5110-a4ef-6a390077dd3e'::uuid, 'c7018d50-4dcb-503b-8678-0080997e30cf'::uuid, 'Jusqu’à quand l’Allemagne prévoit-elle au plus tard de sortir du charbon ?', 'mcq', '["2025","2030","2038","2050"]'::jsonb, 2, 'La loi fixe 2038 au plus tard.', 9),
    ('3d413b31-f28b-512e-9e6b-ce0edea889ab'::uuid, 'c7018d50-4dcb-503b-8678-0080997e30cf'::uuid, 'Que signifie « die Herausforderung » ?', 'mcq', '["Le défi","La sortie","La demande","La victoire"]'::jsonb, 0, 'Un mot clé de l’axe : *vor einer Herausforderung stehen*, être face à un défi.', 10),
    ('42828d37-328b-5e54-b220-2fffc2c498c4'::uuid, 'c7018d50-4dcb-503b-8678-0080997e30cf'::uuid, 'Quel est le taux de fécondité approximatif en Allemagne ?', 'mcq', '["2,5","1,4","3,0","0,8"]'::jsonb, 1, 'Autour de 1,4 enfant par femme, en dessous du seuil de renouvellement.', 11),
    ('48bfd9c9-3bb0-5dc2-b88f-eaaeb29f1d38'::uuid, 'c7018d50-4dcb-503b-8678-0080997e30cf'::uuid, 'Quel problème touche les stations de ski des Alpes ?', 'mcq', '["Le manque de neige dû au réchauffement","L’interdiction du ski","La fermeture des frontières","Le manque de touristes étrangers"]'::jsonb, 0, 'Le réchauffement pousse à se reconvertir vers d’autres activités.', 12),
    ('e9a463d8-45fb-5de6-bf6c-714827ae7381'::uuid, '80f22538-5538-578c-b285-c094b8b78e27'::uuid, 'Qui a écrit le célèbre poème de la Loreley en 1824 ?', 'mcq', '["Goethe","Heinrich Heine","Schiller","Brecht"]'::jsonb, 1, 'Heine en fait une sirène fatale ; Brentano avait inventé la figure en 1801.', 1),
    ('7b23efab-067d-5b05-aab0-6ee95c528de7'::uuid, '80f22538-5538-578c-b285-c094b8b78e27'::uuid, 'La Loreley est liée à quel fleuve ?', 'mcq', '["Le Danube","L’Elbe","Le Rhin","L’Oder"]'::jsonb, 2, 'C’est un rocher du Rhin moyen, passage autrefois dangereux.', 2),
    ('7c9fbe69-fe43-5849-b9f9-fde289ed2386'::uuid, '80f22538-5538-578c-b285-c094b8b78e27'::uuid, 'Dans le Faust de Goethe, qui est Méphisto ?', 'mcq', '["Le frère de Faust","Le diable avec qui Faust fait un pari","Un professeur","Le père de Gretchen"]'::jsonb, 1, 'Méphistophélès, figure du diable, parie qu’il satisfera Faust.', 3),
    ('4ec2383a-0c18-5616-9da3-603b619f2cbf'::uuid, '80f22538-5538-578c-b285-c094b8b78e27'::uuid, 'En quelle année paraît Faust I ?', 'mcq', '["1587","1808","1900","1945"]'::jsonb, 1, 'Goethe publie la première partie en 1808.', 4),
    ('cf788b0e-fc64-535e-8c83-278882c7694f'::uuid, '80f22538-5538-578c-b285-c094b8b78e27'::uuid, 'Que signifie l’adjectif « faustisch » ?', 'mcq', '["Qui a une ambition sans limite","Qui est paresseux","Qui croit aux fées","Qui aime la forêt"]'::jsonb, 0, 'Il décrit une soif de savoir et de pouvoir qui ne connaît pas de bornes.', 5),
    ('c89ad106-3241-5e29-bf9f-5b202a734c2a'::uuid, '80f22538-5538-578c-b285-c094b8b78e27'::uuid, 'Les frères Grimm ont publié leurs contes en…', 'mcq', '["1701","1812","1871","1920"]'::jsonb, 1, 'Première édition des *Kinder- und Hausmärchen* en 1812.', 6),
