    ('d00abd64-150f-5098-908e-03f3af625d4e'::uuid, '80f22538-5538-578c-b285-c094b8b78e27'::uuid, 'Siegfried est le héros de…', 'mcq', '["la Chanson des Nibelungen","Faust","la Loreley","Hänsel et Gretel"]'::jsonb, 0, 'Épopée médiévale (vers 1200), reprise notamment par Wagner.', 9),
