    ('43bef8c3-7d9e-5c43-ba97-463069625666'::uuid, '80f22538-5538-578c-b285-c094b8b78e27'::uuid, 'Comment dit-on « la sorcière » ?', 'mcq', '["die Hexe","die Fee","die Göttin","die Heldin"]'::jsonb, 0, 'La sorcière de Hänsel et Gretel est *die Hexe*.', 11),
    ('aec52a76-771d-57d5-b9c2-f5a6a08930ae'::uuid, '80f22538-5538-578c-b285-c094b8b78e27'::uuid, 'Que révèle la reprise d’un mythe à une nouvelle époque ?', 'mcq', '["Rien, c’est une simple copie","Les préoccupations de l’époque qui le reprend","Seulement l’époque d’origine","Que le mythe est vrai"]'::jsonb, 1, 'Chaque réinterprétation reflète les valeurs et les peurs de son temps.', 12),
