    ('aa989201-6e33-5aac-a320-a30371ab6b93'::uuid, 'd1e91dc3-4fa9-5c71-ad93-12b2d7854d35'::uuid, 'Que rappelle le « H » des plaques HH et HB ?', 'mcq', '["Hauptstadt","Hansestadt","Hafen","Heimat"]'::jsonb, 1, 'Hambourg et Brême sont des villes hanséatiques.', 3),
    ('207500c7-729d-5c84-ac5d-bc1c0a39544f'::uuid, 'd1e91dc3-4fa9-5c71-ad93-12b2d7854d35'::uuid, 'Quels traités fondent la CEE en 1957 ?', 'mcq', '["Les traités de Rome","Le traité de Maastricht","Le traité de l’Élysée","Le traité de Versailles"]'::jsonb, 0, 'Signés par six pays, dont la France et la RFA.', 4),
    ('e5eb2910-9de3-5376-acf1-a0066d45feac'::uuid, 'd1e91dc3-4fa9-5c71-ad93-12b2d7854d35'::uuid, 'La Hanse était avant tout…', 'mcq', '["une alliance militaire","une association de villes marchandes","une dynastie royale","une Église"]'::jsonb, 1, 'Un réseau commercial autour de la mer du Nord et de la Baltique.', 5),
    ('34583d71-cd00-5724-b795-33892d7ffecc'::uuid, 'd1e91dc3-4fa9-5c71-ad93-12b2d7854d35'::uuid, 'Que signifie « die Versöhnung » ?', 'mcq', '["La réconciliation","La guerre","La frontière","Le commerce"]'::jsonb, 0, 'Mot clé de la relation franco-allemande après 1945.', 6),
    ('fd160c2d-1597-5826-bc75-582b1adb7d36'::uuid, 'd1e91dc3-4fa9-5c71-ad93-12b2d7854d35'::uuid, 'En quelle année l’euro a-t-il remplacé le mark dans les porte-monnaie ?', 'mcq', '["1990","1999","2002","2007"]'::jsonb, 2, 'Les pièces et billets en euros circulent depuis le 1er janvier 2002.', 7),
    ('743a304f-5fa4-5f16-9fae-82dfe1a5366d'::uuid, 'd1e91dc3-4fa9-5c71-ad93-12b2d7854d35'::uuid, 'L’Allemagne est le pays le plus peuplé de l’Union européenne.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Environ 84 millions d’habitants.', 8),
    ('19f00abb-7273-5304-8d5e-3bc513287a75'::uuid, 'd1e91dc3-4fa9-5c71-ad93-12b2d7854d35'::uuid, 'Quel pays de l’Est est devenu un partenaire économique majeur de l’Allemagne ?', 'mcq', '["La Pologne","L’Islande","Le Portugal","L’Irlande"]'::jsonb, 0, 'Depuis son entrée dans l’UE en 2004, la Pologne est un grand partenaire commercial.', 9),
    ('3033c429-f467-57ae-bfca-dfb4b701bffb'::uuid, 'd1e91dc3-4fa9-5c71-ad93-12b2d7854d35'::uuid, 'Comment dit-on « la frontière » ?', 'mcq', '["die Grenze","der Grund","das Gebiet","die Kante"]'::jsonb, 0, '*die Grenze* : un mot essentiel pour parler de l’Europe.', 10),
    ('5fe540d5-b7de-579e-b983-6ad68a067475'::uuid, 'd1e91dc3-4fa9-5c71-ad93-12b2d7854d35'::uuid, 'Que désigne le terme « Mitteleuropa » ?', 'mcq', '["L’Europe méditerranéenne","L’Europe du milieu","L’Europe du Nord","L’Union européenne"]'::jsonb, 1, 'L’espace central de l’Europe, entre l’Ouest et l’Est.', 11),
    ('aca69b5a-3b2c-51bb-8432-f903d2b96622'::uuid, 'd1e91dc3-4fa9-5c71-ad93-12b2d7854d35'::uuid, 'Que signifie « die Zusammenarbeit » ?', 'mcq', '["La coopération","La concurrence","Le chômage","L’indépendance"]'::jsonb, 0, '*zusammen* (ensemble) + *arbeiten* (travailler).', 12),
    ('5f7effa6-5089-5a50-9258-b966f7dbf537'::uuid, '9c82c17d-d98b-5cad-acdf-f8dd4fbe698f'::uuid, 'Comment dit-on « j’aurais su » ?', 'mcq', '["ich hatte gewusst","ich hätte gewusst","ich würde wissen","ich wäre gewusst"]'::jsonb, 1, '*wissen* forme son parfait avec *haben* : subjonctif II passé *hätte gewusst*.', 1),
    ('17958333-7f9f-5ee9-98c4-2397f543e312'::uuid, '9c82c17d-d98b-5cad-acdf-f8dd4fbe698f'::uuid, 'Comment dit-on « elle serait venue » ?', 'mcq', '["sie hätte gekommen","sie wäre gekommen","sie war gekommen","sie würde gekommen"]'::jsonb, 1, '*kommen* se conjugue avec *sein* : *wäre gekommen*.', 2),
    ('bb5626ce-750c-5d94-8de6-016d8f28afed'::uuid, '9c82c17d-d98b-5cad-acdf-f8dd4fbe698f'::uuid, 'Quelle phrase exprime un regret ?', 'mcq', '["Ich habe mehr gelernt.","Hätte ich doch mehr gelernt!","Ich lerne mehr.","Ich werde mehr lernen."]'::jsonb, 1, '*Hätte ich doch…!* : si seulement j’avais…', 3),
    ('68a37097-b140-577a-b1b0-5f0710569be5'::uuid, '9c82c17d-d98b-5cad-acdf-f8dd4fbe698f'::uuid, '« Wenn ich Zeit gehabt ___, hätte ich dir geholfen. » Quel mot complète la phrase ?', 'mcq', '["hatte","hätte","habe","wäre"]'::jsonb, 1, 'Irréel du passé des deux côtés : *gehabt hätte*.', 4),
    ('af10bdfd-2351-56be-8ee3-a323ef55d677'::uuid, '9c82c17d-d98b-5cad-acdf-f8dd4fbe698f'::uuid, 'Quelle différence entre « hatte » et « hätte » ?', 'mcq', '["Aucune","hatte est un prétérit, hätte un subjonctif II","hatte est un subjonctif, hätte un prétérit","hätte est seulement écrit"]'::jsonb, 1, 'Le tréma change le mode : *ich hatte* = j’avais ; *ich hätte* = j’aurais.', 5),
    ('5b80ca23-b14f-54b7-b1e5-36bcffd7fb4a'::uuid, '9c82c17d-d98b-5cad-acdf-f8dd4fbe698f'::uuid, 'Comment dit-on « Tu aurais dû m’appeler » ?', 'mcq', '["Du musstest mich anrufen.","Du hättest mich anrufen sollen.","Du wärst mich angerufen.","Du sollst mich anrufen."]'::jsonb, 1, 'Le reproche : *hättest … sollen*, avec *sollen* à l’infinitif en fin de phrase.', 6),
    ('5848fef8-3968-5e1f-970e-e7c88cb4aa87'::uuid, '9c82c17d-d98b-5cad-acdf-f8dd4fbe698f'::uuid, 'Au subjonctif II passé, on choisit hätte ou wäre selon l’auxiliaire du parfait.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*haben* → *hätte*, *sein* → *wäre* : c’est le même choix qu’au parfait.', 7),
    ('4037a691-d5fb-5e9d-8f96-1bd530b1b50c'::uuid, '9c82c17d-d98b-5cad-acdf-f8dd4fbe698f'::uuid, '« Fast wäre ich gefallen » signifie…', 'mcq', '["Je suis tombé plusieurs fois","J’ai failli tomber","Je serais tombé si…","Je tombe souvent"]'::jsonb, 1, '*fast* + subjonctif II passé : ce qui a failli arriver.', 8),
    ('a11a69a9-ee9c-530b-80c3-a088a08cd6d6'::uuid, '9c82c17d-d98b-5cad-acdf-f8dd4fbe698f'::uuid, 'Quel est le subjonctif II de « wir sind » ?', 'mcq', '["wir waren","wir wären","wir hätten","wir würden"]'::jsonb, 1, '*wären* : forme de subjonctif II de *sein*.', 9),
    ('04a0b32c-300f-569d-a77e-a098619796da'::uuid, '9c82c17d-d98b-5cad-acdf-f8dd4fbe698f'::uuid, 'Comment traduire « Si nous étions partis plus tôt… » ?', 'mcq', '["Wenn wir früher abgefahren sind…","Wenn wir früher abgefahren wären…","Wenn wir früher abgefahren hätten…","Wenn wir früher abfuhren…"]'::jsonb, 1, '*abfahren* prend *sein* : *abgefahren wären*, auxiliaire en fin de subordonnée.', 10),
    ('c041b47a-058f-52bd-9987-0c819978a1bd'::uuid, '9c82c17d-d98b-5cad-acdf-f8dd4fbe698f'::uuid, 'Dans une subordonnée en wenn, l’auxiliaire hätte ou wäre se place…', 'mcq', '["en 1re position","en 2e position","en toute fin","juste après wenn"]'::jsonb, 2, 'Le verbe conjugué ferme la subordonnée : *wenn ich es gewusst hätte*.', 11),
    ('9fbb3ceb-8f88-50ba-b34f-62172cc11495'::uuid, '9c82c17d-d98b-5cad-acdf-f8dd4fbe698f'::uuid, 'Quel temps français correspond à la principale « … wäre ich gekommen » ?', 'mcq', '["Le plus-que-parfait","Le conditionnel passé","Le passé simple","Le futur antérieur"]'::jsonb, 1, '« Je serais venu » : conditionnel passé.', 12),
    ('9b7680f5-d516-5fb1-a2c7-81078646d811'::uuid, '328847a7-d87b-5243-b8cb-3cc7badec67c'::uuid, 'Quelle préposition accompagne « warten » ?', 'mcq', '["für","auf","an","nach"]'::jsonb, 1, '*warten auf* + accusatif : *Ich warte auf den Bus.*', 1),
    ('c529b226-229b-5740-9b96-c1f57d1170be'::uuid, '328847a7-d87b-5243-b8cb-3cc7badec67c'::uuid, '« Ich habe Angst ___ dem Hund. » Quel mot complète la phrase ?', 'mcq', '["von","vor","für","über"]'::jsonb, 1, '*Angst haben vor* + datif : avoir peur de.', 2),
    ('925743ea-93ad-55d0-8e9a-c6efd38c2065'::uuid, '328847a7-d87b-5243-b8cb-3cc7badec67c'::uuid, 'Comment dit-on « Je m’intéresse à l’art » ?', 'mcq', '["Ich interessiere mich an Kunst.","Ich interessiere mich für Kunst.","Ich interessiere mich auf Kunst.","Ich interessiere Kunst."]'::jsonb, 1, '*sich interessieren für* + accusatif.', 3),
    ('9f239911-82f0-5766-87a1-60be4e7d90c3'::uuid, '328847a7-d87b-5243-b8cb-3cc7badec67c'::uuid, '« Ich freue mich auf die Ferien » parle de vacances…', 'mcq', '["passées","à venir","en cours","annulées"]'::jsonb, 1, '*sich freuen auf* : se réjouir de ce qui va arriver.', 4),
    ('3d6e58a9-d4af-5111-aedc-9451e8693ca1'::uuid, '328847a7-d87b-5243-b8cb-3cc7badec67c'::uuid, 'Quel cas suit « an » dans « teilnehmen an » ?', 'mcq', '["L’accusatif","Le datif","Le génitif","Le nominatif"]'::jsonb, 1, '*an einer Debatte teilnehmen* : datif.', 5),
    ('5371e84e-e7aa-50d1-982c-9e6aa206b736'::uuid, '328847a7-d87b-5243-b8cb-3cc7badec67c'::uuid, '« Er ist stolz ___ seine Tochter. » Quel mot complète la phrase ?', 'mcq', '["von","über","auf","an"]'::jsonb, 2, '*stolz sein auf* + accusatif : être fier de.', 6),
    ('6d99d66a-cbe0-5f7b-b0b2-d07a0920cd41'::uuid, '328847a7-d87b-5243-b8cb-3cc7badec67c'::uuid, 'Dans une rection prépositionnelle, le cas après an, auf, über dépend du mouvement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le cas est fixé par le verbe, indépendamment de toute idée de lieu.', 7),
    ('8935df4a-2ab5-5179-a966-c7f2f3051e75'::uuid, '328847a7-d87b-5243-b8cb-3cc7badec67c'::uuid, 'Que signifie « Das hängt vom Wetter ab » ?', 'mcq', '["Cela dépend du temps","Cela tombe du ciel","Il fait mauvais","C’est accroché dehors"]'::jsonb, 0, '*abhängen von* + datif : dépendre de.', 8),
    ('ffdfe731-fdd6-5ddb-9d31-ae8711a2fa80'::uuid, '328847a7-d87b-5243-b8cb-3cc7badec67c'::uuid, 'Comment dit-on « Je pense à toi » ?', 'mcq', '["Ich denke an dich.","Ich denke von dir.","Ich denke dir.","Ich denke auf dich."]'::jsonb, 0, '*denken an* + accusatif.', 9),
    ('96b0c257-12b0-54f7-9d1d-9203c7b18efe'::uuid, '328847a7-d87b-5243-b8cb-3cc7badec67c'::uuid, 'Quelle question porte sur une personne attendue ?', 'mcq', '["Worauf wartest du?","Auf wen wartest du?","Wo wartest du?","Was wartest du?"]'::jsonb, 1, 'Pour une personne : préposition + *wen* ; *worauf* vise une chose.', 10),
    ('0bfab061-a106-524b-97bc-5c2b783a8797'::uuid, '328847a7-d87b-5243-b8cb-3cc7badec67c'::uuid, '« sich kümmern um » signifie…', 'mcq', '["s’inquiéter de","s’occuper de","se moquer de","se souvenir de"]'::jsonb, 1, '*Ich kümmere mich um meinen Bruder* : je m’occupe de mon frère.', 11),
    ('43e88400-2bce-5906-b0cf-9519221b76b7'::uuid, '328847a7-d87b-5243-b8cb-3cc7badec67c'::uuid, 'Quelle construction est correcte ?', 'mcq', '["Ich erinnere mich an den Urlaub.","Ich erinnere mich von dem Urlaub.","Ich erinnere mich über den Urlaub.","Ich erinnere den Urlaub mich."]'::jsonb, 0, '*sich erinnern an* + accusatif : se souvenir de.', 12),
    ('ac97539a-2c5d-5d4d-b0a3-6fb5986d2884'::uuid, 'd8965e96-dbe5-5a52-b84b-078301ee9d4a'::uuid, 'Comment reprendre « auf den Bus » dans « Ich warte auf den Bus » ?', 'mcq', '["Ich warte auf ihn.","Ich warte darauf.","Ich warte worauf.","Ich warte daran."]'::jsonb, 1, 'Le bus est une chose : *darauf*.', 1),
    ('79829318-0cd0-5ed4-9286-2785a45ffe37'::uuid, 'd8965e96-dbe5-5a52-b84b-078301ee9d4a'::uuid, 'Comment reprendre « auf Paul » dans « Ich warte auf Paul » ?', 'mcq', '["Ich warte darauf.","Ich warte auf ihn.","Ich warte daran.","Ich warte worauf."]'::jsonb, 1, 'Pour une personne, on garde préposition + pronom : *auf ihn*.', 2),
    ('e2c142f7-9a29-5474-a2af-1f9e79081495'::uuid, 'd8965e96-dbe5-5a52-b84b-078301ee9d4a'::uuid, 'Pourquoi écrit-on « darüber » avec un r ?', 'mcq', '["Par erreur","Parce que über commence par une voyelle","Parce que c’est un pluriel","Pour marquer le datif"]'::jsonb, 1, 'On intercale un *r* devant une préposition à initiale vocalique.', 3),
    ('1f652548-cbf4-5601-bf1c-53275d132911'::uuid, 'd8965e96-dbe5-5a52-b84b-078301ee9d4a'::uuid, 'Quelle question porte sur une chose ?', 'mcq', '["An wen denkst du?","Woran denkst du?","Wen denkst du?","Wem denkst du?"]'::jsonb, 1, '*woran* interroge sur une chose ou une idée.', 4),
    ('7a228c12-5321-59e8-a69d-e0bb4c676f08'::uuid, 'd8965e96-dbe5-5a52-b84b-078301ee9d4a'::uuid, '« ___ interessierst du dich? — Für Musik. » Quel mot complète la question ?', 'mcq', '["Wofür","Für wen","Womit","Was"]'::jsonb, 0, '*sich interessieren für* ; question sur une chose : *wofür*.', 5),
    ('1391f37e-38d6-5e11-a739-dbab63d7231e'::uuid, 'd8965e96-dbe5-5a52-b84b-078301ee9d4a'::uuid, 'Dans « Ich freue mich darauf, dass du kommst », que fait « darauf » ?', 'mcq', '["Il remplace une personne","Il annonce la subordonnée en dass","Il indique un lieu","Il est inutile et fautif"]'::jsonb, 1, 'Il garde la trace de *sich freuen auf* et annonce la subordonnée.', 6),
    ('83b91a50-7ae9-5d52-b735-daac661b9ce4'::uuid, 'd8965e96-dbe5-5a52-b84b-078301ee9d4a'::uuid, 'On peut former « daohne ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*ohne*, *seit*, *außer* et *gegenüber* n’ont pas de forme en *da-*.', 7),
    ('bbe44e93-30d1-507a-a999-073c704593b4'::uuid, 'd8965e96-dbe5-5a52-b84b-078301ee9d4a'::uuid, 'Quelle est la forme en wo- de « mit » ?', 'mcq', '["womit","wormit","wobeimit","wiemit"]'::jsonb, 0, '*mit* commence par une consonne : pas de *r*. *Womit schreibst du?*', 8),
    ('f7f1f61b-c92b-5a87-bcb0-8f09b63f4116'::uuid, 'd8965e96-dbe5-5a52-b84b-078301ee9d4a'::uuid, '« Wir sprechen seit einer Stunde darüber » : « darüber » reprend…', 'mcq', '["une personne","une chose ou un sujet de discussion","un lieu","un moment"]'::jsonb, 1, '*sprechen über* + une chose : reprise par *darüber*.', 9),
    ('dc410a0b-a25e-5ca8-86b0-d6f3a607cf6f'::uuid, 'd8965e96-dbe5-5a52-b84b-078301ee9d4a'::uuid, 'Comment demande-t-on « À qui penses-tu ? »', 'mcq', '["Woran denkst du?","An wen denkst du?","Wem denkst du?","Wer denkst du?"]'::jsonb, 1, 'Pour une personne : préposition + *wen*.', 10),
    ('193b0d89-b2c5-5acf-9340-0f35b8837866'::uuid, 'd8965e96-dbe5-5a52-b84b-078301ee9d4a'::uuid, 'Dans « Er denkt daran, sein Handy mitzunehmen », « daran » annonce…', 'mcq', '["un groupe infinitif","un complément de lieu","une personne","un complément de temps"]'::jsonb, 0, 'Le pronom annonce le groupe infinitif en *zu*.', 11),
    ('02c074b6-e88d-5a15-824f-e4b67bb9dc3a'::uuid, 'd8965e96-dbe5-5a52-b84b-078301ee9d4a'::uuid, 'Quelle est la forme en da- de « um » ?', 'mcq', '["daum","darum","dasum","dorum"]'::jsonb, 1, 'Voyelle initiale : *da-r-um*. *Es geht darum* = il s’agit de cela.', 12),
    ('80480f9e-e821-5216-99b9-15ade5d80467'::uuid, '8ea3c4b3-f17c-566b-9fd8-a223d2d834f6'::uuid, 'Quel est le genre de « Freundschaft » ?', 'mcq', '["der","die","das","Il varie"]'::jsonb, 1, 'Les noms en *-schaft* sont toujours féminins.', 1),
    ('7f714334-6cba-51b1-8cae-a7d72dfb0842'::uuid, '8ea3c4b3-f17c-566b-9fd8-a223d2d834f6'::uuid, 'Quel est le genre de « Mädchen » ?', 'mcq', '["der","die","das","Il dépend du sexe"]'::jsonb, 2, 'Le suffixe *-chen* rend le nom neutre, même pour une personne.', 2),
    ('2ca47539-2799-55b9-b248-e88a223af322'::uuid, '8ea3c4b3-f17c-566b-9fd8-a223d2d834f6'::uuid, 'Quel suffixe annonce un nom masculin ?', 'mcq', '["-ung","-ismus","-heit","-ment"]'::jsonb, 1, '*der Optimismus*, *der Tourismus* : les noms en *-ismus* sont masculins.', 3),
    ('ac23117e-dbe0-5e38-b041-93c455eca69e'::uuid, '8ea3c4b3-f17c-566b-9fd8-a223d2d834f6'::uuid, 'Quel est le genre de « Argument » ?', 'mcq', '["der","die","das","Aucun"]'::jsonb, 2, 'Les noms en *-ment* d’origine latine sont neutres.', 4),
    ('d2cfd401-e0dc-5aff-931a-ef8511f42ceb'::uuid, '8ea3c4b3-f17c-566b-9fd8-a223d2d834f6'::uuid, 'Les phénomènes météorologiques sont en général…', 'mcq', '["féminins","masculins","neutres","sans genre"]'::jsonb, 1, '*der Regen, der Schnee, der Wind, der Nebel*.', 5),
    ('22ab65f3-997d-50d0-9f7a-89da6cbd417a'::uuid, '8ea3c4b3-f17c-566b-9fd8-a223d2d834f6'::uuid, 'Quel est le genre de « das Leben » et pourquoi ?', 'mcq', '["Neutre : infinitif substantivé","Masculin : radical verbal","Féminin : terminaison -en","Neutre : mot étranger"]'::jsonb, 0, 'Un infinitif devenu nom est toujours neutre.', 6),
    ('aa24c9e8-7fb6-55f9-96b0-e9186c2f9cbd'::uuid, '8ea3c4b3-f17c-566b-9fd8-a223d2d834f6'::uuid, '« der Fortschritt » est masculin parce que…', 'mcq', '["il finit par -t","c’est un radical verbal devenu nom","c’est un mot étranger","il désigne une personne"]'::jsonb, 1, 'La dérivation implicite (*fortschreiten* → *der Fortschritt*) donne des masculins.', 7),
    ('741c46d8-b44e-57c9-aeff-c245d4fa0f69'::uuid, '8ea3c4b3-f17c-566b-9fd8-a223d2d834f6'::uuid, 'Quel est le genre de « Nation » ?', 'mcq', '["der","die","das","Il varie"]'::jsonb, 1, 'Les noms en *-ion* sont féminins.', 8),
    ('4dc32442-6746-5464-8997-3a5ba924daee'::uuid, '8ea3c4b3-f17c-566b-9fd8-a223d2d834f6'::uuid, 'Tous les noms en -e sont féminins.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La plupart, mais pas tous : *der Junge*, *der Name*, *das Auge*.', 9),
    ('d34cd253-74c9-5368-9f2a-2aa807fc6533'::uuid, '8ea3c4b3-f17c-566b-9fd8-a223d2d834f6'::uuid, 'Quel est le genre de « Klima » ?', 'mcq', '["der","die","das","Aucun"]'::jsonb, 2, 'Les noms grecs en *-ma* sont neutres : *das Klima, das Thema*.', 10),
    ('0bc51027-46aa-5a62-9c2d-ec6eb6241cc9'::uuid, '8ea3c4b3-f17c-566b-9fd8-a223d2d834f6'::uuid, 'Quel est le genre de « Universität » ?', 'mcq', '["der","die","das","Il varie"]'::jsonb, 1, 'Les noms en *-tät* sont féminins.', 11),
    ('0e489675-48be-5708-a580-6427e9ed2867'::uuid, '8ea3c4b3-f17c-566b-9fd8-a223d2d834f6'::uuid, 'Quel nom est masculin ?', 'mcq', '["die Zeitung","der Frühling","das Museum","die Bäckerei"]'::jsonb, 1, 'Le suffixe *-ling* donne des masculins.', 12),
    ('81761f11-fd2d-52b3-9acf-b247add5ce33'::uuid, '1a50c77b-07ae-5574-9a98-e2c0417d10cd'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Ich sehe den Student.","Ich sehe den Studenten.","Ich sehe der Studenten.","Ich sehe dem Student."]'::jsonb, 1, '*der Student* est un masculin faible : *den Studenten* à l’accusatif.', 1),
    ('6b70b74e-c6d1-5fd6-a90c-6ce71fc4ab66'::uuid, '1a50c77b-07ae-5574-9a98-e2c0417d10cd'::uuid, 'À quel cas un masculin faible ne prend-il PAS de -en au singulier ?', 'mcq', '["Accusatif","Datif","Nominatif","Génitif"]'::jsonb, 2, 'Le nominatif singulier est la seule forme sans terminaison.', 2),
    ('7fdb1ddf-4a28-5f45-81a3-abcca34eaf70'::uuid, '1a50c77b-07ae-5574-9a98-e2c0417d10cd'::uuid, 'Lequel de ces noms est un masculin faible ?', 'mcq', '["der Tisch","der Franzose","der Lehrer","der Käse"]'::jsonb, 1, 'Nationalité en *-e* : *den Franzosen, dem Franzosen*.', 3),
    ('026dfd97-31f5-573c-83fc-31e44522013c'::uuid, '1a50c77b-07ae-5574-9a98-e2c0417d10cd'::uuid, 'Quel est l’accusatif singulier de « der Herr » ?', 'mcq', '["den Herr","den Herrn","den Herren","den Herres"]'::jsonb, 1, '*den Herrn* au singulier ; *die Herren* au pluriel.', 4),
    ('20d1494a-d826-564f-8a5c-8503fc55a6df'::uuid, '1a50c77b-07ae-5574-9a98-e2c0417d10cd'::uuid, '« Ich helfe dem ___ » (der Nachbar). Quelle forme complète la phrase ?', 'mcq', '["Nachbar","Nachbarn","Nachbars","Nachbarin"]'::jsonb, 1, '*der Nachbar* est un masculin faible : *dem Nachbarn*.', 5),
    ('6a8d5d3d-718e-52e4-a1a2-3f533a77cf71'::uuid, '1a50c77b-07ae-5574-9a98-e2c0417d10cd'::uuid, '« der Deutsche » est un masculin faible.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un adjectif substantivé : *ein Deutscher*, *der Deutsche*.', 6),
    ('98798a93-4938-5808-be16-e9585157cae2'::uuid, '1a50c77b-07ae-5574-9a98-e2c0417d10cd'::uuid, 'Quel suffixe signale souvent un masculin faible ?', 'mcq', '["-ung","-ist","-chen","-heit"]'::jsonb, 1, '*der Journalist, der Polizist* : *den Journalisten*.', 7),
    ('a5df976b-f854-530e-8bc5-140e19b3b1f4'::uuid, '1a50c77b-07ae-5574-9a98-e2c0417d10cd'::uuid, 'Quel est le génitif de « der Name » ?', 'mcq', '["des Namen","des Names","des Namens","der Namen"]'::jsonb, 2, 'Masculin mixte : *-n* à l’accusatif et au datif, *-ns* au génitif.', 8),
    ('b5690b8a-9d77-53f7-9820-2bc66931e281'::uuid, '1a50c77b-07ae-5574-9a98-e2c0417d10cd'::uuid, '« Das Kind spielt mit dem ___ » (der Junge). Quelle forme complète la phrase ?', 'mcq', '["Junge","Jungen","Junges","Jungem"]'::jsonb, 1, 'Masculin en *-e* désignant un être vivant : *dem Jungen*.', 9),
    ('13135156-1f80-532f-96b1-c81218b8960d'::uuid, '1a50c77b-07ae-5574-9a98-e2c0417d10cd'::uuid, 'Quelle forme est correcte ?', 'mcq', '["die Rechte des Menschs","die Rechte des Menschen","die Rechte der Mensch","die Rechte des Mensches"]'::jsonb, 1, 'Génitif d’un masculin faible : *des Menschen*.', 10),
    ('faa112e4-b47f-5d01-9be4-2561d35262ca'::uuid, '1a50c77b-07ae-5574-9a98-e2c0417d10cd'::uuid, '« der Käse » est un masculin faible parce qu’il finit par -e.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seuls les masculins en *-e* désignant des êtres vivants le sont ; *den Käse*.', 11),
    ('650ad3a0-efab-5eec-9e69-f11dde7a333a'::uuid, '1a50c77b-07ae-5574-9a98-e2c0417d10cd'::uuid, 'Comment dit-on « J’interroge le policier » ?', 'mcq', '["Ich frage den Polizist.","Ich frage den Polizisten.","Ich frage dem Polizisten.","Ich frage der Polizist."]'::jsonb, 1, '*fragen* + accusatif, et *der Polizist* est faible : *den Polizisten*.', 12),
    ('bfdfcecd-e863-5e95-a2c6-5abdb802f571'::uuid, 'e9962b8c-efed-55b8-ae8a-a867d56472f1'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Ich bleibe zu Hause, weil ich bin krank.","Ich bleibe zu Hause, weil ich krank bin.","Ich bleibe zu Hause, denn ich krank bin.","Ich bleibe zu Hause, weil bin ich krank."]'::jsonb, 1, 'Après *weil*, le verbe conjugué va à la fin.', 1),
    ('c78f6d58-ce79-511f-99f7-d7aa9663d097'::uuid, 'e9962b8c-efed-55b8-ae8a-a867d56472f1'::uuid, 'Après « denn », l’ordre des mots est…', 'mcq', '["verbe à la fin","ordre normal, verbe en 2e position","verbe en 1re position","libre"]'::jsonb, 1, '*denn* est coordonnant : position zéro, ordre normal.', 2),
    ('d5112e97-09c4-5af7-9e9d-4e09dcc0677f'::uuid, 'e9962b8c-efed-55b8-ae8a-a867d56472f1'::uuid, 'Où se place « nämlich » ?', 'mcq', '["Toujours en tête de phrase","Jamais en tête, après le verbe","Toujours en fin de phrase","Avant le sujet uniquement"]'::jsonb, 1, '*Ich bin nämlich krank* : jamais en première position.', 3),
    ('e35fa433-8a6a-5af6-8467-f3b513ebb7a2'::uuid, 'e9962b8c-efed-55b8-ae8a-a867d56472f1'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Es regnet, deshalb ich bleibe hier.","Es regnet, deshalb bleibe ich hier.","Es regnet, deshalb ich hier bleibe.","Es regnet, deshalb hier ich bleibe."]'::jsonb, 1, 'Après l’adverbe *deshalb*, le verbe reste 2e et le sujet passe derrière.', 4),
    ('a38a8306-2d65-5444-bfb0-de9f1814a709'::uuid, 'e9962b8c-efed-55b8-ae8a-a867d56472f1'::uuid, 'Que signifie « also » ?', 'mcq', '["Aussi","Donc","Alors que","Pourtant"]'::jsonb, 1, 'Faux ami : « aussi » se dit *auch* ; *also* = donc.', 5),
    ('323bbeec-42bf-521c-96b1-cf82746e4dbb'::uuid, 'e9962b8c-efed-55b8-ae8a-a867d56472f1'::uuid, '« ___ es regnet, bleiben wir hier. » Quel mot introduisant une cause connue complète la phrase ?', 'mcq', '["Denn","Da","Deshalb","Nämlich"]'::jsonb, 1, '*Da* introduit une cause connue, souvent en tête, verbe à la fin.', 6),
    ('178215d3-30c7-56ee-8518-adc4a77ee87d'::uuid, 'e9962b8c-efed-55b8-ae8a-a867d56472f1'::uuid, 'Quel cas suit la préposition « wegen » ?', 'mcq', '["Le datif","L’accusatif","Le génitif","Le nominatif"]'::jsonb, 2, '*wegen des Regens* : génitif (le datif est familier).', 7),
    ('a188ec65-19be-5d1f-a2ec-4e7fd18d1402'::uuid, 'e9962b8c-efed-55b8-ae8a-a867d56472f1'::uuid, 'On peut répondre à « Warum? » par « Denn ich bin müde. »', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On répond par *Weil ich müde bin.* ; *denn* ne s’emploie pas seul.', 8),
    ('a1e2c18d-1624-5371-88e7-683686cd0671'::uuid, 'e9962b8c-efed-55b8-ae8a-a867d56472f1'::uuid, '« Er war so müde, dass er sofort ___. » Quelle forme complète la phrase ?', 'mcq', '["schlief ein","einschlief","einschlafen","eingeschlafen"]'::jsonb, 1, 'Dans la subordonnée en *dass*, le verbe à préverbe se reforme en fin : *einschlief*.', 9),
    ('85076682-b472-56d1-b049-f8120ed54e27'::uuid, 'e9962b8c-efed-55b8-ae8a-a867d56472f1'::uuid, 'Lequel de ces mots exprime la conséquence ?', 'mcq', '["weil","denn","deswegen","nämlich"]'::jsonb, 2, '*deswegen* = c’est pourquoi ; les trois autres expriment la cause.', 10),
    ('fc0f970a-303d-5dd7-ae05-30ccc726d579'::uuid, 'e9962b8c-efed-55b8-ae8a-a867d56472f1'::uuid, 'Dans « Es regnete stark, sodass das Spiel ausfiel », « sodass » introduit…', 'mcq', '["une cause","une conséquence","un but","une opposition"]'::jsonb, 1, '*sodass* = si bien que : conséquence, verbe à la fin.', 11),
    ('986815bb-7c9a-55c5-869a-b6825a17af21'::uuid, 'e9962b8c-efed-55b8-ae8a-a867d56472f1'::uuid, '« Ich bin zu spät gekommen, denn der Zug ___ Verspätung. » Quel mot complète la phrase ?', 'mcq', '["hatte","hat gehabt","habe","hätte"]'::jsonb, 0, 'Après *denn*, ordre normal : le verbe conjugué en 2e position.', 12),
    ('b1e4bdbc-787b-5fc3-892e-9abb00e2a607'::uuid, 'ea5616e3-0007-5b8a-b268-ba515e511b61'::uuid, 'Que désignaient les « trois K » ?', 'mcq', '["Kaiser, Krieg, Kultur","Kinder, Küche, Kirche","Kunst, Kino, Konzert","Kopf, Körper, Kraft"]'::jsonb, 1, 'Enfants, cuisine, église : la sphère assignée aux femmes.', 1),
    ('27b77dda-c767-5adc-a6b3-597f21bc74d4'::uuid, 'ea5616e3-0007-5b8a-b268-ba515e511b61'::uuid, 'Quelle phrase de la Loi fondamentale défend l’égalité hommes-femmes ?', 'mcq', '["Die Würde des Menschen ist unantastbar","Männer und Frauen sind gleichberechtigt","Alle Macht geht vom Volke aus","Einigkeit und Recht und Freiheit"]'::jsonb, 1, 'L’article 3, défendu par Elisabeth Selbert en 1949.', 2),
    ('47f1b089-d195-59c9-bb54-f1b10a79c95f'::uuid, 'ea5616e3-0007-5b8a-b268-ba515e511b61'::uuid, 'Jusqu’en 1977 en RFA, une femme mariée avait besoin de l’accord de son mari pour travailler.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La réforme du droit du mariage de 1977 y a mis fin.', 3),
    ('68e30bfd-8859-5e57-bf37-a83506558737'::uuid, 'ea5616e3-0007-5b8a-b268-ba515e511b61'::uuid, 'Qu’était la FDJ ?', 'mcq', '["Un parti libéral","L’organisation de jeunesse de la RDA","Un journal","Une Église"]'::jsonb, 1, 'La *Freie Deutsche Jugend* encadrait la jeunesse est-allemande.', 4),
    ('329dfa21-69a4-57c9-8253-fb1397190e7a'::uuid, 'ea5616e3-0007-5b8a-b268-ba515e511b61'::uuid, 'Que crée la Cour constitutionnelle en 1983 ?', 'mcq', '["Le droit de vote à 16 ans","Un droit à l’autodétermination informationnelle","L’impôt d’Église","La liberté de la presse"]'::jsonb, 1, 'Un jalon de la protection des données personnelles.', 5),
    ('11523ea3-fc33-5ddb-a831-db053541649a'::uuid, 'ea5616e3-0007-5b8a-b268-ba515e511b61'::uuid, 'Pourquoi de nombreux Allemands ont-ils fait flouter leur maison sur Google Street View ?', 'mcq', '["Par souci de leur vie privée","Par obligation légale","Par erreur technique","Pour des raisons fiscales"]'::jsonb, 0, 'Un réflexe très allemand de protection de la sphère privée.', 6),
    ('f10a62e4-0603-5a50-a56d-bd8d1cb66974'::uuid, 'ea5616e3-0007-5b8a-b268-ba515e511b61'::uuid, 'Que signifie « die Überwachung » ?', 'mcq', '["La surveillance","La victoire","Le réveil","La traversée"]'::jsonb, 0, '*überwachen* = surveiller.', 7),
    ('51d445a0-456b-5bb1-b485-dfa304b9fc90'::uuid, 'ea5616e3-0007-5b8a-b268-ba515e511b61'::uuid, 'Qu’est-ce que la « Kirchensteuer » ?', 'mcq', '["Un don volontaire","L’impôt d’Église prélevé via l’État","Une taxe sur les monuments","Une amende"]'::jsonb, 1, 'Les membres des Églises paient cet impôt, collecté par l’administration fiscale.', 8),
    ('dcb7d3a6-3600-5fec-af25-e13fdf06c775'::uuid, 'ea5616e3-0007-5b8a-b268-ba515e511b61'::uuid, 'Quelle église de Leipzig a joué un rôle en 1989 ?', 'mcq', '["La Frauenkirche","L’église Saint-Nicolas","Le Dom de Cologne","L’église du Souvenir"]'::jsonb, 1, 'Ses prières pour la paix précédaient les manifestations du lundi.', 9),
    ('4e915bba-b634-5fe6-a187-413cb110bd71'::uuid, 'ea5616e3-0007-5b8a-b268-ba515e511b61'::uuid, 'Que signifie « die Öffentlichkeit » ?', 'mcq', '["L’ouverture","L’espace public, le public","La publicité","Le bureau"]'::jsonb, 1, 'L’opposé de *die Privatsphäre*.', 10),
    ('a91a9524-ed14-5d49-9739-63a3459d1795'::uuid, 'ea5616e3-0007-5b8a-b268-ba515e511b61'::uuid, 'Qui fut la première femme chancelière d’Allemagne ?', 'mcq', '["Ursula von der Leyen","Angela Merkel","Annalena Baerbock","Elisabeth Selbert"]'::jsonb, 1, 'Angela Merkel, de 2005 à 2021.', 11),
    ('14e8a085-bce2-5427-b6c8-1e57531a694a'::uuid, 'ea5616e3-0007-5b8a-b268-ba515e511b61'::uuid, 'Comment s’appelle le RGPD en allemand ?', 'mcq', '["DSGVO","BGB","GG","NetzDG"]'::jsonb, 0, '*Datenschutz-Grundverordnung*, entrée en application en 2018.', 12),
    ('f914bee5-0ab2-5a33-903a-3e48cd33ed7b'::uuid, 'd31755a2-cba4-58ba-844b-92424cd463ad'::uuid, 'Quand le Mur de Berlin a-t-il été construit ?', 'mcq', '["Le 9 novembre 1949","Le 13 août 1961","Le 17 juin 1953","Le 3 octobre 1990"]'::jsonb, 1, 'Dans la nuit du 12 au 13 août 1961.', 1),
    ('f1f74f51-6cbf-528c-8492-3d77280464c1'::uuid, 'd31755a2-cba4-58ba-844b-92424cd463ad'::uuid, 'Qu’est-ce que l’East Side Gallery ?', 'mcq', '["Un musée d’art moderne","Un pan de mur de 1,3 km peint par des artistes","Une galerie commerciale","Un poste-frontière"]'::jsonb, 1, 'Le plus long fragment conservé du Mur.', 2),
    ('659eb6de-2440-58ca-b338-50ee77535eea'::uuid, 'd31755a2-cba4-58ba-844b-92424cd463ad'::uuid, 'Pourquoi le 9 novembre n’est-il pas la fête nationale ?', 'mcq', '["C’est un jour de deuil trop chargé (pogroms de 1938)","Il tombe pendant les vacances","La RDA l’avait choisi","Il n’y a rien eu ce jour-là"]'::jsonb, 0, 'On a préféré le 3 octobre, jour de la réunification.', 3),
    ('3af0d948-039f-52db-a5b9-723d89cfd2b5'::uuid, 'd31755a2-cba4-58ba-844b-92424cd463ad'::uuid, 'Qu’était Prora ?', 'mcq', '["Un camp de concentration","Un complexe balnéaire nazi sur Rügen","Une caserne soviétique","Un château prussien"]'::jsonb, 1, 'Conçu pour la *Kraft durch Freude*, jamais achevé.', 4),
    ('df522aba-2928-54e4-be35-76dd1f24eb9a'::uuid, 'd31755a2-cba4-58ba-844b-92424cd463ad'::uuid, 'Que désigne le « Nischel » de Chemnitz ?', 'mcq', '["Une église","Une tête géante de Karl Marx","Un pont","Un stade"]'::jsonb, 1, 'Monument de 1971, devenu emblème de la ville.', 5),
    ('bdca32d8-00fc-53cc-9440-f6aa0579b476'::uuid, 'd31755a2-cba4-58ba-844b-92424cd463ad'::uuid, 'Que s’est-il passé le 9 novembre 1938 ?', 'mcq', '["La chute du Mur","La nuit de Cristal","La proclamation de la République","Le putsch de la brasserie"]'::jsonb, 1, 'Pogroms organisés contre les Juifs dans tout le Reich.', 6),
    ('abd3a417-c39a-5a6f-a0f5-d3a542a6e160'::uuid, 'd31755a2-cba4-58ba-844b-92424cd463ad'::uuid, 'Que signifie « die Gedenkstätte » ?', 'mcq', '["Le mémorial","Le cimetière militaire","Le musée d’art","L’hôtel de ville"]'::jsonb, 0, '*gedenken* (commémorer) + *die Stätte* (le lieu).', 7),
    ('ce5c5f6b-ec5b-5d39-bfae-a4419338f74b'::uuid, 'd31755a2-cba4-58ba-844b-92424cd463ad'::uuid, 'La Topographie de la terreur se trouve sur l’ancien siège…', 'mcq', '["du Reichstag","de la Gestapo","de la Stasi","du parti communiste"]'::jsonb, 1, 'Un centre de documentation sur les crimes du régime nazi.', 8),
    ('e596e830-f3cd-59fa-872c-948917272462'::uuid, 'd31755a2-cba4-58ba-844b-92424cd463ad'::uuid, 'Quelle attitude l’Allemagne a-t-elle le plus souvent choisie face à un patrimoine embarrassant ?', 'mcq', '["Tout détruire","Garder et documenter","Le cacher","Le vendre"]'::jsonb, 1, 'Conserver les traces en les expliquant.', 9),
    ('5a4bb1db-d5c9-5499-9e96-2612aafea4f0'::uuid, 'd31755a2-cba4-58ba-844b-92424cd463ad'::uuid, 'Klaus Iohannis, issu de la minorité allemande, a présidé…', 'mcq', '["la Pologne","la Roumanie","la Hongrie","la Tchéquie"]'::jsonb, 1, 'Saxon de Transylvanie, président de la Roumanie de 2014 à 2025.', 10),
