    ('d35b0155-cc7f-582c-9649-07670d18340f'::uuid, '240df771-86a0-54aa-a7ef-4163517e1812'::uuid, 'Le temps du subjonctif I dépend du temps du verbe introducteur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Er sagte, er sei krank* : le verbe introducteur au prétérit n’impose rien.', 8),
    ('2dfd6c3e-e064-5f35-9200-0cbe1d77c610'::uuid, '240df771-86a0-54aa-a7ef-4163517e1812'::uuid, '« ___ der Polizei gab es drei Verletzte. » Quel mot signifiant « selon » complète la phrase ?', 'mcq', '["Laut","Wegen","Trotz","Statt"]'::jsonb, 0, '*laut* + datif ou génitif : selon.', 9),
    ('88348d9b-4087-5deb-a608-0904e4c8a004'::uuid, '240df771-86a0-54aa-a7ef-4163517e1812'::uuid, 'Comment rapporter « Ich werde kommen » ?', 'mcq', '["Er sagt, er werde kommen.","Er sagt, er wird gekommen.","Er sagt, er komme gewesen.","Er sagt, er würde gekommen sein."]'::jsonb, 0, 'Futur rapporté : *werde* + infinitif.', 10),
    ('cd7fb3ea-2cf7-5453-8e9a-ea0bc77bda5c'::uuid, '240df771-86a0-54aa-a7ef-4163517e1812'::uuid, 'Que signifie « angeblich » ?', 'mcq', '["Certainement","Soi-disant, à ce qu’on prétend","Heureusement","Évidemment"]'::jsonb, 1, 'Il marque la distance du locuteur.', 11),
    ('c1a25796-ad68-51ee-a2a3-bb7a3adbe654'::uuid, '240df771-86a0-54aa-a7ef-4163517e1812'::uuid, 'Quel est le subjonctif I de « sie (pluriel) sind » ?', 'mcq', '["sie wären","sie seien","sie sein","sie sind"]'::jsonb, 1, '*sein* a des formes propres au pluriel : *seien*.', 12),
    ('069c0307-3cf2-5138-aae2-c2159736473d'::uuid, '22aad2a9-c27d-5e66-affb-b2b29459602e'::uuid, 'Comment dit-on « j’ai dû travailler » ?', 'mcq', '["Ich habe arbeiten gemusst.","Ich habe arbeiten müssen.","Ich bin arbeiten müssen.","Ich musste gearbeitet."]'::jsonb, 1, 'Modal avec infinitif au parfait : double infinitif.', 1),
    ('615676e9-e962-5e87-a0a7-780eed38d29b'::uuid, '22aad2a9-c27d-5e66-affb-b2b29459602e'::uuid, 'Quand emploie-t-on le participe « gekonnt » ?', 'mcq', '["Toujours au parfait","Quand le modal est employé seul, sans infinitif","Dans une subordonnée","Jamais"]'::jsonb, 1, '*Ich habe es gekonnt* : modal sans infinitif.', 2),
    ('a75d95aa-5416-50a3-bc35-e89769735ab0'::uuid, '22aad2a9-c27d-5e66-affb-b2b29459602e'::uuid, 'Quel auxiliaire utilise-t-on avec le double infinitif ?', 'mcq', '["sein","haben","werden","Selon le verbe"]'::jsonb, 1, 'Toujours *haben*.', 3),
    ('af07aadb-5e26-5587-b180-44434a22fce9'::uuid, '22aad2a9-c27d-5e66-affb-b2b29459602e'::uuid, 'Comment dit-on « j’ai fait réparer mon vélo » ?', 'mcq', '["Ich habe mein Fahrrad reparieren lassen.","Ich habe mein Fahrrad repariert gelassen.","Ich habe mein Fahrrad lassen repariert.","Ich ließ mein Fahrrad repariert."]'::jsonb, 0, '*lassen* suit la même règle que les modaux.', 4),
    ('780cd7b1-743b-5b81-9e74-ad6334be7d82'::uuid, '22aad2a9-c27d-5e66-affb-b2b29459602e'::uuid, 'Dans une subordonnée, où se place l’auxiliaire avec un double infinitif ?', 'mcq', '["À la toute fin","Devant les deux infinitifs","Juste après la conjonction","Entre les deux infinitifs"]'::jsonb, 1, '*…, weil ich habe arbeiten müssen.*', 5),
    ('27949fdd-fb50-5cf9-9873-bf42f8871d84'::uuid, '22aad2a9-c27d-5e66-affb-b2b29459602e'::uuid, '« Du hättest mich anrufen ___. » Quel mot complète la phrase ?', 'mcq', '["gesollt","sollen","sollte","soll"]'::jsonb, 1, 'Subjonctif II passé avec double infinitif : *hättest … anrufen sollen*.', 6),
    ('35d0e551-c73b-5d65-a3a8-91e34f364308'::uuid, '22aad2a9-c27d-5e66-affb-b2b29459602e'::uuid, 'Quelle subordonnée est correcte ?', 'mcq', '["…, weil er nicht kommen können hat.","…, weil er nicht hat kommen können.","…, weil er hat nicht kommen können.","…, weil er nicht kommen hat können."]'::jsonb, 1, 'L’auxiliaire précède le bloc des deux infinitifs.', 7),
    ('ee439339-c9c4-5e35-9225-9ced81ab0688'::uuid, '22aad2a9-c27d-5e66-affb-b2b29459602e'::uuid, '« Ich hätte mehr lernen sollen » exprime…', 'mcq', '["un projet","un regret","une obligation présente","une permission"]'::jsonb, 1, 'Subjonctif II passé : j’aurais dû.', 8),
    ('c984e414-fabc-59c4-8a74-3d893be2aadd'::uuid, '22aad2a9-c27d-5e66-affb-b2b29459602e'::uuid, 'On dit « Ich habe es gemusst » quand le modal n’est suivi d’aucun infinitif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sans infinitif, le modal prend son participe.', 9),
    ('2971ec55-2b78-5e67-bd23-4d785f549d66'::uuid, '22aad2a9-c27d-5e66-affb-b2b29459602e'::uuid, 'Comment dit-on « Brecht n’a pas voulu apprendre le danois » ?', 'mcq', '["Brecht hat die dänische Sprache nicht lernen wollen.","Brecht hat die dänische Sprache nicht gelernt gewollt.","Brecht ist die dänische Sprache nicht lernen wollen.","Brecht wollte die dänische Sprache nicht gelernt haben."]'::jsonb, 0, 'Double infinitif : *lernen wollen*, auxiliaire *hat*.', 10),
    ('c121d872-da6c-5adb-9f35-d6f806aad96c'::uuid, '22aad2a9-c27d-5e66-affb-b2b29459602e'::uuid, 'Quel est le plus-que-parfait de « Er kann nicht kommen » ?', 'mcq', '["Er hatte nicht kommen können.","Er war nicht kommen können.","Er hatte nicht gekommen gekonnt.","Er konnte nicht gekommen."]'::jsonb, 0, '*hatte* + double infinitif.', 11),
    ('c80469d6-614e-500a-9f99-2b53f6cce9da'::uuid, '22aad2a9-c27d-5e66-affb-b2b29459602e'::uuid, '« Ich habe ihn kommen sehen » signifie…', 'mcq', '["Je l’ai vu venir","Je l’ai fait venir","Je voulais qu’il vienne","Il m’a vu venir"]'::jsonb, 0, '*sehen* + infinitif se construit souvent en double infinitif.', 12),
    ('9ecd3868-688f-5982-8c91-d06ec06bebb0'::uuid, '0597e167-eb51-526f-83e4-5f58f607b2d6'::uuid, 'Comment se forme le participe I ?', 'mcq', '["ge- + radical + t","infinitif + d","radical + end","zu + infinitif"]'::jsonb, 1, '*blühen* → *blühend*, *lesen* → *lesend*.', 1),
    ('7e32782b-cc87-5ba3-8dcf-5afc645bbe8a'::uuid, '0597e167-eb51-526f-83e4-5f58f607b2d6'::uuid, 'Que signifie « die blühende Landschaft » ?', 'mcq', '["Le paysage fleuri il y a longtemps","Le paysage en fleurs","Le paysage à fleurir","Le paysage fané"]'::jsonb, 1, 'Le participe I exprime une action en cours, active.', 2),
    ('5c657bf1-2200-5e70-9702-2018ef59ae0f'::uuid, '0597e167-eb51-526f-83e4-5f58f607b2d6'::uuid, 'Dans « die von den Nazis verbannten Künstler », quel est le nom noyau ?', 'mcq', '["Nazis","Künstler","verbannten","von"]'::jsonb, 1, 'L’article *die* annonce *Künstler*, placé à la fin du groupe.', 3),
    ('908f4e57-8e3e-5cc1-b353-623570899e6d'::uuid, '0597e167-eb51-526f-83e4-5f58f607b2d6'::uuid, 'Quelle relative équivaut à « die im Frühling blühende Landschaft » ?', 'mcq', '["die Landschaft, die im Frühling blüht","die Landschaft, die im Frühling geblüht wurde","die Landschaft, die im Frühling blühen muss","die Landschaft, der im Frühling blüht"]'::jsonb, 0, 'Participe I actif → relative à l’actif.', 4),
    ('4877fc4b-e623-5014-a597-1cfd574e59ed'::uuid, '0597e167-eb51-526f-83e4-5f58f607b2d6'::uuid, 'Le participe II employé comme épithète a en général un sens…', 'mcq', '["actif et en cours","passif ou accompli","futur","impératif"]'::jsonb, 1, '*die gestohlene Tasche* : le sac qui a été volé.', 5),
    ('f6e52def-7ba6-5245-9679-809bb6ad960b'::uuid, '0597e167-eb51-526f-83e4-5f58f607b2d6'::uuid, 'Un participe épithète se décline comme un adjectif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*ein schlafendes Kind*, *mit der gestohlenen Tasche*.', 6),
    ('bebd225d-7e8c-5128-9d76-93977e13552e'::uuid, '0597e167-eb51-526f-83e4-5f58f607b2d6'::uuid, 'Que signifie « die zu lösende Aufgabe » ?', 'mcq', '["La tâche résolue","La tâche à résoudre","La tâche qui résout","La tâche impossible"]'::jsonb, 1, '*zu* + participe I : ce qui doit être fait.', 7),
    ('a6f3ea1f-68b4-507a-9b0f-3f7081af11c5'::uuid, '0597e167-eb51-526f-83e4-5f58f607b2d6'::uuid, 'Traduis « das 1949 verabschiedete Grundgesetz ».', 'mcq', '["La Loi fondamentale qui adoptera en 1949","La Loi fondamentale adoptée en 1949","La Loi fondamentale abolie en 1949","La Loi fondamentale adoptant 1949"]'::jsonb, 1, '*verabschiedet* : participe II, adoptée.', 8),
    ('02a97a2b-9f32-5a9e-9b8b-cc7c56f4e4f3'::uuid, '0597e167-eb51-526f-83e4-5f58f607b2d6'::uuid, '« Die Zahl der in Armut ___ Menschen steigt. » Quel participe complète la phrase ?', 'mcq', '["lebenden","gelebten","lebende","lebend"]'::jsonb, 0, 'Participe I décliné après l’article *der* (génitif pluriel) : *lebenden*.', 9),
    ('f76cd298-0d92-5ad4-88d3-13cb3b5197da'::uuid, '0597e167-eb51-526f-83e4-5f58f607b2d6'::uuid, 'Quel indice signale un groupe participial épithète ?', 'mcq', '["Un article suivi d’un verbe conjugué","Un article suivi d’une préposition ou d’un complément au lieu d’un nom","Une virgule","Un point d’exclamation"]'::jsonb, 1, 'L’article attend son nom, qui arrive plus loin.', 10),
    ('e305968a-1137-549f-a1f7-c01c0d333e34'::uuid, '0597e167-eb51-526f-83e4-5f58f607b2d6'::uuid, 'Que signifie « ein nicht zu unterschätzendes Problem » ?', 'mcq', '["Un problème sous-estimé","Un problème à ne pas sous-estimer","Un problème mineur","Un problème résolu"]'::jsonb, 1, '*nicht zu* + participe I : qu’il ne faut pas…', 11),
    ('fae64a99-c31c-5709-a311-16a896cdda2d'::uuid, '0597e167-eb51-526f-83e4-5f58f607b2d6'::uuid, '« die seit Jahren steigenden Mieten » signifie…', 'mcq', '["les loyers qui ont baissé","les loyers qui augmentent depuis des années","les loyers à augmenter","les loyers de l’an dernier"]'::jsonb, 1, '*steigend* : participe I de *steigen*, augmenter.', 12),
    ('e3d0f839-b91f-57ed-ace2-6f272ba0e902'::uuid, 'f1e58a5a-8539-58e9-a4f5-693fe2d8b110'::uuid, 'Que signifie « irgendwo » ?', 'mcq', '["Nulle part","Quelque part","Partout","Ici"]'::jsonb, 1, '*irgend-* + *wo* : un lieu indéterminé.', 1),
    ('57e2b643-392b-5981-9c9e-97e3700b15ce'::uuid, 'f1e58a5a-8539-58e9-a4f5-693fe2d8b110'::uuid, 'Comment dit-on « nulle part » ?', 'mcq', '["irgendwo","nirgendwo","niemals","nirgendwann"]'::jsonb, 1, '*nirgendwo* ou *nirgends*.', 2),
    ('fa70eca2-00dd-549a-b06c-835b9c2ddf3c'::uuid, 'f1e58a5a-8539-58e9-a4f5-693fe2d8b110'::uuid, 'Quelle phrase est correcte pour « je n’ai vu personne » ?', 'mcq', '["Ich habe nicht niemanden gesehen.","Ich habe niemanden gesehen.","Ich habe nicht jemand gesehen.","Ich habe kein jemand gesehen."]'::jsonb, 1, 'Une seule négation : *niemanden*.', 3),
    ('5cef1b3d-ef33-53b1-93bf-f37c9c90c2c4'::uuid, 'f1e58a5a-8539-58e9-a4f5-693fe2d8b110'::uuid, 'Que signifie « irgendwann » ?', 'mcq', '["Jamais","Un jour, à un moment","Toujours","Maintenant"]'::jsonb, 1, '*Irgendwann schaffe ich das* : un jour, j’y arriverai.', 4),
    ('5e4c1686-0f0e-57ac-8892-39a47dddc692'::uuid, 'f1e58a5a-8539-58e9-a4f5-693fe2d8b110'::uuid, 'Comment dit-on « quelque chose de nouveau » ?', 'mcq', '["etwas neu","etwas Neues","etwas neues","etwas Neue"]'::jsonb, 1, 'Adjectif substantivé neutre : majuscule et *-es*.', 5),
    ('9ca642cc-ec56-5b55-934b-97f2b3d95ab3'::uuid, 'f1e58a5a-8539-58e9-a4f5-693fe2d8b110'::uuid, '« Ich habe mit ___ gesprochen. » (personne) Quelle forme complète la phrase ?', 'mcq', '["niemand","niemanden","niemandem","niemandes"]'::jsonb, 2, '*mit* + datif : *niemandem*.', 6),
    ('b678c4a2-248f-5a00-99d3-cb8b4755c02e'::uuid, 'f1e58a5a-8539-58e9-a4f5-693fe2d8b110'::uuid, 'Que signifie « irgendwie » ?', 'mcq', '["D’une manière ou d’une autre","Nulle part","Pourquoi","Comme toujours"]'::jsonb, 0, 'Une manière indéterminée.', 7),
    ('255fa1d7-2e44-57db-888e-133ade15a7c7'::uuid, 'f1e58a5a-8539-58e9-a4f5-693fe2d8b110'::uuid, '« Irgendein Schüler weiß es » signifie…', 'mcq', '["Aucun élève ne le sait","Un élève quelconque le sait","Chaque élève le sait","Un seul élève le sait"]'::jsonb, 1, '*irgendein* : un … quelconque.', 8),
    ('a5941464-3449-5941-9f6e-c6fc23a7944e'::uuid, 'f1e58a5a-8539-58e9-a4f5-693fe2d8b110'::uuid, 'En allemand, on peut cumuler deux négations comme « nicht » et « niemand ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une seule négation par idée : *niemand* suffit.', 9),
    ('634f8e64-407e-5da3-b0b4-6f282810a9b6'::uuid, 'f1e58a5a-8539-58e9-a4f5-693fe2d8b110'::uuid, 'Quel est le datif de « man » ?', 'mcq', '["man","einen","einem","mans"]'::jsonb, 2, '*man* → *einen* (acc.) → *einem* (dat.).', 10),
    ('e577fa03-4075-58b5-ae1a-e4fe3608fba0'::uuid, 'f1e58a5a-8539-58e9-a4f5-693fe2d8b110'::uuid, 'Comment dit-on « rien de spécial » ?', 'mcq', '["nichts Besonderes","nicht besonders","nichts besondere","kein Besonderes"]'::jsonb, 0, '*nichts* + adjectif substantivé neutre.', 11),
    ('8ec36f88-135a-539a-a617-637021d0b7a0'::uuid, 'f1e58a5a-8539-58e9-a4f5-693fe2d8b110'::uuid, 'Quel mot est l’opposé de « irgendwann » ?', 'mcq', '["nirgends","nie","nichts","niemand"]'::jsonb, 1, 'Un jour ↔ jamais.', 12),
    ('9fa5774f-67ac-5ad9-a4c3-36568c1da2e8'::uuid, '1e993466-bf85-56bb-94a3-52e26c09ba8e'::uuid, 'Que traduit « indem » le plus souvent ?', 'mcq', '["Le but","Le moyen (en + gérondif)","La cause","Le temps passé"]'::jsonb, 1, '*Man lernt, indem man liest* : en lisant.', 1),
    ('2134dc07-122c-5744-94f8-0219599fad8e'::uuid, '1e993466-bf85-56bb-94a3-52e26c09ba8e'::uuid, 'Où se place le verbe conjugué après « indem » ?', 'mcq', '["En 2e position","À la fin","En 1re position","Juste après indem"]'::jsonb, 1, '*indem* est un subordonnant.', 2),
    ('67271eb6-49de-5a68-a84c-a7225a498d5b'::uuid, '1e993466-bf85-56bb-94a3-52e26c09ba8e'::uuid, 'Comment traduire « en mangeant » (simultanéité) ?', 'mcq', '["indem man isst","beim Essen","ohne zu essen","dadurch essen"]'::jsonb, 1, '*beim* + infinitif pour la simultanéité ; *indem* pour le moyen.', 3),
    ('8601b181-e234-50dd-a474-b923cebf7584'::uuid, '1e993466-bf85-56bb-94a3-52e26c09ba8e'::uuid, 'Comment dit-on « il partit sans dire un mot » ?', 'mcq', '["Er ging, ohne ein Wort zu sagen.","Er ging, ohne dass ein Wort sagen.","Er ging, ohne sagen ein Wort.","Er ging, indem er kein Wort sagte zu."]'::jsonb, 0, 'Même sujet : *ohne … zu*.', 4),
    ('576a1c15-28ae-51aa-84b9-1584ae056710'::uuid, '1e993466-bf85-56bb-94a3-52e26c09ba8e'::uuid, 'Quand emploie-t-on « ohne dass » plutôt que « ohne … zu » ?', 'mcq', '["Quand les sujets sont différents","Au passé seulement","À l’oral seulement","Jamais"]'::jsonb, 0, '*Er ging, ohne dass ich es merkte.*', 5),
    ('135fc95e-21cd-58d2-b1c5-3c1aa6ff197e'::uuid, '1e993466-bf85-56bb-94a3-52e26c09ba8e'::uuid, '« Statt zu lernen, spielt er » signifie…', 'mcq', '["Pour apprendre, il joue","Au lieu de travailler, il joue","Après avoir travaillé, il joue","Il joue en apprenant"]'::jsonb, 1, '*(an)statt … zu* : au lieu de.', 6),
    ('130f4751-ff2a-5db9-93e1-b3686a341c94'::uuid, '1e993466-bf85-56bb-94a3-52e26c09ba8e'::uuid, 'Dans « dadurch, dass… », que fait « dadurch » ?', 'mcq', '["Il annonce une subordonnée de moyen","Il exprime le temps","Il remplace une personne","Il marque une opposition"]'::jsonb, 0, 'Il met l’accent sur le moyen exprimé par la subordonnée.', 7),
    ('dd75836d-c1e6-5c9b-ba5f-62a1b5930ca0'::uuid, '1e993466-bf85-56bb-94a3-52e26c09ba8e'::uuid, '« Man lernt eine Sprache, indem man viel ___. » Quelle forme complète la phrase ?', 'mcq', '["liest","lesen","gelesen","lese"]'::jsonb, 0, 'Verbe conjugué à la fin : *liest*.', 8),
    ('f19578ce-6c71-5c13-b98e-2208b8cdff1b'::uuid, '1e993466-bf85-56bb-94a3-52e26c09ba8e'::uuid, 'Avec « indem », les deux propositions ont en général le même sujet.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme le gérondif français.', 9),
    ('6a5efb39-dbdb-53ca-83ad-a1659f7507fb'::uuid, '1e993466-bf85-56bb-94a3-52e26c09ba8e'::uuid, 'Quelle question porte sur le moyen ?', 'mcq', '["Wodurch?","Wann?","Wo?","Wem?"]'::jsonb, 0, '*Wodurch?* ou *Wie?* : par quel moyen ?', 10),
    ('ffaf3da0-1e25-5813-9b6c-851fd1b53eaf'::uuid, '1e993466-bf85-56bb-94a3-52e26c09ba8e'::uuid, 'Que signifie « durch viel Lesen » ?', 'mcq', '["Malgré beaucoup de lecture","Par beaucoup de lecture","Pendant la lecture","Sans lire"]'::jsonb, 1, '*durch* + accusatif exprime le moyen.', 11),
    ('ed2c768c-159a-53d6-9f0e-4933e132e060'::uuid, '1e993466-bf85-56bb-94a3-52e26c09ba8e'::uuid, 'Quelle phrase exprime le moyen ?', 'mcq', '["Beim Lesen höre ich Musik.","Indem wir weniger Auto fahren, schützen wir das Klima.","Während ich lese, schläft er.","Bevor ich lese, esse ich."]'::jsonb, 1, 'En roulant moins : moyen.', 12),
    ('e9bfcb2d-76b5-5b62-87a8-98bdb9749469'::uuid, '9b110631-dbbb-50f2-8f06-27f03a4580c8'::uuid, 'Que signifie « Er ist wohl krank » ?', 'mcq', '["Il est très malade","Il est sans doute malade","Il n’est pas malade","Il est bien malade (c’est certain)"]'::jsonb, 1, '*wohl* marque la supposition.', 1),
    ('f4ec314d-628c-52bf-8b37-704011c01400'::uuid, '9b110631-dbbb-50f2-8f06-27f03a4580c8'::uuid, '« Komm doch mit! » est…', 'mcq', '["un ordre sec","une invitation insistante","un refus","une question"]'::jsonb, 1, '*doch* adoucit et insiste : viens donc avec nous !', 2),
    ('9b6b176a-6d34-53fc-9c76-9ffcec6a0ece'::uuid, '9b110631-dbbb-50f2-8f06-27f03a4580c8'::uuid, 'Quelle particule exprime une évidence partagée ?', 'mcq', '["ja","mal","bloß","denn"]'::jsonb, 0, '*Sie wissen ja…* : vous le savez bien.', 3),
    ('f81bc31f-cfe4-56ea-a47b-45f2c343024c'::uuid, '9b110631-dbbb-50f2-8f06-27f03a4580c8'::uuid, 'Que signifie « Mach das bloß nicht! » ?', 'mcq', '["Fais-le seulement","Surtout ne fais pas ça !","Fais-le vite","Tu ne l’as pas fait"]'::jsonb, 1, '*bloß* renforce un avertissement.', 4),
    ('42ab21da-8187-529a-a774-9454d4e37b8d'::uuid, '9b110631-dbbb-50f2-8f06-27f03a4580c8'::uuid, '« Das ist eben so » exprime…', 'mcq', '["la surprise","la résignation","la colère","la supposition"]'::jsonb, 1, '*eben* / *halt* : c’est comme ça, on n’y peut rien.', 5),
    ('838dd20b-12b3-5b92-828d-a7316fc056ae'::uuid, '9b110631-dbbb-50f2-8f06-27f03a4580c8'::uuid, 'Dans « Was ist denn los? », « denn » signifie…', 'mcq', '["car","donc, marque l’intérêt dans la question","alors, conséquence","mais"]'::jsonb, 1, 'Particule de question, sans valeur de cause.', 6),
    ('f230f52c-3dc7-5a40-ae77-076d5a685aeb'::uuid, '9b110631-dbbb-50f2-8f06-27f03a4580c8'::uuid, 'Une particule modale est normalement accentuée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est inaccentuée ; accentuée, elle change de sens.', 7),
    ('6117edbc-a943-5169-9e6f-3f13bfc02def'::uuid, '9b110631-dbbb-50f2-8f06-27f03a4580c8'::uuid, 'Que signifie « Wie heißt du eigentlich? » ?', 'mcq', '["Au fait, comment tu t’appelles ?","Comment tu t’appelles vraiment, officiellement ?","Tu t’appelles comment déjà, encore ?","Pourquoi tu t’appelles ainsi ?"]'::jsonb, 0, '*eigentlich* ouvre une nouvelle orientation : au fait.', 8),
    ('2636e0c3-6a99-5a3e-bc3e-9a156bbc8db7'::uuid, '9b110631-dbbb-50f2-8f06-27f03a4580c8'::uuid, 'Quelle phrase exprime un reproche (je te l’avais dit) ?', 'mcq', '["Das ist ja teuer!","Das ist doch teuer!","Das ist wohl teuer.","Das ist mal teuer."]'::jsonb, 1, '*doch* rappelle ce que l’autre aurait dû savoir.', 9),
    ('6d701d4e-2235-5848-a29b-a3dec13d8558'::uuid, '9b110631-dbbb-50f2-8f06-27f03a4580c8'::uuid, 'Que fait « mal » dans « Komm mal her! » ?', 'mcq', '["Il exprime la répétition","Il adoucit la demande","Il exprime la négation","Il indique le passé"]'::jsonb, 1, '*mal* rend la demande plus familière et moins brusque.', 10),
    ('a81fe498-5f53-5f8d-8ec3-b5c372dfd684'::uuid, '9b110631-dbbb-50f2-8f06-27f03a4580c8'::uuid, '« Wenn ich bloß Zeit hätte! » exprime…', 'mcq', '["un souhait","un ordre","un constat","un reproche"]'::jsonb, 0, 'Si seulement j’avais le temps !', 11),
    ('d3b566f4-f0d9-587a-89af-1ed4dbc237bd'::uuid, '9b110631-dbbb-50f2-8f06-27f03a4580c8'::uuid, 'Dans « Seine Reaktion war ja zu erwarten », que montre « ja » ?', 'mcq', '["Que le narrateur est surpris","Que la réaction était prévisible pour tous","Que la réaction est niée","Une question"]'::jsonb, 1, 'Évidence partagée : bien sûr, on s’y attendait.', 12),
    ('8c750094-db06-5c23-9b7b-4cae7b9d9e12'::uuid, '42cc61e0-7492-579e-a7dd-1b8ae95d7726'::uuid, 'Quel voyage raconte *Diarios de motocicleta* ?', 'mcq', '["Le voyage de Colomb en 1492","Le voyage du jeune Ernesto Guevara en Amérique du Sud en 1952","Le pèlerinage de Saint-Jacques","L’exil de Neruda"]'::jsonb, 1, 'Le film de Walter Salles (2004) montre comment le voyage révèle l’injustice sociale.', 1),
    ('d67cd1f2-660b-5fbb-919e-67156057110e'::uuid, '42cc61e0-7492-579e-a7dd-1b8ae95d7726'::uuid, 'Quelle est la longueur approximative de la frontière entre le Mexique et les États-Unis ?', 'mcq', '["500 km","1 200 km","3 100 km","8 000 km"]'::jsonb, 2, 'Environ 3 100 km, dont une partie est murée.', 2),
    ('cb6dbfb2-14ef-5da2-906d-e906cd2cb4c0'::uuid, '42cc61e0-7492-579e-a7dd-1b8ae95d7726'::uuid, 'Comment surnomme-t-on le train de marchandises que prennent les migrants au Mexique ?', 'mcq', '["La Bestia","El Dorado","La Retirada","El Cayuco"]'::jsonb, 0, 'Les migrants voyagent sur son toit, au péril de leur vie.', 3),
    ('d17f13d7-2c0d-5fa3-a198-92e9e50983cf'::uuid, '42cc61e0-7492-579e-a7dd-1b8ae95d7726'::uuid, 'Que désigne la Retirada de 1939 ?', 'mcq', '["Le retour des émigrés d’Amérique","La fin de la Reconquête","La défaite de l’Invincible Armada","L’exil de près d’un demi-million de républicains vers la France"]'::jsonb, 3, 'À la fin de la guerre civile, ils fuient la victoire de Franco.', 4),
    ('2323d658-8077-58d7-8653-941d0bfc3f34'::uuid, '42cc61e0-7492-579e-a7dd-1b8ae95d7726'::uuid, 'Où se trouvent Ceuta et Melilla ?', 'mcq', '["Aux Canaries","En Afrique du Nord, face au Maroc","Dans les Pyrénées","Aux Baléares"]'::jsonb, 1, 'Ce sont deux villes espagnoles sur le continent africain.', 5),
    ('0ab05aad-d1ef-5615-8294-5d99214f57ae'::uuid, '42cc61e0-7492-579e-a7dd-1b8ae95d7726'::uuid, 'Depuis 2015, combien de Vénézuéliens environ ont quitté leur pays ?', 'mcq', '["Quelques milliers","Environ 100 000","Plus de sept millions","Un million exactement"]'::jsonb, 2, 'C’est l’un des plus grands exodes du monde actuel.', 6),
    ('60852323-6212-5884-b094-015cd2071224'::uuid, '42cc61e0-7492-579e-a7dd-1b8ae95d7726'::uuid, 'Que signifie *echar de menos* ?', 'mcq', '["Regretter, manquer de quelqu’un","Jeter","Oublier","Diminuer"]'::jsonb, 0, '*Echo de menos a mi familia* = ma famille me manque.', 7),
    ('c1e620f3-e748-52b9-ac16-a4500d0d32b0'::uuid, '42cc61e0-7492-579e-a7dd-1b8ae95d7726'::uuid, 'Comment dit-on « le pays d’accueil » ?', 'mcq', '["el país de origen","el país de salida","el país vecino","el país de acogida"]'::jsonb, 3, '*Acoger* = accueillir.', 8),
    ('81b6a6f4-5046-5efd-ae1c-71c07adba2d0'::uuid, '42cc61e0-7492-579e-a7dd-1b8ae95d7726'::uuid, 'Que sont les *cayucos* ?', 'mcq', '["Des pirogues de migrants vers les Canaries","Des trains","Des passeports","Des camps de réfugiés"]'::jsonb, 0, 'Venues d’Afrique de l’Ouest, elles tentent une traversée atlantique très dangereuse.', 9),
    ('9291230b-e634-5a6a-9fc7-508de53e1ddf'::uuid, '42cc61e0-7492-579e-a7dd-1b8ae95d7726'::uuid, 'Dans les années 1960, beaucoup d’Espagnols ont émigré vers la France, l’Allemagne ou la Suisse.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils fuyaient la pauvreté de l’Espagne franquiste.', 10),
    ('403c9400-797b-5979-89ce-b7d6096e076a'::uuid, '42cc61e0-7492-579e-a7dd-1b8ae95d7726'::uuid, 'Quelle formule sert à POSER un problème ?', 'mcq', '["En definitiva…","Cabe preguntarse si…","Por otro lado…","Ya que…"]'::jsonb, 1, '« On peut se demander si… » : idéal pour une problématique.', 11),
    ('1ca087c2-e83f-5319-bd41-3fb23d78e8d0'::uuid, '42cc61e0-7492-579e-a7dd-1b8ae95d7726'::uuid, 'Qui chante *Clandestino* (1998) ?', 'mcq', '["Mercedes Sosa","Shakira","Manu Chao","Víctor Jara"]'::jsonb, 2, 'La chanson donne voix aux sans-papiers : *Solo voy con mi pena…*', 12),
    ('d143dadc-f04d-5292-b76d-61e8d26b5726'::uuid, '0fb16220-9db3-52d1-b11c-d5dca89d3a2b'::uuid, 'En quelle année l’Espagne a-t-elle ouvert le mariage aux couples de même sexe ?', 'mcq', '["1978","2005","2015","1992"]'::jsonb, 1, 'Elle est l’un des premiers pays au monde à le faire ; l’Argentine suit en 2010.', 1),
    ('b144377f-1cb2-52a9-9f79-1793039fcd22'::uuid, '0fb16220-9db3-52d1-b11c-d5dca89d3a2b'::uuid, 'Qui est Rigoberta Menchú ?', 'mcq', '["Une chanteuse argentine","Une présidente chilienne","Une militante maya, prix Nobel de la paix 1992","Une peintre mexicaine"]'::jsonb, 2, 'Elle défend les droits des peuples autochtones du Guatemala.', 2),
    ('3820b1e0-e050-57ec-9235-7f3c672c8059'::uuid, '0fb16220-9db3-52d1-b11c-d5dca89d3a2b'::uuid, 'Quelle Constitution a fait de la Bolivie un « État plurinational » ?', 'mcq', '["Celle de 2009","Celle de 1825","Celle de 1952","Celle de 1978"]'::jsonb, 0, 'Elle reconnaît les peuples et les langues autochtones.', 3),
    ('02b3f2c9-686f-5585-b9bc-cbeee9692bc7'::uuid, '0fb16220-9db3-52d1-b11c-d5dca89d3a2b'::uuid, 'Que raconte le film *Campeones* (2018) ?', 'mcq', '["L’histoire d’un club de football","La vie d’un torero","Un voyage en Amérique","Une équipe de basket de joueurs ayant une déficience intellectuelle"]'::jsonb, 3, 'Les acteurs de l’équipe ont eux-mêmes une déficience intellectuelle ; le film a reçu le Goya du meilleur film.', 4),
    ('62ebd271-f340-5a30-9211-bdf9c4c5fa9e'::uuid, '0fb16220-9db3-52d1-b11c-d5dca89d3a2b'::uuid, 'Quelle langue parlaient les Aztèques ?', 'mcq', '["Le quechua","Le nahuatl","Le guarani","L’aymara"]'::jsonb, 1, 'Le nahuatl est encore parlé par plus d’un million de Mexicains.', 5),
    ('1d596d12-6d92-5c73-ba11-be7f572a9703'::uuid, '0fb16220-9db3-52d1-b11c-d5dca89d3a2b'::uuid, 'Combien de langues autochtones le Mexique reconnaît-il comme nationales ?', 'mcq', '["3","12","68","200"]'::jsonb, 2, 'La loi de 2003 leur donne le statut de langues nationales, à côté de l’espagnol.', 6),
    ('381bf604-82b1-5e47-9b8f-437b39a22c4f'::uuid, '0fb16220-9db3-52d1-b11c-d5dca89d3a2b'::uuid, 'Qu’est-ce que San Basilio de Palenque ?', 'mcq', '["Un village colombien fondé par des esclaves en fuite","Un quartier de Madrid","Une île des Caraïbes","Une réserve naturelle"]'::jsonb, 0, 'Ses habitants, afrodescendants, parlent une langue créole, le palenquero.', 7),
    ('3f4f9560-db6e-58d2-b9c3-2a2e707db972'::uuid, '0fb16220-9db3-52d1-b11c-d5dca89d3a2b'::uuid, 'Que signifie *la discapacidad* ?', 'mcq', '["La capacité","La discipline","La discrimination","Le handicap"]'::jsonb, 3, '*Una persona con discapacidad* = une personne handicapée.', 8),
    ('e0253829-b3d0-5e6a-ae99-6c742e7faea3'::uuid, '0fb16220-9db3-52d1-b11c-d5dca89d3a2b'::uuid, 'Evo Morales, président de la Bolivie de 2006 à 2019, est d’origine aymara.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il a été le premier chef d’État issu d’un peuple autochtone en Bolivie.', 9),
    ('f8d0849d-256f-5073-ae76-a4f7a3d20199'::uuid, '0fb16220-9db3-52d1-b11c-d5dca89d3a2b'::uuid, 'Après *Es necesario que…*, quel mode emploie-t-on ?', 'mcq', '["L’indicatif","Le subjonctif","L’infinitif","Le conditionnel"]'::jsonb, 1, 'Une nécessité exprimée par une tournure impersonnelle + *que* appelle le subjonctif.', 10),
    ('1350771c-fbdf-5605-87ce-53e6ada18aa5'::uuid, '0fb16220-9db3-52d1-b11c-d5dca89d3a2b'::uuid, 'Que signifie *la convivencia* ?', 'mcq', '["La convocation","La convivialité d’un repas","Le vivre-ensemble","La conviction"]'::jsonb, 2, '*Convivir* = vivre ensemble, cohabiter.', 11),
    ('9e2b62c7-a07b-5911-9cec-e65a628b3581'::uuid, '0fb16220-9db3-52d1-b11c-d5dca89d3a2b'::uuid, 'Au Paraguay, seul l’espagnol est langue officielle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le guarani est lui aussi langue officielle, et parlé par la majorité de la population.', 12),
    ('7a14adf5-cf8a-5dfa-9935-242e10688360'::uuid, 'c6adfbc0-3013-572f-9a1a-b4ba6668401f'::uuid, 'De quel roi Velázquez était-il le peintre ?', 'mcq', '["Charles Quint","Philippe II","Philippe IV","Alphonse XIII"]'::jsonb, 2, 'Au XVIIe siècle, il peint la cour et glorifie la monarchie.', 1),
    ('a8c9dd5b-0501-5b8f-9b7e-b556d7828764'::uuid, 'c6adfbc0-3013-572f-9a1a-b4ba6668401f'::uuid, 'Pourquoi l’État mexicain a-t-il commandé des fresques murales après la Révolution ?', 'mcq', '["Pour décorer les églises","Pour raconter l’histoire au peuple","Pour attirer les touristes","Pour imiter l’Europe"]'::jsonb, 1, 'À partir de 1921, Rivera, Orozco et Siqueiros peignent l’histoire nationale sur les murs publics.', 2),
    ('bbbea2f0-778b-5f4c-931f-8bba689e6582'::uuid, 'c6adfbc0-3013-572f-9a1a-b4ba6668401f'::uuid, 'Quel film de Buñuel, Palme d’or 1961, fut interdit en Espagne ?', 'mcq', '["Viridiana","Volver","Campeones","Roma"]'::jsonb, 0, 'La censure franquiste l’a jugé blasphématoire.', 3),
    ('6ea90042-fd87-52cd-96d9-d7771720783b'::uuid, 'c6adfbc0-3013-572f-9a1a-b4ba6668401f'::uuid, 'Qu’est-il arrivé à Víctor Jara en septembre 1973 ?', 'mcq', '["Il est parti en exil à Paris","Il a reçu le prix Nobel","Il est devenu ministre","Il a été assassiné après le coup d’État de Pinochet"]'::jsonb, 3, 'Chanteur engagé, il est tué quelques jours après le coup d’État.', 4),
    ('c1e92185-10b7-58ec-94bb-941269d57c23'::uuid, 'c6adfbc0-3013-572f-9a1a-b4ba6668401f'::uuid, 'Quand *Guernica* est-il arrivé en Espagne ?', 'mcq', '["En 1937","En 1981, après le retour de la démocratie","En 1975, à la mort de Franco","En 1992, pour les Jeux olympiques"]'::jsonb, 1, 'Picasso refusait que le tableau entre en Espagne tant que la démocratie n’y était pas rétablie.', 5),
    ('670a5e47-6c74-53f0-a249-4ba5289da169'::uuid, 'c6adfbc0-3013-572f-9a1a-b4ba6668401f'::uuid, 'Que sont les *arpilleras* chiliennes ?', 'mcq', '["Des chansons populaires","Des danses","Des tapisseries brodées pour dénoncer les disparitions","Des journaux clandestins"]'::jsonb, 2, 'Des femmes les brodaient sous Pinochet.', 6),
    ('ab245edc-e3a5-519a-aadd-58b4de16943d'::uuid, 'c6adfbc0-3013-572f-9a1a-b4ba6668401f'::uuid, 'Qui a chanté *Gracias a la vida* (1966) ?', 'mcq', '["Violeta Parra","Mercedes Sosa en premier","Víctor Jara","Shakira"]'::jsonb, 0, 'Violeta Parra l’a composée et enregistrée ; Mercedes Sosa l’a rendue célèbre dans toute l’Amérique.', 7),
    ('a230dd00-a448-52e5-a0a6-2859dd2d1f04'::uuid, 'c6adfbc0-3013-572f-9a1a-b4ba6668401f'::uuid, 'Pourquoi la fresque de Rivera au Rockefeller Center fut-elle détruite ?', 'mcq', '["Elle était trop grande","Elle s’effritait","Elle représentait Franco","Elle montrait Lénine"]'::jsonb, 3, 'Le commanditaire refusait ce portrait ; la fresque fut détruite en 1934.', 8),
    ('3ec38ec3-727d-5714-bb4f-7119ce315a02'::uuid, 'c6adfbc0-3013-572f-9a1a-b4ba6668401f'::uuid, 'Que signifie *comprometido* en parlant d’un artiste ?', 'mcq', '["Compromis","Engagé","Célèbre","Censuré"]'::jsonb, 1, '*Un artista comprometido* = un artiste engagé.', 9),
    ('da4ef29b-321e-5eeb-860a-0e03679d4a07'::uuid, 'c6adfbc0-3013-572f-9a1a-b4ba6668401f'::uuid, 'La censure franquiste a duré jusqu’en 1977.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle disparaît pendant la Transition, avant la Constitution de 1978.', 10),
    ('c3d8965b-aee9-5169-8690-b43269fb8d8b'::uuid, 'c6adfbc0-3013-572f-9a1a-b4ba6668401f'::uuid, 'Après *Esta obra consigue que el espectador…*, quel mode faut-il ?', 'mcq', '["L’indicatif","L’infinitif","Le subjonctif","Le gérondif"]'::jsonb, 2, '*Conseguir que* exprime un effet obtenu sur autrui : subjonctif.', 11),
    ('fa6c63d5-fea9-54bf-b7a6-74900628af5a'::uuid, 'c6adfbc0-3013-572f-9a1a-b4ba6668401f'::uuid, 'Quel nouveau nom le Valle de los Caídos a-t-il reçu en 2022 ?', 'mcq', '["Valle de la Paz","Valle de Cuelgamuros","Valle de la Memoria","Valle de Guernica"]'::jsonb, 1, 'La loi de mémoire démocratique a rendu au lieu son nom géographique.', 12),
    ('883765c8-1552-5a82-a787-3d3bb7511b91'::uuid, '1b49c3c1-99c5-55fc-bf37-2a365a97859e'::uuid, 'Quelle découverte a rendu célèbre Santiago Ramón y Cajal ?', 'mcq', '["Le vaccin contre la rage","La structure de l’ADN","Le système nerveux fait de cellules distinctes, les neurones","La circulation du sang"]'::jsonb, 2, 'C’est la « doctrine du neurone », fondement des neurosciences.', 1),
    ('d658d84e-167e-5382-8a78-41127ab5a43e'::uuid, '1b49c3c1-99c5-55fc-bf37-2a365a97859e'::uuid, 'En quelle année Ramón y Cajal a-t-il reçu le prix Nobel ?', 'mcq', '["1906","1959","1934","1898"]'::jsonb, 0, 'Il l’a partagé avec l’Italien Camillo Golgi.', 2),
    ('f3e31a9b-c628-54a3-b6fa-c24b23f9fcbd'::uuid, '1b49c3c1-99c5-55fc-bf37-2a365a97859e'::uuid, 'Comment Ramón y Cajal appelait-il les neurones ?', 'mcq', '["Les étoiles du cerveau","Les arbres de la pensée","Les soldats de l’esprit","Les papillons de l’âme"]'::jsonb, 3, '*Las mariposas del alma* : une image de dessinateur autant que de savant.', 3),
    ('e1aa87e0-b9a3-58d2-b92d-8c9d909e7dc1'::uuid, '1b49c3c1-99c5-55fc-bf37-2a365a97859e'::uuid, 'Avec qui Ramón y Cajal a-t-il partagé son prix Nobel ?', 'mcq', '["Severo Ochoa","Camillo Golgi","Louis Pasteur","Marie Curie"]'::jsonb, 1, 'Golgi avait inventé la coloration à l’argent que Cajal a perfectionnée.', 4),
    ('b079a85c-519d-5585-87df-61e6402e4266'::uuid, '1b49c3c1-99c5-55fc-bf37-2a365a97859e'::uuid, 'Que prévoit la « loi Rider » espagnole de 2021 ?', 'mcq', '["L’interdiction des vélos en ville","Des aides aux cyclistes","Que les livreurs des plateformes sont présumés salariés","La fin du télétravail"]'::jsonb, 2, 'Elle protège les livreurs contre le faux statut d’indépendant.', 5),
    ('3a31774a-ec8f-5bd3-952b-a8b669120757'::uuid, '1b49c3c1-99c5-55fc-bf37-2a365a97859e'::uuid, 'Quel autre Espagnol a reçu le Nobel de médecine, en 1959 ?', 'mcq', '["Severo Ochoa","Pablo Neruda","Juan Ramón Jiménez","Gabriel García Márquez"]'::jsonb, 0, 'Ses travaux portaient sur l’ARN ; les trois autres sont des Nobel de littérature.', 6),
    ('52650193-30bb-5e18-8fcd-3b0008be50e6'::uuid, '1b49c3c1-99c5-55fc-bf37-2a365a97859e'::uuid, 'Que signifie *el paro* en Espagne ?', 'mcq', '["La grève","Le chômage","Le parking","La paresse"]'::jsonb, 1, '*Estar en paro* = être au chômage ; la grève se dit *la huelga*.', 7),
    ('e409c798-b972-542f-b006-9fd07bf96df2'::uuid, '1b49c3c1-99c5-55fc-bf37-2a365a97859e'::uuid, 'Que signifie *el canon de belleza* ?', 'mcq', '["Le canon de beauté","Le salon de beauté","Le concours de beauté","Le produit de beauté"]'::jsonb, 0, 'Le modèle idéal imposé par une société.', 8),
    ('2b67e310-cdc4-56d3-8f4f-fb7b87da8d68'::uuid, '1b49c3c1-99c5-55fc-bf37-2a365a97859e'::uuid, 'Ramón y Cajal dessinait les neurones à la main.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ses milliers de dessins servent encore aujourd’hui dans l’enseignement.', 9),
    ('170ab9f5-be11-5185-aa1c-d3271074f24b'::uuid, '1b49c3c1-99c5-55fc-bf37-2a365a97859e'::uuid, 'Après *¿Es ético que…?*, quel mode faut-il ?', 'mcq', '["L’indicatif","L’infinitif","Le futur","Le subjonctif"]'::jsonb, 3, 'Un jugement de valeur + *que* entraîne le subjonctif : *¿Es ético que una clínica anuncie…?*', 10),
    ('9a9b2811-b801-5e75-9111-3d3245d2321a'::uuid, '1b49c3c1-99c5-55fc-bf37-2a365a97859e'::uuid, 'Que signifie *No cabe duda de que…* ?', 'mcq', '["Il n’y a pas de place pour…","Il ne fait aucun doute que…","Je doute que…","Il n’est pas certain que…"]'::jsonb, 1, 'Une certitude : suivie de l’indicatif.', 11),
    ('12aacc04-4694-5a6b-875c-9208f43ed435'::uuid, '1b49c3c1-99c5-55fc-bf37-2a365a97859e'::uuid, 'Dans quelle région est né Ramón y Cajal ?', 'mcq', '["En Galice","En Andalousie","En Navarre, à Petilla de Aragón","À Madrid"]'::jsonb, 2, 'Petilla de Aragón est une enclave navarraise entourée par l’Aragon.', 12),
    ('99fe5247-84aa-5e07-8463-c8e8fed3dcb1'::uuid, 'f37ff39e-82d9-5530-8d79-9ec91b5e3ae0'::uuid, 'Que désigne la Pachamama ?', 'mcq', '["Un volcan","La Terre-Mère des peuples andins","Une danse bolivienne","Une déesse aztèque de la guerre"]'::jsonb, 1, 'On la remercie par des offrandes, notamment en août.', 1),
    ('91f21f67-c0c9-511f-aa63-e78aa3fb4c63'::uuid, 'f37ff39e-82d9-5530-8d79-9ec91b5e3ae0'::uuid, 'Quel pays a reconnu le premier des droits à la nature dans sa Constitution, en 2008 ?', 'mcq', '["L’Espagne","Le Mexique","L’Équateur","Le Chili"]'::jsonb, 2, 'La Constitution équatorienne de 2008 fait de la nature un sujet de droit.', 2),
    ('a01fe41c-a748-543b-a429-e3a6295755b0'::uuid, 'f37ff39e-82d9-5530-8d79-9ec91b5e3ae0'::uuid, 'Où se trouve le parc national de Doñana ?', 'mcq', '["En Andalousie","En Galice","Aux Canaries","En Catalogne"]'::jsonb, 0, 'C’est l’une des plus grandes zones humides d’Europe.', 3),
    ('8f496bc4-28df-54e2-967c-87f30a19062f'::uuid, 'f37ff39e-82d9-5530-8d79-9ec91b5e3ae0'::uuid, 'Quelle menace pèse principalement sur Doñana ?', 'mcq', '["Les volcans","Le tourisme de ski","Les ouragans","Le pompage de l’eau pour l’agriculture"]'::jsonb, 3, 'L’irrigation assèche l’aquifère qui alimente les lagunes.', 4),
    ('465ac06a-3c06-5946-b431-78e650ae1b59'::uuid, 'f37ff39e-82d9-5530-8d79-9ec91b5e3ae0'::uuid, 'À quoi ressemblent les colonnes de la Sagrada Familia ?', 'mcq', '["À des vagues","À des arbres qui se ramifient","À des montagnes","À des nuages"]'::jsonb, 1, 'Gaudí voulait une forêt de pierre.', 5),
    ('5c886425-e0a6-55f9-b853-fea300f49b9c'::uuid, 'f37ff39e-82d9-5530-8d79-9ec91b5e3ae0'::uuid, 'Quel poète chilien a écrit le *Canto general* (1950) ?', 'mcq', '["Gabriela Mistral","Octavio Paz","Pablo Neruda","Federico García Lorca"]'::jsonb, 2, 'Il y chante la nature et l’histoire de tout le continent.', 6),
    ('88738f39-3bc5-5f89-bb10-6e375e2d8ca0'::uuid, 'f37ff39e-82d9-5530-8d79-9ec91b5e3ae0'::uuid, 'Que signifie *la sequía* ?', 'mcq', '["La sécheresse","La récolte","La soif","La forêt"]'::jsonb, 0, '*Seco* = sec ; *la sequía* = la sécheresse.', 7),
    ('3033cbdc-a908-50fc-930d-6578f221f4e1'::uuid, 'f37ff39e-82d9-5530-8d79-9ec91b5e3ae0'::uuid, 'Quelle part approximative du Costa Rica est protégée ?', 'mcq', '["Presque rien","La totalité","La moitié exactement","Environ un quart"]'::jsonb, 3, 'Le pays vit en partie de l’écotourisme.', 8),
    ('aa4a6dcc-9c0f-539c-af99-543c34a9fe1c'::uuid, 'f37ff39e-82d9-5530-8d79-9ec91b5e3ae0'::uuid, 'Les îles Galápagos appartiennent à l’Équateur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles sont célèbres pour les observations de Darwin.', 9),
    ('e8ff30ab-13f6-5338-a437-a490e8495edd'::uuid, 'f37ff39e-82d9-5530-8d79-9ec91b5e3ae0'::uuid, 'Que signifie *el invernadero* ?', 'mcq', '["L’hiver","La serre","L’inventaire","L’entrepôt"]'::jsonb, 1, 'Les serres d’Almería forment une « mer de plastique » visible depuis l’espace.', 10),
    ('006a8c98-ecd1-5db8-830e-0a019e18ff32'::uuid, 'f37ff39e-82d9-5530-8d79-9ec91b5e3ae0'::uuid, 'Quelle expression introduit une conséquence ?', 'mcq', '["Es urgente que","Hay que matizar","Por consiguiente","Convendría"]'::jsonb, 2, '*Por consiguiente* = par conséquent.', 11),
    ('49a83d8c-acf3-5e4e-b6c5-6baeded0ffeb'::uuid, 'f37ff39e-82d9-5530-8d79-9ec91b5e3ae0'::uuid, 'Comment dit-on « une espèce menacée d’extinction » ?', 'mcq', '["una especie en peligro de extinción","una especie amenazada de desaparición","una especie en extinción peligrosa","una especie peligrosa"]'::jsonb, 0, '*Estar en peligro de extinción* est l’expression consacrée.', 12),
    ('47491acd-d3e8-5e94-aed9-4260a109a303'::uuid, '292e54f4-0a41-5bcf-b6db-750aba39bdf1'::uuid, 'Combien de pays la cordillère des Andes traverse-t-elle ?', 'mcq', '["3","5","7","10"]'::jsonb, 2, 'Venezuela, Colombie, Équateur, Pérou, Bolivie, Chili, Argentine.', 1),
    ('4563a562-5075-5627-aa1b-0d0452d14b44'::uuid, '292e54f4-0a41-5bcf-b6db-750aba39bdf1'::uuid, 'Quel est le plus haut sommet des Amériques ?', 'mcq', '["L’Aconcagua","Le Chimborazo","Le Huascarán","Le Popocatépetl"]'::jsonb, 0, 'Situé en Argentine, il culmine à 6 961 m.', 2),
    ('2edfc958-a362-588a-958b-9244a8a09d6e'::uuid, '292e54f4-0a41-5bcf-b6db-750aba39bdf1'::uuid, 'Entre quels pays se trouve le lac Titicaca ?', 'mcq', '["Le Chili et l’Argentine","L’Équateur et la Colombie","Le Venezuela et la Colombie","Le Pérou et la Bolivie"]'::jsonb, 3, 'C’est l’un des plus hauts lacs navigables du monde, à plus de 3 800 m.', 3),
    ('77e4f2f8-4682-537e-b6a5-753245aedb5d'::uuid, '292e54f4-0a41-5bcf-b6db-750aba39bdf1'::uuid, 'Quelle était la capitale de l’Empire inca ?', 'mcq', '["Lima","Cuzco","Quito","La Paz"]'::jsonb, 1, 'Lima a été fondée par les Espagnols en 1535.', 4),
    ('d2281e8b-5e24-50ed-902d-7787db5fc63f'::uuid, '292e54f4-0a41-5bcf-b6db-750aba39bdf1'::uuid, 'Qui a révélé Machu Picchu au monde en 1911 ?', 'mcq', '["Simón Bolívar","Francisco Pizarro","Hiram Bingham","Pablo Neruda"]'::jsonb, 2, 'L’explorateur américain a fait connaître le site, que les paysans des environs connaissaient.', 5),
    ('c6c66d90-1372-5904-8824-76c5bdf335bf'::uuid, '292e54f4-0a41-5bcf-b6db-750aba39bdf1'::uuid, 'Quels pays forment le « triangle du lithium » ?', 'mcq', '["Bolivie, Chili, Argentine","Pérou, Équateur, Colombie","Mexique, Cuba, Venezuela","Espagne, Portugal, Maroc"]'::jsonb, 0, 'Leurs salars concentrent une grande part des réserves mondiales.', 6),
    ('470c61f5-63da-55b6-87e3-cd92e464cb9e'::uuid, '292e54f4-0a41-5bcf-b6db-750aba39bdf1'::uuid, 'De quel métal le Chili est-il le premier producteur mondial ?', 'mcq', '["L’or","L’argent","Le fer","Le cuivre"]'::jsonb, 3, 'Le cuivre est la première exportation chilienne.', 7),
    ('838660cc-995b-55ea-8820-91686c516f24'::uuid, '292e54f4-0a41-5bcf-b6db-750aba39bdf1'::uuid, 'Que signifie *el buen vivir* (*sumak kawsay*) ?', 'mcq', '["La gastronomie andine","Vivre en harmonie avec la communauté et la nature","Un parti politique","La richesse individuelle"]'::jsonb, 1, 'Le principe est inscrit dans les Constitutions de l’Équateur (2008) et de la Bolivie (2009).', 8),
    ('10accd60-a280-5f33-83c1-49c5e87735de'::uuid, '292e54f4-0a41-5bcf-b6db-750aba39bdf1'::uuid, 'Le quechua et l’aymara sont encore parlés par des millions de personnes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Surtout au Pérou, en Bolivie et en Équateur.', 9),
    ('b30634eb-0eea-5147-aba1-6d2609b62094'::uuid, '292e54f4-0a41-5bcf-b6db-750aba39bdf1'::uuid, 'Que signifie *el altiplano* ?', 'mcq', '["La plaine côtière","Le haut plateau","La forêt tropicale","Le sommet enneigé"]'::jsonb, 1, 'Le haut plateau andin, entre le Pérou, la Bolivie, le Chili et l’Argentine.', 10),
    ('0114ba8b-8ef6-5642-989a-54f31a5e69ff'::uuid, '292e54f4-0a41-5bcf-b6db-750aba39bdf1'::uuid, 'Qui a composé *El cóndor pasa* en 1913 ?', 'mcq', '["Víctor Jara","Violeta Parra","Daniel Alomía Robles","Simon et Garfunkel"]'::jsonb, 2, 'Le compositeur péruvien s’est inspiré de mélodies andines ; Simon et Garfunkel l’ont repris en 1970.', 11),
    ('d2dbdb22-b383-5894-924f-aa204935ab24'::uuid, '292e54f4-0a41-5bcf-b6db-750aba39bdf1'::uuid, 'Quel glacier bolivien a disparu vers 2009 ?', 'mcq', '["Le Perito Moreno","Le glacier de Chacaltaya","Le glacier de l’Aconcagua","Le glacier du Teide"]'::jsonb, 1, 'Sa disparition symbolise la fonte des glaciers andins, dont dépend l’eau des villes.', 12),
    ('10a8716b-d549-58e5-bb2d-2e9b0f055195'::uuid, 'ed0befd7-51d5-50b8-a54f-0a295041ac1d'::uuid, 'Sur quelle base se forme l’imparfait du subjonctif ?', 'mcq', '["L’infinitif","La 3e personne du pluriel du passé simple","La 1re personne du présent","Le radical du futur"]'::jsonb, 1, 'On retire *-ron* et on ajoute *-ra* ou *-se*.', 1),
    ('21d09c87-5f54-5a43-87d3-dfe7527f8964'::uuid, 'ed0befd7-51d5-50b8-a54f-0a295041ac1d'::uuid, 'Quel est l’imparfait du subjonctif de *tener* (yo) ?', 'mcq', '["teniera","tenga","tuviera","tendría"]'::jsonb, 2, '*Tuvieron* → *tuvie-* → *tuviera*.', 2),
    ('a19bfbd9-c469-5c72-8e34-346bf43462e4'::uuid, 'ed0befd7-51d5-50b8-a54f-0a295041ac1d'::uuid, 'Quelle forme est correcte pour *nosotros* ?', 'mcq', '["habláramos","hablaramos","hablaremos","hablábamos"]'::jsonb, 0, 'La forme *nosotros* porte toujours un accent écrit.', 3),
    ('040c0f1f-8500-5145-a1f9-f61b8a7289a8'::uuid, 'ed0befd7-51d5-50b8-a54f-0a295041ac1d'::uuid, '*Ser* et *ir* ont le même imparfait du subjonctif. Lequel ?', 'mcq', '["siera","iera","era","fuera"]'::jsonb, 3, 'Leur passé simple est commun : *fueron* → *fuera*.', 4),
    ('ead43f82-14f8-5d26-8ac2-7c2f2a10b761'::uuid, 'ed0befd7-51d5-50b8-a54f-0a295041ac1d'::uuid, 'Complète : *Quería que tú ___ conmigo.*', 'mcq', '["vienes","vinieras","vengas","vendrías"]'::jsonb, 1, 'Verbe principal au passé → imparfait du subjonctif.', 5),
    ('3bc0ffea-24be-5d3f-9b14-16ca8696e214'::uuid, 'ed0befd7-51d5-50b8-a54f-0a295041ac1d'::uuid, 'Après *como si*, quel temps emploie-t-on ?', 'mcq', '["Le présent du subjonctif","L’indicatif","L’imparfait du subjonctif","Le conditionnel"]'::jsonb, 2, '*Habla como si fuera el jefe.*', 6),
    ('36127b63-3786-5819-baaf-48455694afde'::uuid, 'ed0befd7-51d5-50b8-a54f-0a295041ac1d'::uuid, 'Quelle est la bonne phrase ?', 'mcq', '["Si tuviera dinero, viajaría","Si tendría dinero, viajaría","Si tenga dinero, viajaría","Si tuviese dinero, viajaré"]'::jsonb, 0, 'Jamais de conditionnel après *si* : imparfait du subjonctif + conditionnel.', 7),
    ('190524e8-538c-52f3-93e5-7d2ba39156d6'::uuid, 'ed0befd7-51d5-50b8-a54f-0a295041ac1d'::uuid, 'Quel est l’imparfait du subjonctif de *decir* (él) ?', 'mcq', '["diciera","diga","decía","dijera"]'::jsonb, 3, '*Dijeron* → *dijera*.', 8),
    ('c92f74d2-7452-5982-b0ea-543ae147920b'::uuid, 'ed0befd7-51d5-50b8-a54f-0a295041ac1d'::uuid, '*Quisiera un café* est une formule de politesse.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Seule la forme en *-ra* s’emploie ainsi.', 9),
    ('e9a03772-c507-5f7d-9aaa-c891a9f6228f'::uuid, 'ed0befd7-51d5-50b8-a54f-0a295041ac1d'::uuid, 'Quel est l’imparfait du subjonctif de *dormir* (ellos) ?', 'mcq', '["dormieran","durmieran","duerman","dormirían"]'::jsonb, 1, 'Passé simple *durmieron* → *durmieran*.', 10),
    ('7c963f9d-a4fd-502f-a49d-d7d8891cb629'::uuid, 'ed0befd7-51d5-50b8-a54f-0a295041ac1d'::uuid, '*Ojalá estuvieras aquí* exprime…', 'mcq', '["Un ordre","Un souhait réalisable demain","Un souhait irréel dans le présent","Un fait passé réel"]'::jsonb, 2, 'Tu n’es pas là : l’imparfait du subjonctif marque l’irréel.', 11),
    ('d70e5ca4-7b70-5ec4-8556-be946bd2a0bf'::uuid, 'ed0befd7-51d5-50b8-a54f-0a295041ac1d'::uuid, 'Les formes en -ra et en -se sont équivalentes dans presque tous les emplois.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Hablara* ou *hablase* : même sens ; *-ra* est plus courant.', 12),
    ('2f9516ed-77cd-57ed-aa68-5b6b3045e54e'::uuid, '4b225404-50dd-5eb7-abb8-c91b74376ad5'::uuid, 'Quel auxiliaire emploie-t-on pour « je suis allé » ?', 'mcq', '["soy ido","estoy ido","he ido","fui ido"]'::jsonb, 2, 'L’espagnol n’emploie que *haber* aux temps composés.', 1),
    ('66ef48f7-3843-58db-9b74-68773a3e7e72'::uuid, '4b225404-50dd-5eb7-abb8-c91b74376ad5'::uuid, 'Comment dit-on « j’avais parlé » ?', 'mcq', '["había hablado","he hablado","habré hablado","hube hablo"]'::jsonb, 0, 'Plus-que-parfait : *haber* à l’imparfait + participe.', 2),
    ('b23b604e-b10d-50e4-aa57-fe6c30f2a3fe'::uuid, '4b225404-50dd-5eb7-abb8-c91b74376ad5'::uuid, 'Quel est le participe passé de *romper* ?', 'mcq', '["rompido","rompto","rompado","roto"]'::jsonb, 3, 'Participe irrégulier : *roto*.', 3),
    ('99314dfa-2537-5400-82e0-1daf215d3c24'::uuid, '4b225404-50dd-5eb7-abb8-c91b74376ad5'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Había se lo dicho","Se lo había dicho","Había dicho se lo","Había díchoselo"]'::jsonb, 1, 'Les pronoms se placent devant *haber*, jamais entre l’auxiliaire et le participe.', 4),
    ('8488e760-f3fd-54d0-8738-95fc7e02a60c'::uuid, '4b225404-50dd-5eb7-abb8-c91b74376ad5'::uuid, '*Las cartas que he ___.* Quel mot complète la phrase ?', 'mcq', '["escritas","escribidas","escrito","escrita"]'::jsonb, 2, 'Le participe est invariable avec *haber*.', 5),
    ('3f73becb-b2c1-5290-9d4a-a17cedf4301a'::uuid, '4b225404-50dd-5eb7-abb8-c91b74376ad5'::uuid, 'Que signifie *No contesta: habrá salido* ?', 'mcq', '["Il a dû sortir","Il sortira","Il serait sorti","Il était sorti"]'::jsonb, 0, 'Le futur antérieur exprime ici la probabilité dans le passé proche.', 6),
    ('f523d954-5990-5a1a-9612-332ccc7f8707'::uuid, '4b225404-50dd-5eb7-abb8-c91b74376ad5'::uuid, 'Quel temps exprime l’irréel du passé dans *___ venido, pero estaba enfermo* ?', 'mcq', '["Había","Habré","Haya","Habría"]'::jsonb, 3, 'Conditionnel passé : j’aurais pu venir, mais je ne suis pas venu.', 7),
    ('58731d9e-d08f-59a1-a075-f3657b4d6b70'::uuid, '4b225404-50dd-5eb7-abb8-c91b74376ad5'::uuid, 'Quel est le participe passé de *volver* ?', 'mcq', '["volvido","vuelto","vuelvido","volto"]'::jsonb, 1, 'Comme *resolver → resuelto*.', 8),
    ('821c82b2-1e9d-5a7a-b222-d4cbf59c5a82'::uuid, '4b225404-50dd-5eb7-abb8-c91b74376ad5'::uuid, 'Le passé antérieur (*hube hablado*) est surtout littéraire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Dans la langue courante, on le remplace par le passé simple.', 9),
    ('cd119ab9-48a9-56d4-a9cf-f52cfb6ace3f'::uuid, '4b225404-50dd-5eb7-abb8-c91b74376ad5'::uuid, 'Comment dit-on « En juin, j’aurai fini le cours » ?', 'mcq', '["En junio habría terminado el curso","En junio había terminado el curso","En junio habré terminado el curso","En junio he terminado el curso"]'::jsonb, 2, 'Futur antérieur : action achevée avant un moment futur.', 10),
    ('46b4a991-5d7a-5a55-ba07-b418ec8d27dd'::uuid, '4b225404-50dd-5eb7-abb8-c91b74376ad5'::uuid, 'Quel est le participe passé de *poner* ?', 'mcq', '["puesto","ponido","ponto","pusto"]'::jsonb, 0, 'Comme ses composés : *propuesto, compuesto*.', 11),
    ('0482f98f-7eb4-5d45-8ba2-70ef1334c731'::uuid, '4b225404-50dd-5eb7-abb8-c91b74376ad5'::uuid, 'Avec *haber*, le participe s’accorde avec le complément placé avant.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Contrairement au français, il reste toujours invariable.', 12),
    ('f47545d8-b1af-562b-b552-ea11b7bcccf2'::uuid, 'c14ed12a-2c0f-579e-b050-05810fe6e99c'::uuid, 'Comment traduire « il est devenu rouge (de honte) » ?', 'mcq', '["Se volvió rojo","Se puso rojo","Se hizo rojo","Llegó a ser rojo"]'::jsonb, 1, 'Changement passager et soudain : *ponerse*.', 1),
    ('779fa914-5f4a-5fdb-9156-326118c0204d'::uuid, 'c14ed12a-2c0f-579e-b050-05810fe6e99c'::uuid, 'Comment traduire « il est devenu fou » ?', 'mcq', '["Se puso loco","Se quedó loco","Se volvió loco","Se convirtió loco"]'::jsonb, 2, 'Changement profond, subi : *volverse*.', 2),
    ('c053abd5-6ef9-50cc-96ab-1c55cf11592f'::uuid, 'c14ed12a-2c0f-579e-b050-05810fe6e99c'::uuid, 'Comment traduire « elle est devenue médecin » (par ses études) ?', 'mcq', '["Se hizo médica","Se puso médica","Se volvió médica","Se quedó médica"]'::jsonb, 0, 'Métier, changement voulu : *hacerse*.', 3),
    ('70628d14-d4e5-5f03-b625-79b68e1a700d'::uuid, 'c14ed12a-2c0f-579e-b050-05810fe6e99c'::uuid, 'Quelle préposition suit *convertirse* ?', 'mcq', '["a","de","por","en"]'::jsonb, 3, '*Convertirse en* + nom : *se convirtió en una estrella*.', 4),
    ('bec296e5-fef4-54ac-a35f-b6ae921440f8'::uuid, 'c14ed12a-2c0f-579e-b050-05810fe6e99c'::uuid, 'Comment traduire « il est devenu aveugle » (après un accident) ?', 'mcq', '["Se puso ciego","Se quedó ciego","Se hizo ciego","Llegó a ser ciego"]'::jsonb, 1, 'État résultant d’un événement : *quedarse*.', 5),
    ('c4c3d8ae-01c7-5bcd-849f-356cb0aa352f'::uuid, 'c14ed12a-2c0f-579e-b050-05810fe6e99c'::uuid, 'Quelle tournure marque l’aboutissement d’un long parcours ?', 'mcq', '["ponerse","quedarse","llegar a ser","volverse"]'::jsonb, 2, '*Llegó a ser presidente* : il a fini par devenir président.', 6),
    ('5aa8d0a5-29ce-5161-8eb7-2c78d863cec8'::uuid, 'c14ed12a-2c0f-579e-b050-05810fe6e99c'::uuid, 'Comment demande-t-on « Qu’est devenu ton frère ? » ?', 'mcq', '["¿Qué ha sido de tu hermano?","¿Qué se ha puesto tu hermano?","¿En qué se ha vuelto tu hermano?","¿Qué ha llegado tu hermano?"]'::jsonb, 0, 'Tournure figée : *¿Qué ha sido de…?*', 7),
    ('824c110d-9b9c-5737-9fe6-9cca7e5b202f'::uuid, 'c14ed12a-2c0f-579e-b050-05810fe6e99c'::uuid, '*Se quedó sin trabajo* signifie…', 'mcq', '["Il a trouvé du travail","Il est resté au travail","Il est devenu travailleur","Il s’est retrouvé sans travail"]'::jsonb, 3, '*Quedarse sin* = se retrouver privé de.', 8),
    ('77fbdd6c-3351-5b4c-a83b-b0e35cb14e50'::uuid, 'c14ed12a-2c0f-579e-b050-05810fe6e99c'::uuid, '*Me pongo nervioso antes de los exámenes* décrit un changement passager.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La nervosité passe : *ponerse*.', 9),
    ('331f438c-6372-500b-a559-b8adca376379'::uuid, 'c14ed12a-2c0f-579e-b050-05810fe6e99c'::uuid, 'Quel verbe signifie « vieillir » ?', 'mcq', '["enriquecer","envejecer","enfadarse","adelgazar"]'::jsonb, 1, '*Viejo → envejecer*. *Enriquecerse* = s’enrichir.', 10),
    ('7c663e5f-768f-513f-b883-4019ed8e8680'::uuid, 'c14ed12a-2c0f-579e-b050-05810fe6e99c'::uuid, '*Acabó siendo mi mejor amigo* signifie…', 'mcq', '["Il a cessé d’être mon meilleur ami","Il vient de devenir mon meilleur ami","Il a fini par devenir mon meilleur ami","Il était mon meilleur ami"]'::jsonb, 2, '*Acabar* + gérondif = finir par.', 11),
    ('014be041-e218-53e4-89d8-77b2f8de276a'::uuid, 'c14ed12a-2c0f-579e-b050-05810fe6e99c'::uuid, '*Se hizo rico* et *Se puso rico* ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Se hizo rico* = il s’est enrichi ; *ponerse* ne convient pas à un changement durable.', 12),
    ('a4595421-0a11-5ba9-a29d-562b9336a0f1'::uuid, '3ec2218b-a910-5d6c-bc85-dc5042c1e547'::uuid, 'Comment traduire « Ici, on vit bien » (sens général) ?', 'mcq', '["Aquí vive bien","Aquí se vive bien","Aquí uno vive bienes","Aquí se viven bien"]'::jsonb, 1, 'Sens impersonnel : *se* + 3e personne du singulier.', 1),
    ('87ca5352-785d-59d6-b878-6a6610a3614e'::uuid, '3ec2218b-a910-5d6c-bc85-dc5042c1e547'::uuid, 'Comment traduire « On vend des appartements » ?', 'mcq', '["Se vende pisos","Venden a pisos","Se venden pisos","Se vendemos pisos"]'::jsonb, 2, 'Le verbe s’accorde avec la chose au pluriel.', 2),
    ('0824580a-540f-5308-acab-9ea85306d910'::uuid, '3ec2218b-a910-5d6c-bc85-dc5042c1e547'::uuid, 'Comment traduire « On frappe à la porte » ?', 'mcq', '["Llaman a la puerta","Se llama a la puerta los","Uno llama a la puerta","Llamamos a la puerta"]'::jsonb, 0, 'Des gens autres que moi : 3e personne du pluriel.', 3),
    ('ad3ed2f8-913d-5bc9-a975-d0c0e4f31d96'::uuid, '3ec2218b-a910-5d6c-bc85-dc5042c1e547'::uuid, 'Pourquoi dit-on *Uno se acostumbra a todo* et non *Se se acostumbra* ?', 'mcq', '["Parce que *acostumbrar* est irrégulier","Parce que *uno* est plus poli","Par simple habitude régionale","Parce qu’on ne peut pas mettre deux *se* de suite"]'::jsonb, 3, 'Avec un verbe déjà pronominal, *uno* ou *nosotros* remplacent le *se* impersonnel.', 4),
    ('19712750-7720-505a-bc3c-e4863d63e5d7'::uuid, '3ec2218b-a910-5d6c-bc85-dc5042c1e547'::uuid, '*Se detuvo a los ladrones* : pourquoi le verbe est-il au singulier ?', 'mcq', '["C’est une faute","Parce que le complément est une personne introduite par *a*","Parce que *ladrones* est singulier","Parce que le verbe est au passé"]'::jsonb, 1, 'Avec *a* + personne, le verbe reste au singulier.', 5),
    ('e6c66021-1bdf-54a8-9d33-6e826ba8c1a0'::uuid, '3ec2218b-a910-5d6c-bc85-dc5042c1e547'::uuid, 'Comment forme-t-on la voix passive avec *ser* ?', 'mcq', '["ser + infinitif + de","ser + gérondif + por","ser + participe accordé + por","estar + participe invariable + para"]'::jsonb, 2, '*La ley fue aprobada por el Parlamento.*', 6),
    ('6a1d653a-b052-5c8b-acc0-54614a738981'::uuid, '3ec2218b-a910-5d6c-bc85-dc5042c1e547'::uuid, '*La puerta está abierta* exprime…', 'mcq', '["Le résultat, l’état de la porte","L’action d’ouvrir","Un ordre","Un souhait"]'::jsonb, 0, '*Estar* + participe = état résultant ; *ser* + participe = action subie.', 7),
    ('f2c7aa27-0ad8-5b68-b2fa-0a8ad175765c'::uuid, '3ec2218b-a910-5d6c-bc85-dc5042c1e547'::uuid, '*En casa ___ a las dos* (on déjeune, ma famille et moi).', 'mcq', '["se comen","comen","uno comen","comemos"]'::jsonb, 3, 'Groupe qui m’inclut : *nosotros*.', 8),
    ('679eb143-b278-5f3e-9fdd-4e0e3138bb9c'::uuid, '3ec2218b-a910-5d6c-bc85-dc5042c1e547'::uuid, 'À l’oral, l’espagnol préfère souvent le *se* passif à la voix passive avec *ser*.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Se aprobó la ley* est plus naturel que *La ley fue aprobada*.', 9),
    ('e9406a4e-db5d-58a8-96ca-33352935e3b9'::uuid, '3ec2218b-a910-5d6c-bc85-dc5042c1e547'::uuid, 'Comment traduire « On dit qu’il va pleuvoir » ?', 'mcq', '["Se dicen que va a llover","Dicen que va a llover","Uno dicen que va a llover","Es dicho que va a llover"]'::jsonb, 1, '*Dicen que* = on dit que (les gens).', 10),
    ('fda7125e-0fa8-5258-875a-5a69af5afc41'::uuid, '3ec2218b-a910-5d6c-bc85-dc5042c1e547'::uuid, '*Las pirámides ___ construidas por los mayas.* Quel mot complète la phrase ?', 'mcq', '["estaban","han","fueron","se"]'::jsonb, 2, 'Action subie, avec agent : *ser* + participe.', 11),
    ('9ddb6b1b-d3b3-56ca-8e46-101f06fa01fb'::uuid, '3ec2218b-a910-5d6c-bc85-dc5042c1e547'::uuid, '*Se habla español* peut se traduire par « on parle espagnol ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le *se* impersonnel ou passif, très fréquent sur les panneaux.', 12),
    ('8f6e520a-1a9a-5458-8416-7a9447a95742'::uuid, '47471267-3299-5ecd-9714-40be46cdfe1b'::uuid, 'Complète : *Cuando ___ mayor, lo entenderás.*', 'mcq', '["serás","eres","seas","serías"]'::jsonb, 2, 'Action à venir après *cuando* : subjonctif présent.', 1),
    ('0e15524d-d5e2-511a-8d41-10db25139be7'::uuid, '47471267-3299-5ecd-9714-40be46cdfe1b'::uuid, '*Cuando llego a casa, ceno* : pourquoi l’indicatif ?', 'mcq', '["C’est une action habituelle","C’est une faute","Parce que *llegar* est irrégulier","C’est une action future"]'::jsonb, 0, 'Action réelle et habituelle : indicatif.', 2),
    ('728a0eea-8f2e-5893-a0aa-4f6e2b310343'::uuid, '47471267-3299-5ecd-9714-40be46cdfe1b'::uuid, 'Quelle conjonction est TOUJOURS suivie du subjonctif ?', 'mcq', '["cuando","mientras","en cuanto","antes de que"]'::jsonb, 3, 'Ce qui est « avant » n’a pas encore eu lieu.', 3),
    ('0e837c15-3cff-5bce-b337-5466464bbdac'::uuid, '47471267-3299-5ecd-9714-40be46cdfe1b'::uuid, 'Que signifie *Mientras no me pidas perdón, no te hablo* ?', 'mcq', '["Pendant que tu t’excuses, je ne te parle pas","Tant que tu ne me demandes pas pardon, je ne te parle pas","Quand tu m’as demandé pardon, je ne t’ai pas parlé","Avant que tu t’excuses, je te parle"]'::jsonb, 1, '*Mientras* + subjonctif = tant que.', 4),
    ('7053d5ec-a818-5ce2-88b0-6f4e69409c01'::uuid, '47471267-3299-5ecd-9714-40be46cdfe1b'::uuid, 'Comment traduire « En sortant, j’ai vu Luis » ?', 'mcq', '["Saliendo de, vi a Luis","Cuando saldré, vi a Luis","Al salir, vi a Luis","En salir, vi a Luis"]'::jsonb, 2, '*Al* + infinitif = au moment où, en.', 5),
    ('0f22c9d4-6a23-5049-b360-6fcfeaac9f02'::uuid, '47471267-3299-5ecd-9714-40be46cdfe1b'::uuid, 'Que signifie *nada más llegar* ?', 'mcq', '["Dès son arrivée","Sans arriver","Rien n’arrive","Après être arrivé longtemps"]'::jsonb, 0, '*Nada más* + infinitif = à peine, dès que.', 6),
    ('527af232-c635-5238-93c5-6fa1ff798ca0'::uuid, '47471267-3299-5ecd-9714-40be46cdfe1b'::uuid, '*Me dijo que me llamaría cuando ___.* Quel mot complète la phrase ?', 'mcq', '["llegue","llegará","llegaría","llegara"]'::jsonb, 3, 'Concordance : futur vu depuis le passé → imparfait du subjonctif.', 7),
    ('d30f0aee-b372-51a5-875d-3ff922df2690'::uuid, '47471267-3299-5ecd-9714-40be46cdfe1b'::uuid, 'Comment dit-on « dès que » ?', 'mcq', '["hasta que","en cuanto","mientras","antes de"]'::jsonb, 1, 'On dit aussi *tan pronto como*.', 8),
    ('717fa3ad-83d5-505f-abc7-c852653c15c5'::uuid, '47471267-3299-5ecd-9714-40be46cdfe1b'::uuid, 'On peut dire *Cuando llegarás, llámame*.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Jamais de futur après *cuando* : *Cuando llegues, llámame*.', 9),
    ('8d0feecf-521a-5e6c-81ef-6c892cd15c49'::uuid, '47471267-3299-5ecd-9714-40be46cdfe1b'::uuid, '*Lávate las manos antes de comer* : pourquoi l’infinitif ?', 'mcq', '["Parce que le sujet est le même","Parce que c’est un ordre","Parce que l’action est passée","Parce que *antes de* refuse toujours le subjonctif"]'::jsonb, 0, 'Même sujet → *antes de* + infinitif ; sujets différents → *antes de que* + subjonctif.', 10),
    ('9f1c40c8-1f09-5edd-a833-18fcea6c6a7d'::uuid, '47471267-3299-5ecd-9714-40be46cdfe1b'::uuid, '*Mientras cocino, escucho música* : quel est le sens de *mientras* ?', 'mcq', '["Tant que","Avant que","Pendant que","Dès que"]'::jsonb, 2, 'Avec l’indicatif, *mientras* marque la simultanéité.', 11),
    ('825ba77c-35bc-58d2-aff6-628d9c12c79b'::uuid, '47471267-3299-5ecd-9714-40be46cdfe1b'::uuid, 'Complète : *Espera aquí hasta que yo ___.*', 'mcq', '["vuelva","vuelvo","volveré","volvería"]'::jsonb, 0, 'Action à venir après *hasta que* : subjonctif.', 12),
    ('56c594c3-e345-5b5e-8c09-3f49d66cde80'::uuid, 'aed67412-8935-5a35-924e-717a826dc136'::uuid, 'Quel connecteur de cause se place en tête de phrase ?', 'mcq', '["porque","como","así que","por eso"]'::jsonb, 1, '*Como llovía, no salí.* *Porque* ne se place pas en tête.', 1),
    ('cb4c18db-11e7-59a1-8b7e-cc01bd15fa6d'::uuid, 'aed67412-8935-5a35-924e-717a826dc136'::uuid, '*Porque llovía, no salí* est une phrase correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'En tête, il faut *como* : *Como llovía, no salí*.', 2),
    ('e2956c0c-bffa-5c84-befe-1470cfaa34c6'::uuid, 'aed67412-8935-5a35-924e-717a826dc136'::uuid, 'Complète : *No lo digo porque ___ mi amigo, sino porque es verdad.*', 'mcq', '["eres","serás","seas","eras"]'::jsonb, 2, '*No porque* nie la cause : subjonctif.', 3),
    ('acf26d7f-ed35-5d98-aaba-f016ea854f3e'::uuid, 'aed67412-8935-5a35-924e-717a826dc136'::uuid, 'Quel connecteur exprime une cause heureuse ?', 'mcq', '["gracias a","debido a","a causa de","por culpa de"]'::jsonb, 0, '*Aprobé gracias a tu ayuda.*', 4),
    ('a90b0095-0347-5dd1-bf86-f31ca10f63a3'::uuid, 'aed67412-8935-5a35-924e-717a826dc136'::uuid, 'Que signifie *así que* ?', 'mcq', '["Ainsi que","Comme si","Aussi… que","Donc"]'::jsonb, 3, '*Estaba cansado, así que me acosté.*', 5),
    ('a4c518de-e96f-5d58-8418-f3b9ab1a1926'::uuid, 'aed67412-8935-5a35-924e-717a826dc136'::uuid, '*Habla alto de modo que todos te oigan* exprime…', 'mcq', '["Une conséquence réalisée","Un but","Une cause","Une concession"]'::jsonb, 1, '*De modo que* + subjonctif = but ; + indicatif = conséquence.', 6),
    ('419b9278-0af3-5171-8a5c-b58fc4488194'::uuid, 'aed67412-8935-5a35-924e-717a826dc136'::uuid, 'Complète : *Había ___ gente que no pudimos entrar.*', 'mcq', '["tan","tanto","tanta","tantas"]'::jsonb, 2, '*Tanto* s’accorde avec le nom : *tanta gente*.', 7),
    ('4f83dba6-082d-5e69-aa7c-59ed36593133'::uuid, 'aed67412-8935-5a35-924e-717a826dc136'::uuid, 'Complète : *Estaba ___ cansado que se durmió.*', 'mcq', '["tan","tanto","tal","muy"]'::jsonb, 0, 'Devant un adjectif : *tan… que*.', 8),
    ('72095231-346b-593a-b624-da8c14d1cdae'::uuid, 'aed67412-8935-5a35-924e-717a826dc136'::uuid, 'Quel connecteur appartient au registre familier ?', 'mcq', '["por consiguiente","puesto que","debido a","conque"]'::jsonb, 3, '*Ya es tarde, conque vámonos.*', 9),
    ('027551ba-8360-53cf-bdad-2f229210f1aa'::uuid, 'aed67412-8935-5a35-924e-717a826dc136'::uuid, '*Lo castigaron por mentir* : quelle valeur a *por* ?', 'mcq', '["Le but","La cause","Le moyen","Le lieu"]'::jsonb, 1, '*Por* + infinitif donne la cause d’une sanction.', 10),
    ('9bff9b0b-9603-530e-a808-cc1680696541'::uuid, 'aed67412-8935-5a35-924e-717a826dc136'::uuid, 'Quel connecteur convient à une argumentation écrite pour « par conséquent » ?', 'mcq', '["conque","así que","por lo tanto","porque"]'::jsonb, 2, 'On dit aussi *por consiguiente*.', 11),
    ('9a09dd86-4f24-5119-9881-b4e40767605c'::uuid, 'aed67412-8935-5a35-924e-717a826dc136'::uuid, '*Ya que estás aquí, ayúdame* : *ya que* exprime une cause connue de tous.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme « puisque » : la cause est évidente pour les deux interlocuteurs.', 12),
    ('3e49d403-24fd-5b6e-888f-4ffb09036170'::uuid, 'd5ca4bcc-6031-5770-a414-701b9e21c98a'::uuid, 'Qui a peint *Las Meninas* (1656), où il s’est représenté pinceau à la main ?', 'mcq', '["Goya","Velázquez","El Greco","Murillo"]'::jsonb, 1, 'Diego Velázquez, peintre de la cour de Philippe IV, s’y montre à côté de l’infante Marguerite ; le tableau est au Prado.', 1),
    ('7f7c6d09-7098-5dda-ae79-2946f8ce626a'::uuid, 'd5ca4bcc-6031-5770-a414-701b9e21c98a'::uuid, 'Que montre *Las dos Fridas* (1939) de Frida Kahlo ?', 'mcq', '["Deux sœurs jumelles","La peintre et sa mère","Deux Frida, l’une en robe européenne, l’autre en costume mexicain","Frida et Diego Rivera"]'::jsonb, 2, 'Le tableau met en scène une identité double, européenne et mexicaine, reliée par une même artère.', 2),
    ('4d119d77-5a54-55e5-9a82-9f927de74ebd'::uuid, 'd5ca4bcc-6031-5770-a414-701b9e21c98a'::uuid, 'Quelles langues sont co-officielles dans leurs communautés en Espagne, à côté du castillan ?', 'mcq', '["Catalan, basque, galicien","Portugais, catalan, occitan","Basque, arabe, galicien","Andalou, catalan, basque"]'::jsonb, 0, 'La Constitution de 1978 reconnaît ces langues dans leurs communautés autonomes ; l’andalou est un accent du castillan, pas une langue.', 3),
    ('19e90bf0-8d35-54e2-88a9-4138dbb6828e'::uuid, 'd5ca4bcc-6031-5770-a414-701b9e21c98a'::uuid, 'Dans quel pays le guarani est-il langue co-officielle avec l’espagnol ?', 'mcq', '["Au Pérou","Au Mexique","En Bolivie seulement","Au Paraguay"]'::jsonb, 3, 'Le Paraguay a fait du guarani une langue officielle en 1992 ; la majorité des Paraguayens le parlent.', 4),
    ('101bb43d-d958-56cd-81f8-00171b265090'::uuid, 'd5ca4bcc-6031-5770-a414-701b9e21c98a'::uuid, 'Que signifie *el autorretrato* ?', 'mcq', '["Le portrait de groupe","L’autoportrait","La caricature","La photo d’identité"]'::jsonb, 1, '*Auto-* marque ce qu’on fait sur soi-même, comme en français.', 5),
    ('d873b3d2-f812-5492-a547-7b153e720579'::uuid, 'd5ca4bcc-6031-5770-a414-701b9e21c98a'::uuid, 'Que désigne le « spanglish » ?', 'mcq', '["L’espagnol parlé en Angleterre","Un dialecte des Canaries","Le mélange d’anglais et d’espagnol des Latinos des États-Unis","L’anglais appris en Espagne"]'::jsonb, 2, 'Des mots comme *parquear* (se garer) ou *lonche* (déjeuner) viennent de l’anglais adapté à l’espagnol.', 6),
    ('8d7e9d76-c40d-5fb8-b77c-4124966651d8'::uuid, 'd5ca4bcc-6031-5770-a414-701b9e21c98a'::uuid, 'Comment dire « le sentiment d’appartenance » ?', 'mcq', '["el sentimiento de pertenencia","el sentido de la partencia","la pertenencia sentida","el sentir de apartenencia"]'::jsonb, 0, '*Pertenecer a* signifie « appartenir à », d’où *la pertenencia*.', 7),
    ('ac863fb1-3103-5587-90d8-abff0e4112cb'::uuid, 'd5ca4bcc-6031-5770-a414-701b9e21c98a'::uuid, 'Quelle expression sert à décrire le premier plan d’une image ?', 'mcq', '["Al fondo aparece…","En primer plano se ve…","A mi parecer…","Sin embargo…"]'::jsonb, 1, '*En primer plano* = au premier plan ; *al fondo* = à l’arrière-plan.', 8),
    ('e0d01ecf-fe32-5e52-a148-d521cae56f86'::uuid, 'd5ca4bcc-6031-5770-a414-701b9e21c98a'::uuid, 'Goya s’est peint vieilli et malade, sans chercher à se flatter.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ses autoportraits tardifs font du portrait un aveu plutôt qu’une vitrine.', 9),
    ('5e6ab939-b2b1-5d7e-887c-7b7e9869f726'::uuid, 'd5ca4bcc-6031-5770-a414-701b9e21c98a'::uuid, 'Que signifie *las raíces* dans *Tengo raíces mexicanas* ?', 'mcq', '["Les rêves","Les racines","Les voyages","Les parents"]'::jsonb, 1, '*La raíz, las raíces* : les racines, au propre comme au figuré (les origines).', 10),
    ('13f0c1df-4dab-53de-b3d2-f5998dd1853a'::uuid, 'd5ca4bcc-6031-5770-a414-701b9e21c98a'::uuid, 'Quel connecteur permet de NUANCER une idée à l’oral ?', 'mcq', '["En primer plano","Creo que","Sin embargo","Se ve"]'::jsonb, 2, '*Sin embargo* = cependant : il introduit une réserve.', 11),
    ('793fcbcd-9069-5d2e-b593-7caf172619af'::uuid, 'd5ca4bcc-6031-5770-a414-701b9e21c98a'::uuid, 'Selon l’axe, un autoportrait ne renseigne que sur le visage du peintre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il renseigne aussi sur son époque et sur la place qu’il veut y tenir : c’est tout l’enjeu de l’objet d’étude.', 12),
    ('6407530c-8e59-535c-895c-99b67638a604'::uuid, '1a4f3727-0e31-57e8-adbc-e87f5679e506'::uuid, 'Que cherchent les *Abuelas de Plaza de Mayo* ?', 'mcq', '["Les tombes de leurs maris","Leurs petits-enfants volés par la dictature","Un emploi pour leurs enfants","La reconnaissance de leur langue"]'::jsonb, 1, 'Fondées en 1977 en Argentine, elles ont aidé plus de 130 petits-enfants à retrouver leur identité.', 1),
    ('d328c82f-68d6-5c29-b1fa-bfa85238141c'::uuid, '1a4f3727-0e31-57e8-adbc-e87f5679e506'::uuid, 'Quelles années la dictature argentine couvre-t-elle ?', 'mcq', '["1939-1975","1973-1990","1976-1983","1910-1920"]'::jsonb, 2, 'La junte militaire gouverne l’Argentine de 1976 à 1983 ; 1939-1975 est la dictature de Franco.', 2),
    ('326b3e84-404d-5316-9cba-03bd1f7042ca'::uuid, '1a4f3727-0e31-57e8-adbc-e87f5679e506'::uuid, 'Quel film de Pedro Almodóvar réunit trois générations de femmes autour de secrets de famille ?', 'mcq', '["Volver","Alcarràs","Coco","Mafalda"]'::jsonb, 0, '*Volver* (2006) se passe entre Madrid et la Manche.', 3),
    ('2ba5883e-6dfb-52f2-b6e9-01712d5f7629'::uuid, '1a4f3727-0e31-57e8-adbc-e87f5679e506'::uuid, 'Que signifie *la brecha generacional* ?', 'mcq', '["L’héritage familial","La retraite","La crise du logement","Le fossé des générations"]'::jsonb, 3, '*La brecha* : la brèche, l’écart.', 4),
    ('0a5dd8d3-456d-5305-9815-b99c87987aa8'::uuid, '1a4f3727-0e31-57e8-adbc-e87f5679e506'::uuid, 'Quel film a remporté l’Ours d’or en 2022 avec une famille de cultivateurs catalans ?', 'mcq', '["Volver","Alcarràs","Roma","Coco"]'::jsonb, 1, 'Carla Simón y filme trois générations face à la fin de leur verger.', 5),
    ('dc43b434-40b1-5a90-a78d-1290a9624ad3'::uuid, '1a4f3727-0e31-57e8-adbc-e87f5679e506'::uuid, 'Comment dit-on « les petits-enfants » ?', 'mcq', '["los sobrinos","los primos","los nietos","los hijos"]'::jsonb, 2, '*Los nietos* ; *los sobrinos* = neveux, *los primos* = cousins.', 6),
    ('7d2da032-f83d-543c-8a99-cec4c52bb715'::uuid, '1a4f3727-0e31-57e8-adbc-e87f5679e506'::uuid, 'Où se passe le film *Coco* (Pixar, 2017) ?', 'mcq', '["Au Mexique","En Espagne","En Argentine","Au Pérou"]'::jsonb, 0, 'Il se déroule pendant le jour des morts mexicain, fête de la mémoire des ancêtres.', 7),
    ('e9321a53-63cd-5639-ab96-9797fab20c38'::uuid, '1a4f3727-0e31-57e8-adbc-e87f5679e506'::uuid, 'Quelle expression introduit une concession ?', 'mcq', '["Esto se debe a que…","Es verdad que…, pero…","En resumen…","Mientras que…"]'::jsonb, 1, '*Es verdad que…, pero…* reconnaît un point avant de le dépasser.', 8),
    ('6b697ceb-d5f4-506c-99ac-2efceb74a28d'::uuid, '1a4f3727-0e31-57e8-adbc-e87f5679e506'::uuid, '*Mafalda* est une bande dessinée argentine de Quino.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Publiée de 1964 à 1973, elle montre une petite fille qui interroge le monde des adultes.', 9),
    ('7b51b0de-4993-578d-a1a1-19be7fbd46b4'::uuid, '1a4f3727-0e31-57e8-adbc-e87f5679e506'::uuid, 'Que signifie *llevarse bien con alguien* ?', 'mcq', '["Emmener quelqu’un","Bien s’entendre avec quelqu’un","Porter quelqu’un","Se séparer de quelqu’un"]'::jsonb, 1, 'Expression très utile pour parler des relations familiales.', 10),
    ('329d43c5-e609-5750-a7a8-f0bfdc561a6c'::uuid, '1a4f3727-0e31-57e8-adbc-e87f5679e506'::uuid, 'Quand la dictature de Franco a-t-elle pris fin ?', 'mcq', '["En 1939","En 1982","En 1936","En 1975"]'::jsonb, 3, 'Franco meurt en novembre 1975 ; commence alors la Transition démocratique.', 11),
    ('59da31eb-fe37-5031-ab93-327d1526db4e'::uuid, '1a4f3727-0e31-57e8-adbc-e87f5679e506'::uuid, 'Que veut dire *heredar* ?', 'mcq', '["Transmettre","Se souvenir","Hériter","Élever"]'::jsonb, 2, '*Heredar* = hériter, *la herencia* = l’héritage ; *transmitir* = transmettre.', 12),
    ('a946abc6-758c-5dee-ab0a-3f1062ef7964'::uuid, '2cf06184-4aa2-5f8c-b1a5-d2173d48b12a'::uuid, 'Quand se célèbre le Día de Muertos au Mexique ?', 'mcq', '["Le 12 octobre","Les 1er et 2 novembre","Le 24 juin","Le 19 mars"]'::jsonb, 1, 'Les familles dressent des *ofrendas* pour accueillir leurs défunts.', 1),
    ('c913de60-356c-5f9c-841d-43882426a9b2'::uuid, '2cf06184-4aa2-5f8c-b1a5-d2173d48b12a'::uuid, 'Dans quelle ville ont lieu les Fallas ?', 'mcq', '["Séville","Pampelune","Valence","Cuzco"]'::jsonb, 2, 'Les figures géantes y brûlent le 19 mars ; la fête est au patrimoine de l’UNESCO depuis 2016.', 2),
    ('316fd5f7-954c-5951-b845-5f7b41731570'::uuid, '2cf06184-4aa2-5f8c-b1a5-d2173d48b12a'::uuid, 'Que fête-t-on lors de l’Inti Raymi à Cuzco ?', 'mcq', '["Le Soleil, dans la tradition inca","L’indépendance du Pérou","La Vierge Marie","La récolte du café"]'::jsonb, 0, '*Inti* signifie « soleil » en quechua ; la fête a lieu le 24 juin.', 3),
    ('1f9ec766-04d3-51ad-a031-0cbc9f10576d'::uuid, '2cf06184-4aa2-5f8c-b1a5-d2173d48b12a'::uuid, 'Quels souverains ont bâti l’Alhambra de Grenade ?', 'mcq', '["Les Rois catholiques","Les Incas","Les Wisigoths","Les Nasrides"]'::jsonb, 3, 'Derniers rois musulmans d’al-Andalus, les Nasrides perdent Grenade en 1492.', 4),
    ('f514f573-f005-5f4c-af27-937596a12496'::uuid, '2cf06184-4aa2-5f8c-b1a5-d2173d48b12a'::uuid, 'Sous quel nom le Venezuela commémore-t-il le 12 octobre depuis 2002 ?', 'mcq', '["Fiesta Nacional","Día de la Resistencia Indígena","Día de la Hispanidad","Día de Muertos"]'::jsonb, 1, 'Le changement de nom retourne le récit : on célèbre la résistance, pas l’arrivée de Colomb.', 5),
    ('08a471d1-67e8-59cc-98dc-5c1f03c05076'::uuid, '2cf06184-4aa2-5f8c-b1a5-d2173d48b12a'::uuid, 'Que sont les *encierros* de San Fermín ?', 'mcq', '["Des processions religieuses","Des feux d’artifice","Des courses devant les taureaux dans les rues","Des concours de danse"]'::jsonb, 2, 'Ils ont lieu à Pampelune du 7 au 14 juillet, pendant les fêtes qui s’ouvrent le 6.', 6),
    ('a2625077-bb99-542e-a622-07979354d380'::uuid, '2cf06184-4aa2-5f8c-b1a5-d2173d48b12a'::uuid, 'Que signifie *la huella* ?', 'mcq', '["La trace","La fête","La guerre","La maison"]'::jsonb, 0, '*Seguir las huellas del pasado* = suivre les traces du passé.', 7),
    ('2316a6a7-9454-5cf4-b785-a3b230c6783e'::uuid, '2cf06184-4aa2-5f8c-b1a5-d2173d48b12a'::uuid, 'Chichén Itzá est une cité…', 'mcq', '["Inca","Aztèque de Tenochtitlan","Romaine","Maya"]'::jsonb, 3, 'Elle se trouve dans la péninsule du Yucatán, au Mexique.', 8),
    ('14b1758d-5686-5668-8bfe-9882026cbda2'::uuid, '2cf06184-4aa2-5f8c-b1a5-d2173d48b12a'::uuid, 'Le 12 octobre est la fête nationale de l’Espagne.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La *Fiesta Nacional* commémore l’arrivée de Colomb en Amérique en 1492.', 9),
    ('ca8f29b5-e015-5384-9fb5-984f69bacde5'::uuid, '2cf06184-4aa2-5f8c-b1a5-d2173d48b12a'::uuid, 'Quelle tournure oppose deux points de vue ?', 'mcq', '["Hoy en día…","Para unos…, para otros…","Se celebra en…","Me parece importante"]'::jsonb, 1, 'Elle est précieuse pour présenter un débat comme celui du 12 octobre.', 10),
    ('5ceb887f-74f9-510c-940b-eeff252e373e'::uuid, '2cf06184-4aa2-5f8c-b1a5-d2173d48b12a'::uuid, 'Comment dit-on « les peuples autochtones » ?', 'mcq', '["los pueblos originarios","los pueblos antiguos","los primeros vecinos","los indianos"]'::jsonb, 0, 'On dit aussi *pueblos indígenas* ; *indiano* désigne un Espagnol revenu enrichi d’Amérique.', 11),
    ('61b626c4-de68-5be6-82e9-2e73b97c29ac'::uuid, '2cf06184-4aa2-5f8c-b1a5-d2173d48b12a'::uuid, 'Après *Me parece importante que…*, quel mode faut-il ?', 'mcq', '["L’indicatif","L’infinitif","Le subjonctif","Le gérondif"]'::jsonb, 2, 'Un jugement de valeur suivi de *que* entraîne le subjonctif : *Me parece importante que se conserve*.', 12),
    ('04dabf4f-ee46-5b98-8a42-ec0c738f456a'::uuid, '216bcc1d-b1f7-538b-a40f-69bd86858132'::uuid, 'Que sont les *superilles* de Barcelone ?', 'mcq', '["Des îlots de rues rendus aux piétons et à la verdure","Des îles artificielles","Des immeubles de luxe","Des lignes de métro"]'::jsonb, 0, 'Lancées à Poblenou en 2016, elles réduisent la place de la voiture.', 1),
    ('b2a14f5e-2795-5da1-965c-11c3a577452e'::uuid, '216bcc1d-b1f7-538b-a40f-69bd86858132'::uuid, 'Que relie le Metrocable de Medellín, ouvert en 2004 ?', 'mcq', '["L’aéroport au centre","Deux stades","Les quartiers des collines au métro","Deux pays voisins"]'::jsonb, 2, 'Ce téléphérique a désenclavé des quartiers pauvres : un transport devenu outil d’intégration.', 2),
    ('7f628f1b-e5c1-5853-9207-ee892c949885'::uuid, '216bcc1d-b1f7-538b-a40f-69bd86858132'::uuid, 'Que désigne le « 15-M » ?', 'mcq', '["Une loi sur le climat","Le mouvement des Indignés né le 15 mai 2011 à Madrid","Une fête valencienne","Un plan d’urbanisme"]'::jsonb, 1, 'Les jeunes ont occupé la Puerta del Sol contre le chômage et la crise.', 3),
    ('b21afda8-258c-5dbf-86dc-c6959c69ec76'::uuid, '216bcc1d-b1f7-538b-a40f-69bd86858132'::uuid, 'Contre quoi protestent les manifestants de *Canarias tiene un límite* (avril 2024) ?', 'mcq', '["Contre la sécheresse","Contre l’indépendance","Contre la fermeture des écoles","Contre le tourisme de masse et la hausse des loyers"]'::jsonb, 3, 'Ils dénoncent un modèle où les habitants ne peuvent plus se loger sur leurs îles.', 4),
    ('ec7eb557-8cb9-536a-93d3-b9ce58885bbb'::uuid, '216bcc1d-b1f7-538b-a40f-69bd86858132'::uuid, 'Que signifie *sostenible* ?', 'mcq', '["Solide","Durable","Soutenu","Lourd"]'::jsonb, 1, '*El desarrollo sostenible* = le développement durable.', 5),
    ('9ae1b3c3-d249-50b9-b241-6bdec642ef59'::uuid, '216bcc1d-b1f7-538b-a40f-69bd86858132'::uuid, 'Comment dit-on « le loyer » ?', 'mcq', '["el alquiler","el piso","el precio","el alojamiento"]'::jsonb, 0, '*Alquilar* = louer ; *el alquiler* = le loyer ou la location.', 6),
    ('6d5cbdd7-01c4-5c24-a2a5-429bf507523c'::uuid, '216bcc1d-b1f7-538b-a40f-69bd86858132'::uuid, 'Quelle formule sert à PROPOSER une solution ?', 'mcq', '["El problema es que…","La ventaja es que…","Habría que…","Ojalá…"]'::jsonb, 2, '*Habría que* + infinitif = il faudrait.', 7),
    ('e44b30cb-49fc-52d3-a422-698a8ef991ae'::uuid, '216bcc1d-b1f7-538b-a40f-69bd86858132'::uuid, 'Après *Ojalá*, on emploie…', 'mcq', '["L’indicatif présent","Le futur","L’infinitif","Le subjonctif"]'::jsonb, 3, '*Ojalá* exprime un souhait : *Ojalá llueva*.', 8),
    ('45837b5c-87e3-5648-a707-5ee816b588e2'::uuid, '216bcc1d-b1f7-538b-a40f-69bd86858132'::uuid, 'Madrid Central est une zone à faibles émissions créée en 2018.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle limite l’accès des véhicules les plus polluants au centre de Madrid.', 9),
    ('e28aba20-407d-5ad0-86f7-4399fb9dbe67'::uuid, '216bcc1d-b1f7-538b-a40f-69bd86858132'::uuid, 'Pourquoi limite-t-on le nombre de visiteurs quotidiens au Machu Picchu ?', 'mcq', '["Pour augmenter les prix","Pour protéger le site","Pour des raisons religieuses","À cause de la guerre"]'::jsonb, 1, 'Trop de visiteurs abîment la cité inca ; les quotas protègent le patrimoine.', 10),
    ('26693c29-a597-58c8-b4e0-423beefc58fe'::uuid, '216bcc1d-b1f7-538b-a40f-69bd86858132'::uuid, 'Que signifie *comprometerse* ?', 'mcq', '["Promettre en mariage","Compromettre","S’engager","Comprendre"]'::jsonb, 2, 'Faux ami partiel : *un joven comprometido* est un jeune engagé.', 11),
    ('117b96ac-2fc0-52ac-9c72-8a2111006021'::uuid, '216bcc1d-b1f7-538b-a40f-69bd86858132'::uuid, 'L’Espagne reçoit chaque année moins de 20 millions de touristes étrangers.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle en reçoit plus de 80 millions : c’est l’une des premières destinations du monde.', 12),
    ('4e8e3dbc-ade9-58f0-a27e-4cc39ed34faa'::uuid, 'bdabe43a-4f0a-50f6-830f-1f898e6a6ec7'::uuid, 'Combien de toiles Picasso a-t-il peintes d’après *Las Meninas* en 1957 ?', 'mcq', '["3","12","58","100"]'::jsonb, 2, 'Cette série de 58 œuvres est conservée au Museu Picasso de Barcelone.', 1),
    ('c1c79642-d2c7-584e-b99f-1c69678a9466'::uuid, 'bdabe43a-4f0a-50f6-830f-1f898e6a6ec7'::uuid, 'Quel artiste colombien est connu pour ses figures rondes, comme *Mona Lisa a los doce años* ?', 'mcq', '["Fernando Botero","Diego Rivera","Joan Miró","Frida Kahlo"]'::jsonb, 0, 'Botero (1932-2023) a revisité de nombreux chefs-d’œuvre avec ses volumes généreux.', 2),
    ('52bda818-b94f-5f26-b6f1-08432ef2fba9'::uuid, 'bdabe43a-4f0a-50f6-830f-1f898e6a6ec7'::uuid, 'Quel tableau de Dalí montre des montres molles ?', 'mcq', '["Guernica","Las Meninas","Las dos Fridas","La persistance de la mémoire"]'::jsonb, 3, 'Peint en 1931, c’est une icône du surréalisme.', 3),
    ('0e079a4a-6fcd-52a0-9129-76b37dcc310c'::uuid, 'bdabe43a-4f0a-50f6-830f-1f898e6a6ec7'::uuid, 'Dans quelle région d’Espagne est née l’entreprise Zara ?', 'mcq', '["En Catalogne","En Galice","En Andalousie","À Madrid"]'::jsonb, 1, 'Inditex, maison mère de Zara, a été fondée en 1975 en Galice (siège à Arteixo).', 4),
    ('c3cff855-55f2-58c7-9e37-ee6ce6eef3ec'::uuid, 'bdabe43a-4f0a-50f6-830f-1f898e6a6ec7'::uuid, 'Que reprochait le Mexique à Carolina Herrera en 2019 ?', 'mcq', '["Des prix trop élevés","Des défilés trop longs","D’avoir repris des motifs indigènes sans les citer","D’avoir quitté le Venezuela"]'::jsonb, 2, 'Le débat porte sur l’appropriation culturelle.', 5),
    ('f9900a34-031f-51fe-b025-723798119665'::uuid, 'bdabe43a-4f0a-50f6-830f-1f898e6a6ec7'::uuid, 'Qui est La Llorona ?', 'mcq', '["Une femme en pleurs qui cherche ses enfants la nuit","Une reine inca","Une sainte andalouse","Une chanteuse de flamenco"]'::jsonb, 0, 'Cette légende mexicaine a été reprise au cinéma et en chanson.', 6),
    ('f21ff06a-fc64-5a33-ba6b-f08f259762a9'::uuid, 'bdabe43a-4f0a-50f6-830f-1f898e6a6ec7'::uuid, 'D’où vient le mythe d’El Dorado ?', 'mcq', '["D’un roman de Cervantes","D’un rite muisca à la lagune de Guatavita","D’une mine du Potosí","D’un tableau du Prado"]'::jsonb, 1, 'Un chef se couvrait de poudre d’or : les conquistadors en ont fait une cité d’or imaginaire.', 7),
    ('f2615af0-f2ab-5eb7-a665-3a6349ce429c'::uuid, 'bdabe43a-4f0a-50f6-830f-1f898e6a6ec7'::uuid, 'Que signifie *la obra maestra* ?', 'mcq', '["Le maître d’école","L’œuvre de jeunesse","Le musée","Le chef-d’œuvre"]'::jsonb, 3, 'Littéralement « l’œuvre maîtresse ».', 8),
    ('404a3534-dbc0-5740-921f-cf61bb1221db'::uuid, 'bdabe43a-4f0a-50f6-830f-1f898e6a6ec7'::uuid, 'Comment dit-on « s’inspirer de » ?', 'mcq', '["inspirarse de","inspirarse en","inspirar a","inspirarse con"]'::jsonb, 1, 'Attention à la préposition : *inspirarse en*.', 9),
    ('d67272b2-ed06-5f53-97ad-33b931fc362a'::uuid, 'bdabe43a-4f0a-50f6-830f-1f898e6a6ec7'::uuid, 'Cristóbal Balenciaga était un couturier basque.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Né à Getaria en 1895, il s’inspirait des costumes espagnols.', 10),
    ('ff527e4f-1e2a-57b0-b9e6-aa1f71f1f706'::uuid, 'bdabe43a-4f0a-50f6-830f-1f898e6a6ec7'::uuid, 'Quelle expression permet de comparer une reprise à son modèle ?', 'mcq', '["Ojalá…","A diferencia del original…","Esto se debe a que…","Habría que…"]'::jsonb, 1, '*A diferencia de* = à la différence de.', 11),
    ('25b9ac2c-6e44-5878-bed4-2bb755aa4f89'::uuid, 'bdabe43a-4f0a-50f6-830f-1f898e6a6ec7'::uuid, '*Rendir homenaje a* signifie…', 'mcq', '["Rendre un devoir","Critiquer","Rendre hommage à","Copier"]'::jsonb, 2, '*El artista rinde homenaje a Velázquez.*', 12),
    ('ee99ead3-ace3-5a9b-86fa-77aa8b108021'::uuid, '926be5a5-4518-5880-8f59-a52934c42355'::uuid, 'Combien l’Espagne compte-t-elle de communautés autonomes ?', 'mcq', '["12","17","22","50"]'::jsonb, 1, 'Dix-sept communautés, plus les villes autonomes de Ceuta et Melilla.', 1),
    ('b1c9d24b-b787-54a0-b308-3e04cb00354b'::uuid, '926be5a5-4518-5880-8f59-a52934c42355'::uuid, 'Depuis quand Madrid est-elle la capitale de l’Espagne ?', 'mcq', '["1492","1812","1561","1978"]'::jsonb, 2, 'Philippe II y installe la cour en 1561.', 2),
    ('bc0125b8-1e66-5011-825e-13ab6d31275e'::uuid, '926be5a5-4518-5880-8f59-a52934c42355'::uuid, 'Dans quel musée madrilène se trouve *Guernica* de Picasso ?', 'mcq', '["Le Reina Sofía","Le Prado","Le Thyssen","Le Museu Picasso"]'::jsonb, 0, 'Le tableau de 1937 y est exposé depuis 1992.', 3),
    ('5230725b-a206-5273-b030-70ab8276164d'::uuid, '926be5a5-4518-5880-8f59-a52934c42355'::uuid, 'Quelle catastrophe a touché la Galice en 2002 ?', 'mcq', '["Un tremblement de terre","Une sécheresse historique","Une éruption volcanique","La marée noire du *Prestige*"]'::jsonb, 3, 'Le mouvement citoyen *Nunca Máis* est né de cette catastrophe.', 4),
    ('21bf7469-20de-594d-9b2d-53f59ddf328d'::uuid, '926be5a5-4518-5880-8f59-a52934c42355'::uuid, 'Qu’a obtenu la lagune de la Mar Menor en 2022 ?', 'mcq', '["Le statut de parc national","La personnalité juridique","L’inscription à l’UNESCO","Une interdiction de baignade définitive"]'::jsonb, 1, 'Une première en Europe : la lagune peut être défendue en justice pour elle-même.', 5),
    ('c03c0e77-0eb4-59c0-a147-3d6b11d22f89'::uuid, '926be5a5-4518-5880-8f59-a52934c42355'::uuid, 'De quelle région le flamenco est-il originaire ?', 'mcq', '["La Galice","Le Pays basque","L’Andalousie","La Catalogne"]'::jsonb, 2, 'Il est andalou et gitan, inscrit à l’UNESCO en 2010.', 6),
    ('faf11898-f649-58c6-9b9e-d868083040b0'::uuid, '926be5a5-4518-5880-8f59-a52934c42355'::uuid, 'Que désigne la Puerta del Sol ?', 'mcq', '["Une plage de Valence","Une porte de l’Alhambra","Un musée","Le kilomètre zéro des routes d’Espagne"]'::jsonb, 3, 'C’est aussi là qu’on mange les douze raisins du Nouvel An.', 7),
    ('b174361e-e09d-59ea-8362-5d4fa0534113'::uuid, '926be5a5-4518-5880-8f59-a52934c42355'::uuid, 'Que signifie *el tópico* ?', 'mcq', '["Le cliché","Le sujet d’examen","Le tropique","Le touriste"]'::jsonb, 0, 'Faux ami : *un tópico* est un lieu commun, un cliché.', 8),
    ('ebf1b618-5d96-535a-8831-3201d4b3279c'::uuid, '926be5a5-4518-5880-8f59-a52934c42355'::uuid, 'La paella est un plat originaire de Valence.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un plat valencien, pas un plat « national » partagé partout.', 9),
    ('422beb9a-65bc-562a-90b5-0d8439c8b89d'::uuid, '926be5a5-4518-5880-8f59-a52934c42355'::uuid, 'Comment dit-on « la marée noire » ?', 'mcq', '["la marea oscura","la marea negra","la ola negra","el mar sucio"]'::jsonb, 1, '*Negro* ici, comme en français « noire ».', 10),
    ('57001319-7f0d-55a6-9d10-7e43d0b55d21'::uuid, '926be5a5-4518-5880-8f59-a52934c42355'::uuid, 'Quelle formule sert à contredire un cliché ?', 'mcq', '["Por ejemplo…","Es el caso de…","Se suele pensar que…, pero en realidad…","Me llama la atención…"]'::jsonb, 2, '*Soler* + infinitif exprime l’habitude : « on a coutume de penser ».', 11),
    ('5de79745-fd2c-57a3-b8b0-9f096d5afff6'::uuid, '926be5a5-4518-5880-8f59-a52934c42355'::uuid, 'Quel est le point culminant de l’Espagne ?', 'mcq', '["Le Mulhacén","L’Aneto","Le Teide","Le Montserrat"]'::jsonb, 2, 'Le Teide, volcan de Tenerife (Canaries), culmine à 3 715 m ; le Mulhacén est le plus haut sommet de la péninsule.', 12),
    ('f7086c3d-8edf-536a-ae36-2702d03431e0'::uuid, 'd6b7f12c-6706-59b1-a686-54b4901fdebc'::uuid, 'Quel est l’impératif (tú) de *hacer* ?', 'mcq', '["hace","haga","haz","hazte"]'::jsonb, 2, '*Hacer* fait partie des huit irréguliers : *haz*.', 1),
    ('d6a4f861-c1c7-5e14-9716-78d9ec270aa5'::uuid, 'd6b7f12c-6706-59b1-a686-54b4901fdebc'::uuid, 'Comment se forme l’impératif négatif ?', 'mcq', '["no + infinitif","no + subjonctif présent","no + impératif","no + présent de l’indicatif"]'::jsonb, 1, 'À toutes les personnes : *no hables, no comáis, no hagan*.', 2),
    ('6e1612c5-4194-5f5a-8a03-32e8ab3c40c8'::uuid, 'd6b7f12c-6706-59b1-a686-54b4901fdebc'::uuid, 'Quel est l’impératif vosotros de *comer* ?', 'mcq', '["comed","comáis","comad","comid"]'::jsonb, 0, 'On remplace le -r de l’infinitif par -d.', 3),
    ('310aea13-65c9-59d2-82e2-0e66329b142d'::uuid, 'd6b7f12c-6706-59b1-a686-54b4901fdebc'::uuid, 'Comment dit-on « Ne me le dis pas » (tú) ?', 'mcq', '["No dímelo","No me lo dices","No lo me digas","No me lo digas"]'::jsonb, 3, 'Au négatif, les pronoms précèdent le verbe, au subjonctif, dans l’ordre COI + COD.', 4),
    ('83fad934-e847-5f81-a803-d5a82368da39'::uuid, 'd6b7f12c-6706-59b1-a686-54b4901fdebc'::uuid, '*Sentémonos* : pourquoi le -s de *sentemos* disparaît-il ?', 'mcq', '["C’est une faute d’orthographe tolérée","Il tombe devant le pronom nos","Parce que le verbe est irrégulier","Parce que c’est du subjonctif"]'::jsonb, 1, 'On écrit *sentémonos*, *vámonos*.', 5),
    ('dc62a1db-0842-5cc8-9dcd-68eb4b831322'::uuid, 'd6b7f12c-6706-59b1-a686-54b4901fdebc'::uuid, 'Quel est l’impératif tú de *salir* ?', 'mcq', '["sal","sale","salga","sali"]'::jsonb, 0, '*Salir → sal*, comme *poner → pon*, *venir → ven*, *tener → ten*.', 6),
    ('554181eb-6209-5b53-8bee-56720a56e9ed'::uuid, 'd6b7f12c-6706-59b1-a686-54b4901fdebc'::uuid, 'Quelle forme correspond à « Lève-toi » (tú) ?', 'mcq', '["Te levanta","Levantate","Levántate","Te levantes"]'::jsonb, 2, 'Enclise du pronom et accent écrit pour garder l’accent tonique sur *-van-*.', 7),
    ('36a015cb-cc11-56c9-b5a1-cc001efcc7dc'::uuid, 'd6b7f12c-6706-59b1-a686-54b4901fdebc'::uuid, 'Pour *usted*, l’impératif affirmatif emprunte ses formes…', 'mcq', '["À l’indicatif présent","Au futur","À l’infinitif","Au subjonctif présent"]'::jsonb, 3, '*Hable usted, coma usted, siéntese.*', 8),
    ('c6528305-389a-50e1-ac21-4b6f8036a3b6'::uuid, 'd6b7f12c-6706-59b1-a686-54b4901fdebc'::uuid, '*Levantaos* est la forme correcte de l’impératif vosotros de *levantarse*.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le -d tombe devant *os* ; seule exception : *idos*.', 9),
    ('512e9cb1-00d8-5dba-bd71-14033126ebd4'::uuid, 'd6b7f12c-6706-59b1-a686-54b4901fdebc'::uuid, 'Quel est l’impératif tú de *ser* ?', 'mcq', '["es","sé","sea","sed"]'::jsonb, 1, '*Sé bueno* = sois sage ; *sed* est la forme vosotros.', 10),
    ('d48debfe-6eba-5243-adeb-78f231fddf48'::uuid, 'd6b7f12c-6706-59b1-a686-54b4901fdebc'::uuid, 'Quelle phrase est une défense correcte adressée à un ami ?', 'mcq', '["No toca eso","No toques eso","No tocar eso","No tócalo"]'::jsonb, 1, 'Défense = *no* + subjonctif : *no toques*.', 11),
    ('ab55d08d-dd0d-55dc-8014-e753b3c818b8'::uuid, 'd6b7f12c-6706-59b1-a686-54b4901fdebc'::uuid, 'Quel est l’impératif tú de *volver* ?', 'mcq', '["volve","vuelva","vuelve","volved"]'::jsonb, 2, 'La diphtongue se maintient : 3e personne du présent, *vuelve*.', 12),
    ('df0201c1-eafe-543d-b519-b7dbbe1e1fb8'::uuid, 'fb9e0377-de23-53f8-b921-141e392b3713'::uuid, 'Quelle préposition exprime le but devant un infinitif ?', 'mcq', '["por","para","a","de"]'::jsonb, 1, '*Estudio para aprobar* : dans quel but ? → para.', 1),
    ('acb8d6e2-ef76-528f-b27a-40c7bf3ca3ef'::uuid, 'fb9e0377-de23-53f8-b921-141e392b3713'::uuid, 'Comment dit-on « par téléphone » ?', 'mcq', '["para teléfono","en teléfono","por teléfono","de teléfono"]'::jsonb, 2, 'Le moyen s’exprime avec *por*.', 2),
    ('83e1bf49-faf5-525e-b33c-dbe4d245375e'::uuid, 'fb9e0377-de23-53f8-b921-141e392b3713'::uuid, '*Lo compré ___ diez euros.* Quel mot complète la phrase ?', 'mcq', '["para","a","de","por"]'::jsonb, 3, 'L’échange et le prix se disent avec *por*.', 3),
    ('f8cf1584-5751-57cb-a710-248152ea8dff'::uuid, 'fb9e0377-de23-53f8-b921-141e392b3713'::uuid, '*Este regalo es ___ ti.* Quel mot complète la phrase ?', 'mcq', '["para","por","a","con"]'::jsonb, 0, 'Le destinataire s’exprime avec *para*.', 4),
    ('78e9041e-7e35-5c1d-964e-9361f710e72b'::uuid, 'fb9e0377-de23-53f8-b921-141e392b3713'::uuid, 'Comment dit-on « le matin » (moment de la journée) ?', 'mcq', '["para la mañana","por la mañana","en la mañana","a la mañana"]'::jsonb, 1, '*Por la mañana, por la tarde, por la noche* (l’Amérique dit aussi *en la mañana*).', 5),
    ('213935fc-0544-58d9-8df9-a055aefc361f'::uuid, 'fb9e0377-de23-53f8-b921-141e392b3713'::uuid, '*Don Quijote fue escrito ___ Cervantes.* Quel mot complète la phrase ?', 'mcq', '["para","de","por","con"]'::jsonb, 2, 'L’agent du passif est introduit par *por*.', 6),
    ('5c082f7e-5a2a-5c5b-bc3e-cde327901853'::uuid, 'fb9e0377-de23-53f8-b921-141e392b3713'::uuid, 'Que signifie *Para mí, es fácil* ?', 'mcq', '["C’est facile pour moi à faire à ta place","Selon moi, c’est facile","Grâce à moi, c’est facile","C’est facile à cause de moi"]'::jsonb, 1, '*Para mí* introduit un point de vue.', 7),
    ('fc3779de-2fbb-59e6-bfd2-f32af69bd789'::uuid, 'fb9e0377-de23-53f8-b921-141e392b3713'::uuid, 'Que signifie *La casa está por limpiar* ?', 'mcq', '["La maison est propre","La maison va être vendue","La maison reste à nettoyer","La maison est en travaux"]'::jsonb, 2, '*Estar por* + infinitif = rester à faire.', 8),
    ('1f96b738-d067-5e35-874f-08dda1a35726'::uuid, 'fb9e0377-de23-53f8-b921-141e392b3713'::uuid, '*Por eso* signifie « c’est pourquoi ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Expression figée de conséquence : *Llovía; por eso no salí.*', 9),
    ('bdd9a182-e5e2-52e9-ac26-1d60390dbffd'::uuid, 'fb9e0377-de23-53f8-b921-141e392b3713'::uuid, '*Pasé por Toledo* signifie…', 'mcq', '["Je suis passé par Tolède","Je vais à Tolède","Je suis resté à Tolède","Je suis parti de Tolède"]'::jsonb, 0, '*Por* marque le lieu traversé.', 10),
    ('4f8b1105-c90f-5615-8959-980fef18753a'::uuid, 'fb9e0377-de23-53f8-b921-141e392b3713'::uuid, '*Lo hizo por amor* : quelle valeur a *por* ?', 'mcq', '["Le but","Le destinataire","La date limite","La cause"]'::jsonb, 3, 'Il l’a fait à cause de l’amour, mû par l’amour.', 11),
    ('f81cca58-9ce4-50ce-84b8-de0ff4de3a1c'::uuid, 'fb9e0377-de23-53f8-b921-141e392b3713'::uuid, 'Comment dit-on « pour lundi » (date limite) ?', 'mcq', '["por el lunes","a el lunes","para el lunes","en el lunes"]'::jsonb, 2, 'L’échéance se dit avec *para* : *Es para el lunes*.', 12),
    ('203e43a6-9394-544a-a92d-3c5fbf9cf47a'::uuid, 'b3b81d7a-2a10-5d30-ba33-c59785dca03f'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Veo María","Veo a María","Veo en María","Veo de María"]'::jsonb, 1, 'Un COD de personne précise est introduit par *a*.', 1),
    ('2eff45c3-9ace-5a30-ba5d-4155c73d41ff'::uuid, 'b3b81d7a-2a10-5d30-ba33-c59785dca03f'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Tengo a dos hermanos","Tengo de dos hermanos","Tengo dos hermanos","Tengo en dos hermanos"]'::jsonb, 2, '*Tener* ne prend pas de *a* devant son complément.', 2),
    ('df59709b-33e7-59ba-a19c-f0d5006a780f'::uuid, 'b3b81d7a-2a10-5d30-ba33-c59785dca03f'::uuid, 'Que signifie *Quiero a mis padres* ?', 'mcq', '["J’aime mes parents","Je veux mes parents","Je cherche mes parents","Je vais chez mes parents"]'::jsonb, 0, '*Querer a alguien* = aimer quelqu’un.', 3),
    ('73374c1b-7ee3-5972-b200-20d9fd0c1a79'::uuid, 'b3b81d7a-2a10-5d30-ba33-c59785dca03f'::uuid, '*Estoy ___ la playa.* Quel mot complète la phrase ?', 'mcq', '["a","de","para","en"]'::jsonb, 3, 'Pas de mouvement : *en*.', 4),
    ('44ffbf35-9a9f-509a-9fc4-2580931527ec'::uuid, 'b3b81d7a-2a10-5d30-ba33-c59785dca03f'::uuid, 'Comment dit-on « à pied » ?', 'mcq', '["en pie","a pie","de pie","por pie"]'::jsonb, 1, 'On dit *a pie* et *a caballo*, mais *en tren*, *en coche*. (*De pie* = debout.)', 5),
    ('e5bef0de-3549-5cff-a184-b8679ef4797d'::uuid, 'b3b81d7a-2a10-5d30-ba33-c59785dca03f'::uuid, 'Comment dit-on « à huit heures » ?', 'mcq', '["en las ocho","por las ocho","a las ocho","las ocho"]'::jsonb, 2, 'L’heure se dit avec *a*.', 6),
    ('36e7da0f-b4e9-557d-9414-71a384bcc9f7'::uuid, 'b3b81d7a-2a10-5d30-ba33-c59785dca03f'::uuid, 'Comment dit-on « le lundi, je vais au sport » ?', 'mcq', '["El lunes voy al deporte","En lunes voy al deporte","A el lunes voy al deporte","Por lunes voy al deporte"]'::jsonb, 0, 'Aucune préposition devant un jour : *el lunes*.', 7),
    ('f0f4febf-2ac4-5d42-9b5a-0cb66b8ec4eb'::uuid, 'b3b81d7a-2a10-5d30-ba33-c59785dca03f'::uuid, 'Comment dit-on « dans deux jours » (futur) ?', 'mcq', '["en dos días","a dos días","hace dos días","dentro de dos días"]'::jsonb, 3, '*Dentro de* marque le délai futur ; *hace dos días* = il y a deux jours.', 8),
    ('23065dbf-a0a2-5690-a893-974af8ebb0af'::uuid, 'b3b81d7a-2a10-5d30-ba33-c59785dca03f'::uuid, '*No veo a nadie* est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Nadie, alguien, quien* sont précédés de *a* quand ils sont COD.', 9),
    ('6d63b545-2f74-59d7-9178-bf6e81105ce4'::uuid, 'b3b81d7a-2a10-5d30-ba33-c59785dca03f'::uuid, 'Quelle phrase dit « Il commence à pleuvoir » ?', 'mcq', '["Empieza de llover","Empieza a llover","Empieza llover","Empieza en llover"]'::jsonb, 1, '*Empezar a* + infinitif.', 10),
    ('29f0835b-ed6c-5de1-a226-1f6241f72292'::uuid, 'b3b81d7a-2a10-5d30-ba33-c59785dca03f'::uuid, '*Busco un médico* : pourquoi n’y a-t-il pas de *a* ?', 'mcq', '["Parce que *médico* est masculin","Parce que *buscar* ne prend jamais *a*","Parce que le médecin n’est pas précis","C’est une faute"]'::jsonb, 2, 'N’importe quel médecin : personne indéterminée, pas de *a*. Un médecin précis : *busco al médico*.', 11),
    ('52b3c055-511f-5b84-89f1-e604c1049932'::uuid, 'b3b81d7a-2a10-5d30-ba33-c59785dca03f'::uuid, 'Comment dit-on « en été » ?', 'mcq', '["a verano","en verano","por verano","de verano"]'::jsonb, 1, 'Mois, saisons et années prennent *en*.', 12),
    ('9bfd928f-20f2-5f47-84ec-e25038700bbe'::uuid, 'a873b23e-9758-56a5-9f2a-3401f0219d7a'::uuid, 'Comment dit-on « il y a deux ans » (moment passé) ?', 'mcq', '["hay dos años","hace dos años","desde dos años","lleva dos años"]'::jsonb, 1, '*Hace* + durée situe un moment dans le passé.', 1),
    ('abbf303b-ac7e-5331-bd70-e3ac6edc9bba'::uuid, 'a873b23e-9758-56a5-9f2a-3401f0219d7a'::uuid, 'Comment dit-on « il y a beaucoup d’élèves » ?', 'mcq', '["Hace muchos alumnos","Está muchos alumnos","Hay muchos alumnos","Lleva muchos alumnos"]'::jsonb, 2, '*Hay* exprime l’existence.', 2),
    ('105d25b9-c7fe-59e5-bec3-0ea887aa4996'::uuid, 'a873b23e-9758-56a5-9f2a-3401f0219d7a'::uuid, 'Quelle phrase dit « J’habite ici depuis trois ans » ?', 'mcq', '["Vivo aquí desde hace tres años","Viví aquí hace tres años","Vivo aquí hay tres años","Vivo aquí dentro de tres años"]'::jsonb, 0, 'Durée qui continue : présent + *desde hace*.', 3),
    ('3c8cffd4-0995-5df3-be05-40af4ce90879'::uuid, 'a873b23e-9758-56a5-9f2a-3401f0219d7a'::uuid, '*Llevo una hora ___.* Quel mot complète la phrase (« ça fait une heure que je t’attends ») ?', 'mcq', '["esperarte","esperado","que te espero","esperándote"]'::jsonb, 3, '*Llevar* + durée + gérondif.', 4),
    ('cd45bebe-46f1-54d5-8043-b5c59edb3bc6'::uuid, 'a873b23e-9758-56a5-9f2a-3401f0219d7a'::uuid, 'Dans *Hace tres años que vivo aquí*, à quel temps est le verbe ?', 'mcq', '["Au passé simple","Au présent, car l’action continue","Au futur","À l’imparfait"]'::jsonb, 1, 'Comme en français : « cela fait trois ans que j’habite ici ».', 5),
    ('42049769-5f17-599b-9ebe-9cb8cff84eb6'::uuid, 'a873b23e-9758-56a5-9f2a-3401f0219d7a'::uuid, 'Comment dit-on « au bout de deux jours » ?', 'mcq', '["dentro de dos días","durante dos días","al cabo de dos días","hace dos días"]'::jsonb, 2, '*Al cabo de* = au bout de.', 6),
    ('3fbcef3a-f432-5d0c-9ec5-7587f5719ec6'::uuid, 'a873b23e-9758-56a5-9f2a-3401f0219d7a'::uuid, '*Llegué a Madrid hace dos años* : le passé simple est correct, car l’arrivée est une action finie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Moment ponctuel et terminé : passé simple.', 7),
    ('88b536d7-4aac-5dd3-ab42-37ce57e6d5f7'::uuid, 'a873b23e-9758-56a5-9f2a-3401f0219d7a'::uuid, 'Comment dit-on « depuis 2022 » ?', 'mcq', '["desde hace 2022","hace 2022","dentro de 2022","desde 2022"]'::jsonb, 3, '*Desde* + date ; *desde hace* + durée.', 8),
    ('8dcbb737-90ed-56f1-abd9-06f6e3ae42dc'::uuid, 'a873b23e-9758-56a5-9f2a-3401f0219d7a'::uuid, 'Au passé, « cela faisait une heure que j’attendais » se dit…', 'mcq', '["Hace una hora que esperé","Llevaba una hora esperando","Llevo una hora esperando","Hubo una hora que esperaba"]'::jsonb, 1, 'On décale à l’imparfait : *llevaba… esperando* ou *hacía… que esperaba*.', 9),
    ('c0860469-a4c0-5e9e-8a83-64b995dc9efe'::uuid, 'a873b23e-9758-56a5-9f2a-3401f0219d7a'::uuid, 'Comment demande-t-on « depuis quand ? » ?', 'mcq', '["¿desde cuándo?","¿hace cuándo?","¿cuándo hace?","¿desde qué?"]'::jsonb, 0, 'Pour la durée : *¿cuánto tiempo hace que…?*', 10),
    ('c776e6d7-7635-55a6-b560-f36628f68314'::uuid, 'a873b23e-9758-56a5-9f2a-3401f0219d7a'::uuid, '*Dentro de dos días* signifie…', 'mcq', '["Il y a deux jours","Pendant deux jours","Dans deux jours","Depuis deux jours"]'::jsonb, 2, 'Délai tourné vers le futur.', 11),
    ('b6e464a9-6437-576c-bdd4-e72cb0161e2c'::uuid, 'a873b23e-9758-56a5-9f2a-3401f0219d7a'::uuid, '*Hay dos años que vivo aquí* est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Faute classique : il faut *Hace dos años que vivo aquí*.', 12),
    ('5bb47c17-5086-5b8f-ad0c-85541403ccbb'::uuid, '28f9b267-8214-514b-8d86-9e6fd184b773'::uuid, 'Comment dit-on « 100 euros » ?', 'mcq', '["ciento euros","cien euros","cientos euros","un ciento euros"]'::jsonb, 1, '*Cien* seul ou devant un nom ; *ciento* de 101 à 199.', 1),
    ('40d97b40-24ad-5051-8a3e-de43fefc22cf'::uuid, '28f9b267-8214-514b-8d86-9e6fd184b773'::uuid, 'Comment écrit-on 500 ?', 'mcq', '["cincocientos","quincientos","quinientos","cinco cientos"]'::jsonb, 2, 'Forme irrégulière, comme *setecientos* et *novecientos*.', 2),
    ('cccebcfd-10d5-5ac5-8427-3733bf3f03eb'::uuid, '28f9b267-8214-514b-8d86-9e6fd184b773'::uuid, 'Comment dit-on « 200 filles » ?', 'mcq', '["doscientas chicas","doscientos chicas","dos cien chicas","doscientas de chicas"]'::jsonb, 0, 'Les centaines s’accordent avec le nom.', 3),
    ('aadd98fb-715e-5f69-9fb8-e8c7e4835287'::uuid, '28f9b267-8214-514b-8d86-9e6fd184b773'::uuid, 'Comment dit-on « un million de personnes » ?', 'mcq', '["un millón personas","un mil personas","millón de personas","un millón de personas"]'::jsonb, 3, '*Millón* est un nom : il faut *de*.', 4),
    ('d6ec55ba-7ffb-5f79-a6f5-0c1b9593c11c'::uuid, '28f9b267-8214-514b-8d86-9e6fd184b773'::uuid, 'Comment écrit-on 45 ?', 'mcq', '["cuarentaicinco","cuarenta y cinco","cuarenta cinco","cuarentay cinco"]'::jsonb, 1, 'À partir de 31, trois mots avec *y*.', 5),
    ('0a5ba0e4-72d1-58e5-a037-05891f06c4ff'::uuid, '28f9b267-8214-514b-8d86-9e6fd184b773'::uuid, 'Comment dit-on « Il est une heure » ?', 'mcq', '["Son la una","Es las una","Es la una","Está la una"]'::jsonb, 2, 'Singulier pour une heure seulement : *es la una* ; *son las dos*.', 6),
    ('ca63e000-0b6d-50b3-8ff6-c6c8aae4f532'::uuid, '28f9b267-8214-514b-8d86-9e6fd184b773'::uuid, 'Comment dit-on 3 h 45 ?', 'mcq', '["Son las cuatro menos cuarto","Son las tres y cuarenta y cinco menos","Son las tres menos cuarto","Es las cuatro y cuarto"]'::jsonb, 0, 'On retire un quart à l’heure suivante, comme en français.', 7),
    ('4e8a5c39-d22f-5c45-b55d-60f93074788b'::uuid, '28f9b267-8214-514b-8d86-9e6fd184b773'::uuid, 'Comment lit-on « le XXIe siècle » ?', 'mcq', '["el siglo vigésimo primero","el siglo veintiún","el siglo veinte y uno","el siglo veintiuno"]'::jsonb, 3, 'Au-delà de dix, on emploie le cardinal : *el siglo XXI* se lit *veintiuno*.', 8),
    ('90814078-b736-5ab2-bf66-6db7b37e8269'::uuid, '28f9b267-8214-514b-8d86-9e6fd184b773'::uuid, '*Mil* est invariable : on dit *dos mil*.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Contrairement à *millón*, qui fait *millones*.', 9),
    ('6ef68882-cf1f-5c70-87ff-bd44c6a3f2fb'::uuid, '28f9b267-8214-514b-8d86-9e6fd184b773'::uuid, 'Comment dit-on « le premier jour » ?', 'mcq', '["el primero día","el primer día","el uno día","el primo día"]'::jsonb, 1, '*Primero* perd son -o devant un nom masculin singulier.', 10),
    ('4ef443f8-842d-5c64-be62-8dc90d03c515'::uuid, '28f9b267-8214-514b-8d86-9e6fd184b773'::uuid, 'Comment écrit-on 21 ans ?', 'mcq', '["veinte y un años","veintiuno años","veintiún años","veintiuna años"]'::jsonb, 2, 'Un seul mot, et *uno* s’apocope en *-ún* devant un nom masculin.', 11),
    ('00e75668-1585-5bd1-87e7-60156079883f'::uuid, '28f9b267-8214-514b-8d86-9e6fd184b773'::uuid, 'Comment écrit-on 105 ?', 'mcq', '["ciento y cinco","ciento cinco","cien cinco","cien y cinco"]'::jsonb, 1, 'Le *y* ne se met qu’entre dizaines et unités.', 12),
    ('fa810cdb-706c-571b-b854-f5edd5baa34f'::uuid, 'fefcbd5c-dceb-55bb-b413-0bf07a84758d'::uuid, 'Quel est le diminutif de *café* ?', 'mcq', '["cafeíto","cafecito","cafito","cafetito"]'::jsonb, 1, 'Après une voyelle accentuée finale, on ajoute *-cito*.', 1),
    ('a6efaf3b-9964-54ba-a2b1-b52df91a01c0'::uuid, 'fefcbd5c-dceb-55bb-b413-0bf07a84758d'::uuid, 'Quel est le diminutif de *poco* ?', 'mcq', '["pocito","pocquito","poquito","pocoito"]'::jsonb, 2, 'Le *c* devient *qu* pour garder le son [k].', 2),
    ('71c2e381-fce7-56fd-8906-b65c5fe7aaf3'::uuid, 'fefcbd5c-dceb-55bb-b413-0bf07a84758d'::uuid, 'Que signifie *mi abuelita* ?', 'mcq', '["Ma grand-mère chérie","Ma petite-fille","Ma grand-mère de petite taille seulement","Mon arrière-grand-mère"]'::jsonb, 0, 'Le diminutif exprime surtout l’affection.', 3),
    ('1262cc5e-c2eb-5dd4-9e1b-b964a9dd4069'::uuid, 'fefcbd5c-dceb-55bb-b413-0bf07a84758d'::uuid, 'Que signifie *un portazo* ?', 'mcq', '["Une grande porte","Un portier","Une petite porte","Un claquement de porte"]'::jsonb, 3, '*-azo* désigne souvent un coup donné avec l’objet.', 4),
    ('2fc76e05-96ce-51f4-9a32-8ec1a584f1ea'::uuid, 'fefcbd5c-dceb-55bb-b413-0bf07a84758d'::uuid, 'Que signifie *una casucha* ?', 'mcq', '["Une belle maison","Une masure, une maison misérable","Une maison de campagne","Une petite maison mignonne"]'::jsonb, 1, '*-ucho, -ucha* est péjoratif.', 5),
    ('b02b7115-f32e-50e3-bf59-bb1dc7762538'::uuid, 'fefcbd5c-dceb-55bb-b413-0bf07a84758d'::uuid, 'Que signifie *bocadillo* ?', 'mcq', '["Une petite bouche","Un bouchon","Un sandwich","Un baiser"]'::jsonb, 2, 'Mot lexicalisé : ce n’est plus un diminutif.', 6),
    ('48136e37-41d6-53da-97f3-a72ccb3ce0a8'::uuid, 'fefcbd5c-dceb-55bb-b413-0bf07a84758d'::uuid, 'Que désigne *una palabrota* ?', 'mcq', '["Un gros mot","Un long discours","Un mot savant","Un petit mot doux"]'::jsonb, 0, '*-ota* peut être augmentatif et péjoratif.', 7),
    ('ca60490c-e6db-5c4a-9bda-d8e35d8fdaa1'::uuid, 'fefcbd5c-dceb-55bb-b413-0bf07a84758d'::uuid, 'Dans quel pays appelle-t-on les habitants *ticos*, à cause de leur diminutif en *-ico* ?', 'mcq', '["Au Mexique","En Argentine","Au Chili","Au Costa Rica"]'::jsonb, 3, 'Les Costariciens disent *chiquitico*, *momentico*.', 8),
    ('c7999c92-1c6c-53ad-81df-994e5b25c9da'::uuid, 'fefcbd5c-dceb-55bb-b413-0bf07a84758d'::uuid, '*Ratón* (souris) est aujourd’hui un mot autonome, et non un simple augmentatif de *rata*.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *sillón* ou *cajón*, il a pris un sens propre.', 9),
    ('0504bd9f-939a-55d3-914a-77c35ce4eb4b'::uuid, 'fefcbd5c-dceb-55bb-b413-0bf07a84758d'::uuid, 'Quel est le diminutif de *flor* ?', 'mcq', '["florita","florecita","florcita","florilla"]'::jsonb, 1, 'Mot d’une syllabe : *-ecito, -ecita*.', 10),
    ('fa5aecf3-a62c-506f-99f6-74251d83e81f'::uuid, 'fefcbd5c-dceb-55bb-b413-0bf07a84758d'::uuid, 'Au Mexique, que peut vouloir dire *ahorita* ?', 'mcq', '["Hier","Jamais","Tout de suite, ou un peu plus tard","Il y a longtemps"]'::jsonb, 2, 'Le diminutif s’accroche aux adverbes en Amérique latine.', 11),
    ('21d17168-9a60-53f9-ba79-679ebd1322b3'::uuid, 'fefcbd5c-dceb-55bb-b413-0bf07a84758d'::uuid, 'Quel suffixe exprime la grande taille, parfois avec moquerie ?', 'mcq', '["-ito","-illo","-ecito","-ón"]'::jsonb, 3, '*cabezón* = grosse tête, ou têtu.', 12),
    ('f2f6f4f1-2087-5531-8cfa-55da0a38985a'::uuid, 'cbb158ae-4612-55bf-a4c8-35e55d33b1eb'::uuid, 'En quelle année les Espagnoles ont-elles obtenu le droit de vote ?', 'mcq', '["1931","1945","1977","1905"]'::jsonb, 0, 'Sous la IIe République, grâce notamment à Clara Campoamor.', 1),
    ('4b650a63-0b5c-5990-a03d-8c31244536df'::uuid, 'cbb158ae-4612-55bf-a4c8-35e55d33b1eb'::uuid, 'Qu’était le *permiso marital* sous Franco ?', 'mcq', '["Un congé de mariage","L’autorisation du mari nécessaire à la femme pour travailler ou ouvrir un compte","Un certificat de mariage religieux","Un impôt sur le mariage"]'::jsonb, 1, 'Il a été supprimé en 1975.', 2),
    ('203a3ab0-7175-5d94-b079-91fe61c18bfb'::uuid, 'cbb158ae-4612-55bf-a4c8-35e55d33b1eb'::uuid, 'Dans quel pays est né le mouvement *Ni una menos* en 2015 ?', 'mcq', '["En Espagne","Au Mexique","En Argentine","Au Chili"]'::jsonb, 2, 'Il dénonce les féminicides et s’est étendu à toute l’Amérique latine.', 3),
    ('f9e278d6-d4d1-5126-9cdc-0c16dadb37dd'::uuid, 'cbb158ae-4612-55bf-a4c8-35e55d33b1eb'::uuid, 'Que désigne la *España vaciada* ?', 'mcq', '["Les plages désertes en hiver","Les régions intérieures qui se dépeuplent","Les villes après la crise de 2008","Les usines fermées"]'::jsonb, 1, 'Teruel, Soria ou Cuenca perdent leurs habitants.', 4),
    ('c8ff906c-ad64-53a8-a5d5-50d1aeb69c87'::uuid, 'cbb158ae-4612-55bf-a4c8-35e55d33b1eb'::uuid, 'Que raconte *Roma* d’Alfonso Cuarón ?', 'mcq', '["La Rome antique","Un voyage en Italie","La vie d’un footballeur","La vie d’une employée de maison indigène à Mexico vers 1970"]'::jsonb, 3, 'Le film mêle l’intime d’une maison et la violence de la rue.', 5),
    ('47dadf9f-2100-5477-a7f6-7024fa8a439e'::uuid, 'cbb158ae-4612-55bf-a4c8-35e55d33b1eb'::uuid, 'Que signifie *la intimidad* ?', 'mcq', '["L’intimidation","La vie privée, l’intimité","L’amitié","La timidité"]'::jsonb, 1, '*Derecho a la intimidad* = droit à la vie privée.', 6),
    ('bf0451d6-ccfa-5743-9b13-b494d14d997a'::uuid, 'cbb158ae-4612-55bf-a4c8-35e55d33b1eb'::uuid, 'En quelle année l’Espagne a-t-elle adopté sa loi contre les violences de genre ?', 'mcq', '["1981","2004","2015","1931"]'::jsonb, 1, 'Cette loi a été pionnière en Europe.', 7),
    ('8d227e93-3706-50f3-be3f-77b694497476'::uuid, 'cbb158ae-4612-55bf-a4c8-35e55d33b1eb'::uuid, 'Que signifie *el ciberacoso* ?', 'mcq', '["Le piratage","La cybersécurité","Le cyberharcèlement","Le cybercafé"]'::jsonb, 2, '*Acosar* = harceler.', 8),
    ('d753d2e3-78c1-5079-82e4-43f1c152a817'::uuid, 'cbb158ae-4612-55bf-a4c8-35e55d33b1eb'::uuid, 'Le 8 mars 2018, une grève féministe massive a eu lieu en Espagne.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Des millions de personnes y ont participé.', 9),
    ('0a689df1-d4a5-5531-9b13-b5d2d6c41c0a'::uuid, 'cbb158ae-4612-55bf-a4c8-35e55d33b1eb'::uuid, 'Quelle formule permet de concéder puis réfuter ?', 'mcq', '["Lo que está en juego es…","Se podría afirmar que…","Es imprescindible que…","Si bien es cierto que…, no es menos cierto que…"]'::jsonb, 3, '« S’il est vrai que…, il n’en est pas moins vrai que… »', 10),
    ('a1edf7e6-434c-57bb-b5c6-fffb7c4ed0df'::uuid, 'cbb158ae-4612-55bf-a4c8-35e55d33b1eb'::uuid, 'Quelle liste est entrée au Parlement espagnol en 2019 pour défendre une province dépeuplée ?', 'mcq', '["Teruel Existe","Soria Vive","Cuenca Ahora","Galicia Unida"]'::jsonb, 0, 'Son nom même est un cri contre l’oubli.', 11),
    ('4eb63293-6e02-5dc5-9ab8-31575998dee4'::uuid, 'cbb158ae-4612-55bf-a4c8-35e55d33b1eb'::uuid, 'Après *Es imprescindible que…*, on emploie l’indicatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une nécessité impersonnelle + *que* entraîne le subjonctif.', 12),
