    ('14c3dcfb-62e3-500c-a178-a4f3bffaf82d'::uuid, 'd5b5106a-cd05-5527-ac87-c2d71aa594e4'::uuid, 'Que prévoit la loi de mémoire démocratique de 2022 ?', 'mcq', '["L’amnistie des anciens ministres","L’interdiction de la corrida","La prise en charge par l’État de la recherche des disparus","Le retour de la monarchie"]'::jsonb, 2, 'L’État prend en charge les exhumations dans les fosses communes.', 2),
    ('4a05a2bc-c2cc-56ec-878e-483a6f875160'::uuid, 'd5b5106a-cd05-5527-ac87-c2d71aa594e4'::uuid, 'Quel film raconte le procès des juntes militaires argentines de 1985 ?', 'mcq', '["Roma","Madres paralelas","La jaula de oro","Argentina, 1985"]'::jsonb, 3, 'Sorti en 2022, il suit le procureur Julio Strassera.', 3),
