    ('9f1819e3-1af9-57b4-90fb-11f99a9df86b'::uuid, 'd5b5106a-cd05-5527-ac87-c2d71aa594e4'::uuid, 'Quand le Musée de la Mémoire et des Droits de l’Homme a-t-il ouvert à Santiago du Chili ?', 'mcq', '["En 1973","En 1990","En 2010","En 2022"]'::jsonb, 2, 'Il retrace la dictature de Pinochet (1973-1990).', 5),
