    ('e66f1fa0-931e-5a4a-ab91-baae3335d089'::uuid, 'd5b5106a-cd05-5527-ac87-c2d71aa594e4'::uuid, 'Dans quel contexte se déroule *El laberinto del fauno* ?', 'mcq', '["Le Mexique révolutionnaire","L’Espagne de 1944, entre maquis et répression","L’Argentine de 1985","Madrid pendant la Movida"]'::jsonb, 1, 'Guillermo del Toro mêle conte fantastique et réalité historique.', 7),
    ('19612fcd-1be8-530f-9a3a-92d6b5ab9f6d'::uuid, 'd5b5106a-cd05-5527-ac87-c2d71aa594e4'::uuid, 'Que signifie *la fosa común* ?', 'mcq', '["Le fossé commun","La place commune","La maison commune","La fosse commune"]'::jsonb, 3, 'Des milliers de victimes de la guerre civile y reposent encore.', 8),
    ('81662d42-e2d1-5571-a8af-654760bba14c'::uuid, 'd5b5106a-cd05-5527-ac87-c2d71aa594e4'::uuid, 'Riaño, en León, est un village englouti par un barrage en 1987.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les habitants ont perdu leurs terres et une part de leur mémoire.', 9),
    ('e5242d8d-9600-51a2-9d04-09bece8e0bf1'::uuid, 'd5b5106a-cd05-5527-ac87-c2d71aa594e4'::uuid, 'Que sont les *andenes* incas ?', 'mcq', '["Des temples","Des routes","Des terrasses de culture","Des canaux souterrains"]'::jsonb, 2, 'Les Incas ont sculpté les pentes des Andes pour cultiver.', 10),
