    ('a3d474ee-b0e5-566c-91c8-c53242a77465'::uuid, 'd5b5106a-cd05-5527-ac87-c2d71aa594e4'::uuid, 'Les restes de Franco reposent toujours au Valle de los Caídos.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils en ont été exhumés en 2019 ; le lieu s’appelle aujourd’hui Cuelgamuros.', 12),
