    ('c8ea529b-32eb-56b4-b157-f9264f747409'::uuid, '78a06d62-564f-5d2c-9e5e-eb55a1c3fdf1'::uuid, 'En quelle année García Márquez a-t-il reçu le prix Nobel ?', 'mcq', '["1967","2010","1982","1945"]'::jsonb, 2, 'Vargas Llosa l’a reçu en 2010.', 6),
    ('3d1b37c8-6323-5743-98be-765f336c2d6b'::uuid, '78a06d62-564f-5d2c-9e5e-eb55a1c3fdf1'::uuid, 'Que signifie *verosímil* ?', 'mcq', '["Vraisemblable","Véritable","Vérifié","Invraisemblable"]'::jsonb, 0, 'Ce qui paraît vrai, même si c’est inventé.', 7),
    ('06e2bcdb-30f5-57a1-826e-4ddb624918e8'::uuid, '78a06d62-564f-5d2c-9e5e-eb55a1c3fdf1'::uuid, 'Quel auteur argentin a écrit *Ficciones* (1944) ?', 'mcq', '["Julio Cortázar","Ernesto Sabato","Juan Rulfo","Jorge Luis Borges"]'::jsonb, 3, 'Bibliothèques infinies et labyrinthes y questionnent le savoir.', 8),
    ('65de2cd7-84d7-563f-ab58-043b82ab8583'::uuid, '78a06d62-564f-5d2c-9e5e-eb55a1c3fdf1'::uuid, 'Dans *Pedro Páramo*, le village est peuplé de morts qui parlent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le roman de Juan Rulfo (1955) a inspiré tout le réalisme magique.', 9),
    ('7c6888b2-41fd-5a78-824c-2dfbb53e89c8'::uuid, '78a06d62-564f-5d2c-9e5e-eb55a1c3fdf1'::uuid, 'Que caractérise le réalisme magique ?', 'mcq', '["Un récit de science-fiction futuriste","L’extraordinaire raconté comme ordinaire","Un journal intime","Une enquête policière"]'::jsonb, 1, 'Chez García Márquez, une femme monte au ciel sans que personne s’en étonne.', 10),
    ('8ed22a65-9e8b-586c-8929-b47bc4fd10be'::uuid, '78a06d62-564f-5d2c-9e5e-eb55a1c3fdf1'::uuid, 'Quel temps suit *si* dans *Si el autor ___ contado solo los hechos…* ?', 'mcq', '["habría","haya","hubiera","había"]'::jsonb, 2, 'Irréel du passé : plus-que-parfait du subjonctif après *si*.', 11),
