    ('f58a4763-c40a-5d0e-9146-dcf5c2f5c1b0'::uuid, '269c8996-6d10-5f80-b908-aecf8fda3ced'::uuid, 'Après *como si*, quel temps emploie-t-on toujours ?', 'mcq', '["Le présent du subjonctif","L’indicatif","Le conditionnel","L’imparfait ou le plus-que-parfait du subjonctif"]'::jsonb, 3, '*Habla como si lo supiera todo.*', 8),
    ('ce85d722-afee-5d0e-bf31-20ca4c2efb75'::uuid, '269c8996-6d10-5f80-b908-aecf8fda3ced'::uuid, '*Quería que vengas* est correct en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Calque du français : il faut *Quería que vinieras*.', 9),
    ('1f4e0f84-39b9-52db-a230-809e5f7e6ae1'::uuid, '269c8996-6d10-5f80-b908-aecf8fda3ced'::uuid, '*No creo que lo hiciera él* : pourquoi l’imparfait du subjonctif après un présent ?', 'mcq', '["C’est une faute","La subordonnée parle d’un fait passé","Parce que *creer* l’exige toujours","Parce que la phrase est négative"]'::jsonb, 1, 'Le temps suit alors l’époque de l’action.', 10),
    ('60d35898-977c-5db6-8b89-a17f08f4d6ed'::uuid, '269c8996-6d10-5f80-b908-aecf8fda3ced'::uuid, 'Mets au passé : *Aunque llueva, saldré.*', 'mcq', '["Aunque lloviera, saldría","Aunque llueva, saldría","Aunque llovía, saldré","Aunque lloverá, salía"]'::jsonb, 0, 'Concession hypothétique au passé : imparfait du subjonctif + conditionnel.', 11),
    ('b340b5b0-2692-566e-9bb2-0f725723ed4b'::uuid, '269c8996-6d10-5f80-b908-aecf8fda3ced'::uuid, 'La concordance des temps concerne aussi les propositions relatives.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle vaut pour toute subordonnée au subjonctif.', 12),
    ('4094c370-bb70-5305-9b15-6bb11a51681a'::uuid, '51c0134f-8323-5854-96da-119bd1f47e93'::uuid, 'Complète : *Si ___ tiempo, viajaría.*', 'mcq', '["tendría","tenga","tuviera","tengo"]'::jsonb, 2, 'Irréel du présent : imparfait du subjonctif + conditionnel.', 1),
    ('8f52c179-8e35-5116-896c-3b2afa5024df'::uuid, '51c0134f-8323-5854-96da-119bd1f47e93'::uuid, 'Quelle phrase exprime l’irréel du passé ?', 'mcq', '["Si hubiera sabido, habría venido","Si sabía, venía","Si sabré, vendré","Si supiera, vendría"]'::jsonb, 0, 'Plus-que-parfait du subjonctif + conditionnel passé.', 2),
    ('8db47817-39ec-569a-83cd-48eaaa932725'::uuid, '51c0134f-8323-5854-96da-119bd1f47e93'::uuid, '*Si llueve, me quedo* exprime…', 'mcq', '["Un irréel du passé","Un irréel du présent","Un regret","Une hypothèse réalisable"]'::jsonb, 3, '*Si* + présent de l’indicatif.', 3),
    ('5e889330-95d2-5880-8dd1-965c69e5b4c7'::uuid, '51c0134f-8323-5854-96da-119bd1f47e93'::uuid, 'Quelle phrase est fautive ?', 'mcq', '["Si llueve, me quedaré","Si tendría dinero, viajaría","Si tuviera dinero, viajaría","No sé si vendrá"]'::jsonb, 1, 'Jamais de conditionnel après *si* hypothétique.', 4),
    ('927b183b-39ff-5731-9804-d67c67de46d5'::uuid, '51c0134f-8323-5854-96da-119bd1f47e93'::uuid, 'Pourquoi *No sé si vendrá* est-il correct ?', 'mcq', '["Parce que *si* signifie ici « est-ce que »","Parce que *vendrá* est un subjonctif","Parce que la phrase est négative","C’est une exception régionale"]'::jsonb, 0, 'Dans l’interrogation indirecte, *si* accepte le futur.', 5),
    ('a43ff87b-7516-55b5-a2d6-040d78fc6f22'::uuid, '51c0134f-8323-5854-96da-119bd1f47e93'::uuid, 'Que signifie *De haberlo sabido, habría venido* ?', 'mcq', '["Pour l’avoir su, je suis venu","Si je l’avais su, je serais venu","Depuis que je le sais, je viens","Sachant cela, je viendrai"]'::jsonb, 1, '*De* + infinitif passé = hypothèse irréelle du passé.', 6),
    ('a5979a37-3a8e-5a91-8deb-d6873eb8585a'::uuid, '51c0134f-8323-5854-96da-119bd1f47e93'::uuid, '*Como no estudies, suspenderás* exprime…', 'mcq', '["Une cause","Une comparaison","Une menace, une condition","Un souhait"]'::jsonb, 2, '*Como* + subjonctif = si (menace).', 7),
