    ('6b8774f1-79b6-57cc-8c02-3a33d2305040'::uuid, '51c0134f-8323-5854-96da-119bd1f47e93'::uuid, '*Si hubiera estudiado, ahora estaría tranquilo* mélange deux époques.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Condition passée, résultat présent.', 9),
    ('4104ac50-7530-5a82-9098-7799a39e0fea'::uuid, '51c0134f-8323-5854-96da-119bd1f47e93'::uuid, 'Complète : *Me miró como si no me ___.*', 'mcq', '["conoce","conociera","conozca","conocería"]'::jsonb, 1, '*Como si* + imparfait du subjonctif.', 10),
    ('2cc5ceaa-b5f5-573e-bbf7-a12c9df71e91'::uuid, '51c0134f-8323-5854-96da-119bd1f47e93'::uuid, 'Quelle tournure signifie « au cas où » et exige le subjonctif ?', 'mcq', '["por si","como si","en caso de que","si no"]'::jsonb, 2, '*En caso de que llueva, lo aplazamos.*', 11),
    ('91b3ae99-c407-5ed0-9385-9a959c155bb1'::uuid, '51c0134f-8323-5854-96da-119bd1f47e93'::uuid, 'Dans l’irréel du passé, la principale peut aussi être au plus-que-parfait du subjonctif : *Si hubiera sabido, hubiera venido*.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les deux formes, *habría venido* et *hubiera venido*, sont admises.', 12),
    ('bb78058b-45a5-5d26-be34-51bfd794d214'::uuid, '7d093d59-4a0a-514f-875b-bfa7a6495bd9'::uuid, '*Aunque llueve, salgo* signifie…', 'mcq', '["Même s’il pleuvait, je sortirais","Il pleut, mais je sors quand même","S’il pleut, je ne sors pas","Même s’il pleut demain, je sortirai"]'::jsonb, 1, '*Aunque* + indicatif : fait réel, reconnu.', 1),
    ('b6063403-337c-5846-b729-157fe8003ac4'::uuid, '7d093d59-4a0a-514f-875b-bfa7a6495bd9'::uuid, '*Aunque llueva, saldré* signifie…', 'mcq', '["Même s’il pleut, je sortirai","Il pleut et je sors","Il a plu, je suis sorti","Parce qu’il pleut, je sortirai"]'::jsonb, 0, '*Aunque* + subjonctif : fait possible, « même si ».', 2),
    ('e893e059-eb98-50d8-9570-bd3be2000fdd'::uuid, '7d093d59-4a0a-514f-875b-bfa7a6495bd9'::uuid, 'Complète : *Por muy difícil que ___, lo intentaré.*', 'mcq', '["es","será","sería","sea"]'::jsonb, 3, '*Por muy* + adjectif + *que* + subjonctif.', 3),
    ('a0596bcc-5b92-555c-9446-fabfc4a5f013'::uuid, '7d093d59-4a0a-514f-875b-bfa7a6495bd9'::uuid, 'Comment dit-on « malgré le froid » ?', 'mcq', '["a pesar el frío","aunque el frío","a pesar del frío","sin embargo el frío"]'::jsonb, 2, '*A pesar de* + nom ; *de + el = del*.', 4),
    ('15add13a-df04-525d-9c45-2393dfc0a613'::uuid, '7d093d59-4a0a-514f-875b-bfa7a6495bd9'::uuid, 'Que signifie *sin embargo* ?', 'mcq', '["Cependant","Sans obstacle","Sans doute","C’est pourquoi"]'::jsonb, 0, 'Connecteur d’opposition.', 5),
    ('ba8464eb-3aad-5336-a509-7b61460ffb77'::uuid, '7d093d59-4a0a-514f-875b-bfa7a6495bd9'::uuid, 'Quel connecteur signifie « en revanche » ?', 'mcq', '["sino","en cambio","aunque","por eso"]'::jsonb, 1, '*Mi hermana, en cambio, habla con todos.*', 6),
    ('c5a05c76-2254-5205-8080-ed8e28047d50'::uuid, '7d093d59-4a0a-514f-875b-bfa7a6495bd9'::uuid, 'Complète : *No es rojo, ___ azul.*', 'mcq', '["pero","sin embargo","aunque","sino"]'::jsonb, 3, '*Sino* rectifie après une négation.', 7),
    ('150ec103-73b4-52c4-924b-bb22bb99403f'::uuid, '7d093d59-4a0a-514f-875b-bfa7a6495bd9'::uuid, '*Aunque tuviera dinero, no lo compraría* exprime…', 'mcq', '["Un fait réel","Une cause","Une hypothèse irréelle","Un ordre"]'::jsonb, 2, 'Imparfait du subjonctif : même si j’avais (ce qui n’est pas le cas).', 8),
    ('a10b0e12-6c70-5967-95de-7543b8706be1'::uuid, '7d093d59-4a0a-514f-875b-bfa7a6495bd9'::uuid, '*Por mucho que insistas, no iré* : le subjonctif est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Por mucho que* + subjonctif = « tu auras beau insister ».', 9),
    ('40447a2a-a425-5e6f-82bd-a4f37db411ac'::uuid, '7d093d59-4a0a-514f-875b-bfa7a6495bd9'::uuid, '*Aun sabiéndolo, no dijo nada* signifie…', 'mcq', '["Tout en le sachant / même en le sachant, il n’a rien dit","Parce qu’il le savait, il n’a rien dit","Il ne le savait pas encore","Dès qu’il l’a su, il a parlé"]'::jsonb, 0, '*Aun* + gérondif exprime la concession.', 10),
    ('041dc23c-cf60-52ee-8602-91a7d9d6a45e'::uuid, '7d093d59-4a0a-514f-875b-bfa7a6495bd9'::uuid, 'Quel connecteur signifie « alors que » (opposition) ?', 'mcq', '["ya que","mientras que","para que","así que"]'::jsonb, 1, '*Unos ganan mucho, mientras que otros no tienen nada.*', 11),
    ('3432c453-d46a-5721-9361-dda6401a0583'::uuid, '7d093d59-4a0a-514f-875b-bfa7a6495bd9'::uuid, 'On peut employer *sino* sans négation dans la première partie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Sino* s’emploie seulement après une négation ; sinon, on dit *pero*.', 12),
    ('8f4f8b5a-c8c2-5c06-9128-012719de283b'::uuid, '5b7c19af-f840-52d7-a534-ffd57f22ea91'::uuid, 'Complète : *Te lo explico para que lo ___.*', 'mcq', '["entiendes","entiendas","entender","entenderás"]'::jsonb, 1, '*Para que* + subjonctif, toujours.', 1),
    ('343ea765-aad0-5b62-afae-736035d68a24'::uuid, '5b7c19af-f840-52d7-a534-ffd57f22ea91'::uuid, '*Estudio para aprobar* : pourquoi l’infinitif ?', 'mcq', '["Le sujet est le même","C’est un ordre","C’est une condition","L’action est passée"]'::jsonb, 0, 'Même sujet : *para* + infinitif.', 2),
    ('e2e30f97-b5e2-5fe3-891b-67e3d126a304'::uuid, '5b7c19af-f840-52d7-a534-ffd57f22ea91'::uuid, 'Que signifie *a no ser que* ?', 'mcq', '["À condition que","Pour que","À moins que","Bien que"]'::jsonb, 2, '*Saldremos, a no ser que llueva.*', 3),
    ('9217961f-35f6-5cdb-8248-0c17ef5ce1e7'::uuid, '5b7c19af-f840-52d7-a534-ffd57f22ea91'::uuid, '*Siempre que viene, trae flores* signifie…', 'mcq', '["À condition qu’il vienne, il apporte des fleurs","Il ne vient jamais sans fleurs","Il viendra toujours avec des fleurs","Chaque fois qu’il vient, il apporte des fleurs"]'::jsonb, 3, '*Siempre que* + indicatif = chaque fois que.', 4),
    ('16456009-b0c6-52c0-ab16-f4a82b3810be'::uuid, '5b7c19af-f840-52d7-a534-ffd57f22ea91'::uuid, '*Puedes salir siempre que vuelvas pronto* signifie…', 'mcq', '["Tu peux sortir à condition de rentrer tôt","Tu sors chaque fois que tu rentres tôt","Tu es toujours sorti tôt","Tu dois rentrer tôt car tu sors"]'::jsonb, 0, '*Siempre que* + subjonctif = à condition que.', 5),
    ('768ba452-b2ed-546c-ac47-e344db321450'::uuid, '5b7c19af-f840-52d7-a534-ffd57f22ea91'::uuid, 'Complète : *Salió sin que nadie lo ___.*', 'mcq', '["vio","ve","viera","vería"]'::jsonb, 2, '*Sin que* + subjonctif, ici à l’imparfait par concordance.', 6),
    ('b09e76e5-328b-59cf-b863-fca70a18bdb0'::uuid, '5b7c19af-f840-52d7-a534-ffd57f22ea91'::uuid, 'Mets au passé : *Me lo presta con tal de que se lo devuelva.*', 'mcq', '["Me lo prestó con tal de que se lo devuelva","Me lo prestó con tal de que se lo devolviera","Me lo prestó con tal de que se lo devolvía","Me lo prestó con tal de que se lo devolvería"]'::jsonb, 1, 'Concordance : imparfait du subjonctif.', 7),
    ('fcc5d03d-dd37-524f-8322-1a7f9ca7ee75'::uuid, '5b7c19af-f840-52d7-a534-ffd57f22ea91'::uuid, 'Quelle tournure de but appartient au registre soutenu ?', 'mcq', '["para","a","a fin de que","por"]'::jsonb, 2, '*Se tomaron medidas a fin de que no se repitiera.*', 8),
    ('218a5e88-b326-575e-b02c-fb6498d15959'::uuid, '5b7c19af-f840-52d7-a534-ffd57f22ea91'::uuid, '*Lo digo para que lo sabes* est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut le subjonctif : *para que lo sepas*.', 9),
    ('099de74d-b0ca-57aa-9cb9-2812bc5fbfc1'::uuid, '5b7c19af-f840-52d7-a534-ffd57f22ea91'::uuid, 'Que signifie *Vine a verte* ?', 'mcq', '["Je suis venu te voir","Je viens de te voir","Je te verrai venir","Je t’ai vu venir"]'::jsonb, 0, 'Après un verbe de mouvement, le but s’exprime avec *a* + infinitif.', 10),
    ('dfa06891-7add-52c0-be6f-802f010f0c5d'::uuid, '5b7c19af-f840-52d7-a534-ffd57f22ea91'::uuid, 'Quelle conjonction signifie « au cas où » et exige le subjonctif ?', 'mcq', '["por si","siempre que","sin que","en caso de que"]'::jsonb, 3, '*En caso de que no puedas, avísame.*', 11),
    ('dfc38642-631c-5386-9790-4cc8539fa317'::uuid, '5b7c19af-f840-52d7-a534-ffd57f22ea91'::uuid, '*Con tal de que* exige le subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme toutes les conjonctions de condition : *con tal de que me lo devuelvas*.', 12),
    ('36f57b90-a3ad-52af-b42f-7bdd8ec9bf28'::uuid, '35214606-2adc-5793-b394-422853701e47'::uuid, 'Rapporte au passé : *«Tengo hambre»*.', 'mcq', '["Dijo que tiene hambre","Dijo que tenía hambre","Dijo que tendrá hambre","Dijo que tuviera hambre"]'::jsonb, 1, 'Présent → imparfait quand le verbe introducteur est au passé.', 1),
    ('a1423491-0ed0-57e4-899f-40bd82b6e7db'::uuid, '35214606-2adc-5793-b394-422853701e47'::uuid, 'Rapporte au passé : *«Vendré»*.', 'mcq', '["Dijo que vendrá","Dijo que viene","Dijo que vendría","Dijo que viniera"]'::jsonb, 2, 'Futur → conditionnel.', 2),
    ('9ac5bdb4-afc8-5ca5-906d-063ab73d5580'::uuid, '35214606-2adc-5793-b394-422853701e47'::uuid, 'Rapporte au passé : *«Ven»*.', 'mcq', '["Me pidió que fuera","Me pidió de ir","Me pidió que ven","Me pidió que iba"]'::jsonb, 0, 'L’impératif devient *que* + subjonctif, à l’imparfait par concordance ; *venir* devient souvent *ir*.', 3),
    ('c3dc1b1a-ee90-5cd8-be20-d5fe5facda6e'::uuid, '35214606-2adc-5793-b394-422853701e47'::uuid, 'Que devient *mañana* dans un discours rapporté au passé ?', 'mcq', '["el día anterior","aquel día","entonces","al día siguiente"]'::jsonb, 3, '*Ayer* devient *el día anterior*, *hoy* devient *aquel día*.', 4),
    ('9f3b94cc-06b1-513d-a7fe-5259780e8f09'::uuid, '35214606-2adc-5793-b394-422853701e47'::uuid, 'Rapporte : *«¿Dónde vives?»* (au passé).', 'mcq', '["Me preguntó donde vivía","Me preguntó dónde vivía","Me preguntó que dónde vives","Me preguntó si dónde vivía"]'::jsonb, 1, 'L’interrogatif garde son accent, même sans point d’interrogation.', 5),
    ('7cc5f4a5-c0ac-5051-99dd-0b7189ebcacb'::uuid, '35214606-2adc-5793-b394-422853701e47'::uuid, 'Comment rapporter une question totale (*«¿Vienes?»*) ?', 'mcq', '["Avec *que* + subjonctif","Avec *cuál*","Avec *si* + indicatif","Avec *qué*"]'::jsonb, 2, '*Me preguntó si iba.*', 6),
    ('77ba8f8e-d696-5ea0-bf64-b4ad281edaf9'::uuid, '35214606-2adc-5793-b394-422853701e47'::uuid, 'Rapporte au passé : *«He terminado»*.', 'mcq', '["Dijo que había terminado","Dijo que ha terminado","Dijo que terminara","Dijo que terminaría"]'::jsonb, 0, 'Passé composé → plus-que-parfait.', 7),
    ('70b200e0-59b5-5112-804a-0b6f8917ef05'::uuid, '35214606-2adc-5793-b394-422853701e47'::uuid, '*Me dijo de venir* est correct en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Calque du français : *Me dijo que viniera*.', 8),
    ('4e3a8908-e7ab-57d7-b422-14d2afd75121'::uuid, '35214606-2adc-5793-b394-422853701e47'::uuid, 'Si le verbe introducteur est au présent, les temps…', 'mcq', '["Reculent tous d’un cran","Passent au subjonctif","Passent au futur","Ne changent pas"]'::jsonb, 3, '*Dice que está cansado.*', 9),
    ('ad4ed08b-31e4-5dab-bd03-18add7e085a4'::uuid, '35214606-2adc-5793-b394-422853701e47'::uuid, 'Que devient *aquí* au style indirect passé ?', 'mcq', '["allí","aquí mismo","acá","ahí dentro"]'::jsonb, 0, 'Le repère de lieu s’éloigne : *aquí* → *allí*.', 10),
    ('1f8681ed-1fe8-51fc-b40f-a832b1daabfd'::uuid, '35214606-2adc-5793-b394-422853701e47'::uuid, 'Rapporte au passé : *«No gritéis»*.', 'mcq', '["Nos dijo que no gritemos","Nos dijo que no gritáramos","Nos dijo de no gritar","Nos dijo que no gritábamos"]'::jsonb, 1, 'Défense rapportée : *que no* + imparfait du subjonctif.', 11),
    ('6516ca14-e48a-5720-854d-047f5f2a0aa4'::uuid, '35214606-2adc-5793-b394-422853701e47'::uuid, 'L’imparfait du style direct reste à l’imparfait au style indirect.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*«Vivía allí»* → *Dijo que vivía allí*.', 12),
    ('24ab416c-1fb5-57c2-9673-7594c43e899a'::uuid, '221c95b7-ee5e-517c-a6a4-6c13bcbe5a9a'::uuid, 'Comment traduire « C’est ici que je suis né » ?', 'mcq', '["Es aquí que nací","Es aquí donde nací","Es aquí cuando nací","Está aquí donde nací"]'::jsonb, 1, 'Pour un lieu, le relatif est *donde*.', 1),
    ('e1a5d741-6cb4-5505-a9fb-eeea9d940d32'::uuid, '221c95b7-ee5e-517c-a6a4-6c13bcbe5a9a'::uuid, 'Comment traduire « C’est en 1492 que Colomb est arrivé » ?', 'mcq', '["Es en 1492 que llegó Colón","Fue en 1492 donde llegó Colón","Fue en 1492 cuando llegó Colón","Era 1492 que llegó Colón"]'::jsonb, 2, 'Moment → *cuando* ; *ser* au temps de l’action.', 2),
    ('d0e43a1c-ae4f-5829-b900-f04a879184ff'::uuid, '221c95b7-ee5e-517c-a6a4-6c13bcbe5a9a'::uuid, 'Complète : *___ yo quien lo dice.*', 'mcq', '["Soy","Es","Está","Fue"]'::jsonb, 0, '*Ser* s’accorde en personne avec l’élément mis en relief.', 3),
    ('f305ecd0-4dc5-5d63-a2fc-52da5191134e'::uuid, '221c95b7-ee5e-517c-a6a4-6c13bcbe5a9a'::uuid, 'Complète : *Fueron ellos ___ llamaron.*', 'mcq', '["que","cual","quien","quienes"]'::jsonb, 3, 'Personne au pluriel → *quienes* (ou *los que*).', 4),
    ('ef366d4d-21b3-59ab-9225-c1958283788c'::uuid, '221c95b7-ee5e-517c-a6a4-6c13bcbe5a9a'::uuid, 'Que signifie *No sabes lo difícil que es* ?', 'mcq', '["Tu ne sais pas ce qui est difficile","Tu ne sais pas à quel point c’est difficile","Ce n’est pas difficile, tu sais","Tu ne sais pas que c’est difficile"]'::jsonb, 1, '*Lo* + adjectif + *que* exprime l’intensité.', 5),
    ('3d1d95b3-ecb1-5c49-9313-10af052b9928'::uuid, '221c95b7-ee5e-517c-a6a4-6c13bcbe5a9a'::uuid, 'Complète : *No imaginas lo ___ que estaban ellas.*', 'mcq', '["cansado","cansados","cansadas","cansada"]'::jsonb, 2, 'L’adjectif s’accorde avec le nom : *ellas → cansadas*.', 6),
    ('1e59bf5f-3a22-5033-b706-7e1e85156d6d'::uuid, '221c95b7-ee5e-517c-a6a4-6c13bcbe5a9a'::uuid, '*Lo que quiero es descansar* met en relief…', 'mcq', '["Descansar","Quiero","Lo","Rien"]'::jsonb, 0, 'L’ordre inversé met en valeur ce qui suit *ser*.', 7),
    ('ee3fefaf-1362-509b-9960-ea41cc1f3550'::uuid, '221c95b7-ee5e-517c-a6a4-6c13bcbe5a9a'::uuid, 'Quel relatif s’emploie pour mettre en relief une manière ?', 'mcq', '["donde","cuando","quien","como"]'::jsonb, 3, '*Es así como se hace.*', 8),
    ('ff394d9b-de00-5be9-aeab-de608f3c50cb'::uuid, '221c95b7-ee5e-517c-a6a4-6c13bcbe5a9a'::uuid, 'Dans la mise en relief, *ser* se met au temps de l’action.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Fue ayer cuando lo vi.*', 9),
    ('44b5de9e-2fd7-533e-a3f9-fb845b143f2c'::uuid, '221c95b7-ee5e-517c-a6a4-6c13bcbe5a9a'::uuid, 'Que signifie *El caso es que nadie lo sabía* ?', 'mcq', '["Le cas est que personne ne le savait","Toujours est-il que personne ne le savait","Dans ce cas, personne ne le savait","Il se peut que personne ne le sache"]'::jsonb, 1, 'Formule d’insistance de l’oral et de l’écrit.', 10),
    ('bd742aa1-02e2-5dcb-911f-38f521598836'::uuid, '221c95b7-ee5e-517c-a6a4-6c13bcbe5a9a'::uuid, 'Que signifie *Esto sí que es importante* ?', 'mcq', '["Ceci est-il important ?","Si c’est important","Ça, c’est vraiment important","C’est aussi important"]'::jsonb, 2, '*Sí que* renforce l’affirmation.', 11),
    ('2b196795-e807-5f68-ba5f-eba1509e7f8f'::uuid, '221c95b7-ee5e-517c-a6a4-6c13bcbe5a9a'::uuid, '*Es aquí que nací* est une phrase correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Calque du français : il faut *Es aquí donde nací*.', 12)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('allemand', 'allemand', 'allemand', 'espagnol', 'espagnol', 'espagnol');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('allemand', 'allemand', 'allemand', 'espagnol', 'espagnol', 'espagnol')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 386 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 386 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
